'use client';

import { useState, useEffect, useCallback } from 'react';
import { Users, Search, Phone, MapPin, UserCircle, History, ExternalLink, Loader2, Plus, AlertCircle, UserPlus } from 'lucide-react';
import { getCustomersList, createCustomer } from '@/app/actions/customers';
import Link from 'next/link';
import clsx from 'clsx';

interface CustomerGroup {
    name: string;
}

interface Customer {
    id: string;
    name: string;
    phone: string | null;
    address: string | null;
    balance: number | string;
    type: string;
    group?: CustomerGroup | null;
}

export default function CustomersPage() {
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [search, setSearch] = useState('');
    const [loading, setLoading] = useState(true);

    // Add Customer Modal
    const [showAddModal, setShowAddModal] = useState(false);
    const [newCustomer, setNewCustomer] = useState({ name: '', phone: '', address: '' });
    const [creating, setCreating] = useState(false);
    const [formError, setFormError] = useState<string | null>(null);

    const loadCustomers = useCallback(async (showLoading = false) => {
        if (showLoading) setLoading(true);
        const data = await getCustomersList();
        setCustomers(data);
        setLoading(false);
    }, []);

    useEffect(() => {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        loadCustomers(false);
    }, [loadCustomers]);

    const handleCreateCustomer = async () => {
        if (!newCustomer.name.trim()) {
            setFormError('Customer name is required.');
            return;
        }
        setCreating(true);
        setFormError(null);

        const result = await createCustomer({
            name: newCustomer.name,
            phone: newCustomer.phone || undefined,
            address: newCustomer.address || undefined,
        });

        if (result.success) {
            setShowAddModal(false);
            setNewCustomer({ name: '', phone: '', address: '' });
            loadCustomers(true);
        } else {
            setFormError(result.error || 'Failed to create customer.');
        }
        setCreating(false);
    };

    const handleSearchChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setSearch(e.target.value), []);
    const handleOpenAddModal = useCallback(() => setShowAddModal(true), []);
    const handleCloseAddModal = useCallback(() => {
        setShowAddModal(false);
        setFormError(null);
        setNewCustomer({ name: '', phone: '', address: '' });
    }, []);
    const handleNewCustomerNameChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setNewCustomer(prev => ({ ...prev, name: e.target.value })), []);
    const handleNewCustomerPhoneChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setNewCustomer(prev => ({ ...prev, phone: e.target.value })), []);
    const handleNewCustomerAddressChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setNewCustomer(prev => ({ ...prev, address: e.target.value })), []);

    const filtered = customers.filter(c =>
        c.name.toLowerCase().includes(search.toLowerCase()) ||
        (c.phone && c.phone.includes(search))
    );

    const totalDebt = customers.reduce((sum, c) => sum + (Number(c.balance) > 0 ? Number(c.balance) : 0), 0);

    return (
        <div className="space-y-6 max-w-7xl mx-auto">
            {/* Header */}
            <div className="flex flex-col md:flex-row justify-between gap-4">
                <div>
                    <h2 className="text-3xl font-black tracking-tight text-foreground flex items-center gap-3">
                        <Users size={32} className="text-primary" />
                        العملاء <span className="text-muted-foreground font-normal">/ Customers</span>
                    </h2>
                    <p className="text-muted-foreground mt-1 text-lg">Manage and analyze your customer base</p>
                </div>

                <div className="flex items-center gap-3">
                    <div className="relative group flex-1 md:w-80">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground group-focus-within:text-primary transition-colors" size={20} />
                        <input
                            type="text"
                            placeholder="Search by name or phone..."
                            value={search}
                            onChange={handleSearchChange}
                            className="w-full pl-10 pr-4 py-3 bg-card border border-border rounded-xl focus:ring-2 focus:ring-primary/20 outline-none transition-all shadow-sm"
                        />
                    </div>
                    <button
                        onClick={handleOpenAddModal}
                        className="flex items-center gap-2 px-5 py-3 bg-primary text-primary-foreground rounded-xl font-bold text-sm hover:bg-primary/90 hover:shadow-lg hover:shadow-primary/20 transition-all shadow-md whitespace-nowrap"
                    >
                        <UserPlus size={18} />
                        Add Customer
                    </button>
                </div>
            </div>

            {/* Stats Bar */}
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                <div className="bg-card border border-border rounded-2xl p-4">
                    <div className="text-sm text-muted-foreground font-medium">Total Customers</div>
                    <div className="text-2xl font-black mt-1">{customers.length}</div>
                </div>
                <div className="bg-card border border-border rounded-2xl p-4">
                    <div className="text-sm text-muted-foreground font-medium">With Outstanding Debt</div>
                    <div className="text-2xl font-black text-red-600 mt-1">{customers.filter(c => Number(c.balance) > 0).length}</div>
                </div>
                <div className="bg-card border border-border rounded-2xl p-4 col-span-2 md:col-span-1">
                    <div className="text-sm text-muted-foreground font-medium">Total Owed</div>
                    <div className="text-2xl font-black text-red-600 mt-1">EGP {totalDebt.toLocaleString()}</div>
                </div>
            </div>

            {/* Customer Grid */}
            {loading ? (
                <div className="flex flex-col items-center justify-center h-64 gap-4">
                    <Loader2 className="animate-spin text-primary" size={48} />
                    <p className="text-muted-foreground font-medium animate-pulse">Fetching customer intelligence...</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {filtered.map((customer, idx) => (
                        <div key={idx} className="bg-card border border-border rounded-2xl p-5 hover:border-primary/50 transition-all hover:shadow-lg group flex flex-col relative overflow-hidden">
                            <div className="absolute top-0 right-0 p-3 opacity-10 group-hover:opacity-20 transition-opacity">
                                <Users size={64} />
                            </div>

                            <div className="flex items-start gap-4 mb-4 relative z-10">
                                <div className={clsx(
                                    "p-3 rounded-xl",
                                    customer.type === 'USER' ? "bg-primary/10 text-primary" : "bg-orange-500/10 text-orange-600"
                                )}>
                                    <UserCircle size={28} />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-center gap-2 flex-wrap">
                                        <h3 className="font-black text-lg line-clamp-1">{customer.name}</h3>
                                        {/* Balance badge right next to the name */}
                                        <span className={clsx(
                                            "text-xs font-black px-2 py-0.5 rounded-full whitespace-nowrap",
                                            Number(customer.balance) > 0
                                                ? "bg-red-500/10 text-red-600 border border-red-500/20"
                                                : "bg-green-500/10 text-green-600 border border-green-500/20"
                                        )}>
                                            {Number(customer.balance) > 0
                                                ? `Owes EGP ${Number(customer.balance).toLocaleString()}`
                                                : 'Settled'}
                                        </span>
                                        {customer.group && (
                                            <span className="bg-primary/10 text-primary text-[10px] font-black px-1.5 py-0.5 rounded uppercase tracking-wider">{customer.group.name}</span>
                                        )}
                                    </div>
                                    <div className="flex items-center gap-1.5 text-muted-foreground text-sm mt-0.5">
                                        <Phone size={14} />
                                        <span>{customer.phone || 'No phone'}</span>
                                    </div>
                                </div>
                            </div>

                            <div className="flex items-start gap-2 text-muted-foreground text-sm mb-6 flex-1 italic line-clamp-2">
                                <MapPin size={16} className="shrink-0 mt-0.5" />
                                <span>{customer.address || "No address on file"}</span>
                            </div>

                            <div className="flex items-center justify-between pt-4 border-t border-border group">
                                <div className="flex items-center gap-2 text-xs font-bold uppercase tracking-tight text-muted-foreground">
                                    <History size={14} />
                                    <span>History Available</span>
                                </div>
                                <Link prefetch={false}
                                    href={`/customers/profile?id=${customer.id}`}
                                    className="flex items-center gap-1.5 px-4 py-2 bg-secondary text-foreground rounded-lg font-bold text-sm hover:bg-primary hover:text-primary-foreground transition-all shadow-sm"
                                >
                                    View Full Profile Ledger
                                    <ExternalLink size={14} />
                                </Link>
                            </div>
                        </div>
                    ))}

                    {filtered.length === 0 && (
                        <div className="col-span-full py-20 text-center bg-secondary/10 border border-dashed border-border rounded-3xl">
                            <Users size={48} className="mx-auto text-muted-foreground/30 mb-4" />
                            <h3 className="text-xl font-bold text-muted-foreground">No customers found</h3>
                            <p className="text-sm text-muted-foreground">Try searching with a different name or phone number</p>
                        </div>
                    )}
                </div>
            )}

            {/* Add Customer Modal */}
            {showAddModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-card w-full max-w-md rounded-[2rem] border border-border shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
                        <div className="p-8 pb-6 flex flex-col items-center text-center gap-4">
                            <div className="w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center text-primary">
                                <UserPlus size={32} strokeWidth={2} />
                            </div>
                            <div>
                                <h3 className="text-2xl font-black tracking-tight mb-1">New Customer</h3>
                                <p className="text-muted-foreground font-medium text-sm">Add a new customer to your database</p>
                            </div>
                        </div>

                        <div className="px-8 pb-6 space-y-4">
                            {formError && (
                                <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-xl text-red-600 text-xs font-bold flex items-center gap-2">
                                    <AlertCircle size={16} className="shrink-0" />
                                    {formError}
                                </div>
                            )}

                            <div>
                                <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground mb-1.5 block">Customer Name *</label>
                                <input
                                    type="text"
                                    placeholder="e.g. Ahmed Mohamed"
                                    value={newCustomer.name}
                                    onChange={handleNewCustomerNameChange}
                                    className="w-full p-3 bg-background border border-border/60 rounded-xl text-sm font-medium outline-none focus:border-primary/50 focus:ring-2 focus:ring-primary/10 transition-all"
                                    autoFocus
                                />
                            </div>

                            <div>
                                <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground mb-1.5 block">Phone (Optional)</label>
                                <input
                                    type="tel"
                                    placeholder="e.g. 01012345678"
                                    value={newCustomer.phone}
                                    onChange={handleNewCustomerPhoneChange}
                                    className="w-full p-3 bg-background border border-border/60 rounded-xl text-sm font-medium outline-none focus:border-primary/50 focus:ring-2 focus:ring-primary/10 transition-all"
                                />
                            </div>

                            <div>
                                <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground mb-1.5 block">Address (Optional)</label>
                                <input
                                    type="text"
                                    placeholder="e.g. Cairo, Egypt"
                                    value={newCustomer.address}
                                    onChange={handleNewCustomerAddressChange}
                                    className="w-full p-3 bg-background border border-border/60 rounded-xl text-sm font-medium outline-none focus:border-primary/50 focus:ring-2 focus:ring-primary/10 transition-all"
                                />
                            </div>
                        </div>

                        <div className="p-6 bg-secondary/20 flex gap-3">
                            <button
                                onClick={handleCloseAddModal}
                                className="flex-1 py-4 bg-background border border-border/60 rounded-xl font-bold hover:bg-secondary transition-colors"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handleCreateCustomer}
                                disabled={creating}
                                className="flex-1 py-4 bg-primary text-primary-foreground rounded-xl font-black shadow-lg shadow-primary/20 hover:bg-primary/90 hover:scale-[1.02] transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                            >
                                {creating ? (
                                    <Loader2 className="animate-spin" size={20} />
                                ) : (
                                    <>
                                        <Plus size={18} strokeWidth={3} />
                                        Create Customer
                                    </>
                                )}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { Suspense, useState, useEffect, useCallback } from 'react';
import { useSearchParams } from 'next/navigation';
import {
    User, Phone, MapPin, ShoppingBag,
    ArrowLeft, CreditCard, Clock, Receipt, Printer,
    ChevronRight, Loader2,
    CalendarDays, Tag
} from 'lucide-react';
import { getCustomerProfile } from '@/app/actions/customers';
import Link from 'next/link';
import clsx from 'clsx';

interface InvoiceItem {
    quantity: number;
    product: string;
    total: number | string;
}

interface Invoice {
    id: string;
    date: string | Date;
    method: string;
    seller: string;
    total: number | string;
    paid: number | string;
    currentBalance: number;
    items: InvoiceItem[];
}

interface CustomerProfile {
    name: string;
    phone: string;
    address: string;
    type: string;
    balance: number;
    joinedAt: string | Date | null;
}

interface ProfileData {
    profile: CustomerProfile;
    invoices: Invoice[];
}

function ProfileContent() {
    const searchParams = useSearchParams();
    const id = searchParams.get('id');

    const [data, setData] = useState<ProfileData | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (id) {
            getCustomerProfile(id).then(res => {
                setData(res);
                setLoading(false);
            });
        }
    }, [id]);

    if (loading) {
        return (
            <div className="flex flex-col items-center justify-center h-[80vh] gap-4">
                <Loader2 className="animate-spin text-primary" size={64} />
                <p className="text-muted-foreground font-black text-xl animate-pulse">Reconstructing Customer History...</p>
            </div>
        );
    }

    if (!data) return <div>Customer not found</div>;

    const { profile, invoices } = data;
    const totalSpent = invoices.reduce((sum: number, inv: Invoice) => sum + Number(inv.total), 0);

    const handlePrintStatement = useCallback(() => {
        const printContents = document.getElementById('print-statement-content');
        if (printContents) {
            const originalContents = document.body.innerHTML;
            document.body.innerHTML = printContents.innerHTML;
            window.print();
            document.body.innerHTML = originalContents;
            window.location.reload(); // Reload to restore React state since DOM manipulation breaks it
        }
    }, []);

    return (
        <div className="space-y-8 animate-in fade-in duration-700 max-w-7xl mx-auto pb-20">
            {/* Nav Header */}
            <div className="flex items-center justify-between">
                <Link href="/customers" prefetch={false} className="flex items-center gap-2 text-muted-foreground hover:text-primary transition-colors font-bold group">
                    <div className="p-2 rounded-full group-hover:bg-primary/10 transition-colors">
                        <ArrowLeft size={20} />
                    </div>
                    Back to Customers
                </Link>
                <div className="flex items-center gap-2">
                    <button 
                        onClick={handlePrintStatement}
                        className="px-4 py-2 flex items-center gap-2 bg-secondary text-foreground hover:bg-primary hover:text-primary-foreground font-bold rounded-xl transition-all shadow-sm mr-2"
                    >
                        <Printer size={16} />
                        Print Statement
                    </button>
                    <div className={clsx(
                        "px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest border",
                        profile.type === 'USER' ? "bg-primary/10 text-primary border-primary/20" : "bg-orange-500/10 text-orange-600 border-orange-500/20"
                    )}>
                        {profile.type} ACCOUNT
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                {/* Left Column: Profile Card */}
                <div className="lg:col-span-4 space-y-6">
                    <div className="bg-card border border-border rounded-3xl p-8 relative overflow-hidden shadow-xl">
                        <div className="absolute top-0 right-0 p-8 text-primary/5 pointer-events-none">
                            <User size={160} />
                        </div>

                        <div className="flex flex-col items-center text-center relative z-10">
                            <div className="w-24 h-24 bg-gradient-to-br from-primary to-orange-600 rounded-3xl flex items-center justify-center shadow-lg mb-4 text-white font-black text-4xl transform rotate-3 hover:rotate-0 transition-transform">
                                {profile.name[0]}
                            </div>
                            <h2 className="text-3xl font-black tracking-tight mb-1">{profile.name}</h2>
                            <p className="text-muted-foreground flex items-center gap-2 font-medium">
                                <Phone size={14} className="text-primary" />
                                {profile.phone}
                            </p>
                        </div>

                        <div className="mt-8 space-y-6">
                            <div className="flex items-start gap-3 p-4 bg-secondary/30 rounded-2xl border border-border/50">
                                <MapPin className="text-primary shrink-0 mt-1" size={18} />
                                <div>
                                    <h4 className="text-[10px] font-black uppercase tracking-tighter text-muted-foreground mb-1">Primary Location / Address</h4>
                                    <p className="text-sm font-medium leading-relaxed">{profile.address}</p>
                                </div>
                            </div>

                            <div className="flex items-start gap-3 p-4 bg-secondary/30 rounded-2xl border border-border/50">
                                <CalendarDays className="text-primary shrink-0 mt-1" size={18} />
                                <div>
                                    <h4 className="text-[10px] font-black uppercase tracking-tighter text-muted-foreground mb-1">Relationship Started</h4>
                                    <p className="text-sm font-medium">
                                        {profile.joinedAt ? new Date(profile.joinedAt).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' }) : 'N/A'}
                                    </p>
                                </div>
                            </div>
                        </div>

                        <div className="mt-8 pt-8 border-t border-border grid grid-cols-2 gap-4">
                            <div className="text-center">
                                <div className="text-[10px] font-black uppercase text-muted-foreground mb-1">Lifetime Value</div>
                                <div className="text-2xl font-black text-green-600">EGP {totalSpent.toLocaleString()}</div>
                            </div>
                            <div className="text-center border-l border-border">
                                <div className="text-[10px] font-black uppercase text-muted-foreground mb-1">Current Balance</div>
                                <div className={clsx(
                                    "text-2xl font-black",
                                    profile.balance > 0 ? "text-red-600" : "text-green-600"
                                )}>
                                    EGP {Number(profile.balance).toLocaleString()}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Right Column: Purchase History */}
                <div className="lg:col-span-8 space-y-6">
                    <div className="flex items-center justify-between">
                        <h3 className="text-2xl font-black tracking-tight flex items-center gap-3">
                            <Receipt size={28} className="text-primary" />
                            Purchase History <span className="text-muted-foreground font-normal">({invoices.length})</span>
                        </h3>
                    </div>

                    <div className="space-y-4">
                        {invoices.map((invoice: Invoice) => (
                            <div key={invoice.id} className="bg-card border border-border rounded-3xl overflow-hidden shadow-sm hover:shadow-md transition-shadow group">
                                <div className="p-6 flex flex-col md:flex-row md:items-center justify-between gap-4 bg-secondary/10">
                                    <div className="flex items-center gap-4">
                                        <div className="p-3 bg-background border border-border rounded-2xl group-hover:border-primary/30 transition-colors">
                                            <ShoppingBag size={24} className="text-primary" />
                                        </div>
                                        <div>
                                            <div className="flex items-center gap-2">
                                                <h4 className="font-black text-lg">Invoice #{invoice.id.slice(-6).toUpperCase()}</h4>
                                                <span className="px-2 py-0.5 bg-green-500/10 text-green-600 text-[10px] font-black rounded-lg uppercase tracking-widest">Completed</span>
                                            </div>
                                            <div className="flex items-center gap-3 text-xs text-muted-foreground mt-1">
                                                <span className="flex items-center gap-1 font-medium italic"><Clock size={12} /> {new Date(invoice.date).toLocaleDateString()}</span>
                                                <span className="w-1 h-1 bg-border rounded-full" />
                                                <span className="flex items-center gap-1 font-medium"><CreditCard size={12} /> {invoice.method}</span>
                                                <span className="w-1 h-1 bg-border rounded-full" />
                                                <span className="flex items-center gap-1 font-medium italic underline">Sold by: {invoice.seller}</span>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="text-right flex flex-col items-end gap-1">
                                        <div className="text-xl font-black text-primary">EGP {Number(invoice.total).toLocaleString()}</div>
                                        <div className="flex items-center gap-2">
                                            <span className="text-[10px] font-bold text-muted-foreground uppercase">Paid: EGP {Number(invoice.paid).toLocaleString()}</span>
                                            {invoice.currentBalance > 0 && (
                                                <span className="px-2 py-0.5 bg-red-500/10 text-red-600 text-[9px] font-black rounded-full uppercase tracking-tighter italic">
                                                    Due: EGP {Number(invoice.currentBalance).toLocaleString()}
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                </div>
                                <div className="p-6 border-t border-border grid grid-cols-1 md:grid-cols-2 gap-4 bg-background">
                                    <div className="space-y-2">
                                        <div className="text-[10px] font-black uppercase text-muted-foreground tracking-widest flex items-center gap-2">
                                            <Tag size={12} /> Items Purchased
                                        </div>
                                        {invoice.items.map((item: InvoiceItem, i: number) => (
                                            <div key={i} className="flex justify-between items-center text-sm p-2 rounded-lg bg-secondary/20 border border-border/30">
                                                <div className="font-bold flex items-center gap-2">
                                                    <span className="w-6 h-6 flex items-center justify-center bg-primary/10 text-primary rounded-md text-[10px] font-black">{item.quantity}</span>
                                                    {item.product}
                                                </div>
                                                <div className="font-bold text-muted-foreground">EGP {Number(item.total).toLocaleString()}</div>
                                            </div>
                                        ))}
                                    </div>
                                    <div className="hidden md:flex flex-col justify-end items-end gap-3 opacity-30">
                                        <Link prefetch={false}
                                            href={`/invoices?search=${invoice.id.slice(-6).toUpperCase()}`}
                                            className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-primary hover:underline hover:opacity-100 transition-all"
                                        >
                                            View Original Receipt <ChevronRight size={10} />
                                        </Link>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>

                    {invoices.length === 0 && (
                        <div className="text-center py-20 bg-secondary/20 rounded-3xl border border-dashed border-border opacity-50">
                            <ShoppingBag className="mx-auto text-muted-foreground mb-4" size={48} />
                            <p className="font-bold">No purchase history found for this account.</p>
                        </div>
                    )}
                </div>
            </div>

            {/* Hidden Print Content for Statement of Account */}
            <div id="print-statement-content" className="hidden">
                <style>{`
                    @media print {
                        body { background: white; color: black; font-family: sans-serif; }
                        table { width: 100%; border-collapse: collapse; font-size: 12px; margin-top: 20px; }
                        th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
                        th { background-color: #f5f5f5; font-weight: bold; }
                        .text-right { text-align: right; }
                        .text-center { text-align: center; }
                        .font-bold { font-weight: bold; }
                        .header-box { border: 2px solid #333; padding: 15px; margin-bottom: 20px; }
                        .total-box { border: 2px solid #333; padding: 10px; margin-top: 20px; text-align: right; }
                        .watermark { position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%) rotate(-45deg); font-size: 8rem; color: rgba(0,0,0,0.05); z-index: -1; pointer-events: none; }
                    }
                `}</style>

                <div className="watermark">STATEMENT</div>

                <div className="header-box" dir="rtl">
                    <h1 className="text-2xl font-bold mb-4 text-center">كشف حساب عميل</h1>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <strong>اسم العميل:</strong> {profile.name}
                        </div>
                        <div>
                            <strong>التاريخ:</strong> {new Date().toLocaleDateString('en-GB')}
                        </div>
                        <div>
                            <strong>رقم الهاتف:</strong> {profile.phone || 'N/A'}
                        </div>
                        <div>
                            <strong>العنوان:</strong> {profile.address || 'N/A'}
                        </div>
                    </div>
                </div>

                <table dir="rtl">
                    <thead>
                        <tr>
                            <th className="text-center">م</th>
                            <th>التاريخ</th>
                            <th>رقم الفاتورة</th>
                            <th className="text-right">قيمة الفاتورة</th>
                            <th className="text-right">المدفوع</th>
                            <th className="text-right">المتبقي (المديونية)</th>
                        </tr>
                    </thead>
                    <tbody>
                        {invoices.map((inv: any, idx: number) => (
                            <tr key={inv.id}>
                                <td className="text-center">{idx + 1}</td>
                                <td>{new Date(inv.date).toLocaleDateString('en-GB')}</td>
                                <td className="font-mono text-sm">{inv.id.slice(0, 8).toUpperCase()}</td>
                                <td className="text-right font-bold">{Number(inv.total).toFixed(2)}</td>
                                <td className="text-right text-green-700">{Number(inv.paid).toFixed(2)}</td>
                                <td className="text-right text-red-600 font-bold">{Number(inv.currentBalance || 0).toFixed(2)}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>

                <div className="total-box" dir="rtl">
                    <div className="text-lg">
                        <span>إجمالي المشتريات: </span>
                        <span className="font-bold ml-4">{totalSpent.toFixed(2)} ج.م</span>
                    </div>
                    <div className="text-xl mt-2 text-red-600 border-t border-gray-300 pt-2">
                        <span>إجمالي المديونية المستحقة: </span>
                        <span className="font-bold ml-4">{Number(profile.balance).toFixed(2)} ج.م</span>
                    </div>
                </div>
            </div>
        </div>
    );
}

export default function CustomerProfilePage() {
    return (
        <Suspense fallback={
            <div className="flex flex-col items-center justify-center h-[80vh] gap-4">
                <Loader2 className="animate-spin text-primary" size={64} />
                <p className="text-muted-foreground font-black text-xl animate-pulse">Loading Profile...</p>
            </div>
        }>
            <ProfileContent />
        </Suspense>
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { getExpenses, createExpense, deleteExpense, getSalaryReport } from '@/app/actions/expenses';
import { getStaffList } from '@/app/actions/sales';
import { Plus, Trash2, Calendar, User, DollarSign, Tag, Search, Loader2, FileText, Percent, Briefcase, Receipt } from 'lucide-react';
import clsx from 'clsx';

interface Expense {
    id: string;
    description: string;
    amount: number;
    userId: string;
    userName: string;
    category: string;
    date: string;
}

interface User {
    id: string;
    name?: string;
    username?: string;
}

export default function ExpensesPage() {
    const [expenses, setExpenses] = useState<Expense[]>([]);
    const [users, setUsers] = useState<User[]>([]);
    const [loading, setLoading] = useState(true);
    const [submitting, setSubmitting] = useState(false);
    const [salaryMetrics, setSalaryMetrics] = useState({ salaryTotal: 0, nonSalaryTotal: 0, grandTotal: 0, salaryPercent: 0 });

    // New Expense State
    const [showForm, setShowForm] = useState(false);
    const [formData, setFormData] = useState({
        description: '',
        amount: '',
        userId: '',
        category: '',
        date: new Date().toISOString().split('T')[0]
    });

    // Filtering
    const [dateRange, setDateRange] = useState({ start: '', end: '' });
    const [categoryFilter, setCategoryFilter] = useState('ALL');
    const [generatingPdf, setGeneratingPdf] = useState(false);

    useEffect(() => {
        loadData();
    }, []);

    const loadData = useCallback(async () => {
        setLoading(true);
        const [expData, staff] = await Promise.all([
            getExpenses(dateRange.start, dateRange.end),
            getStaffList()
        ]);
        setExpenses(expData.expenses);
        setSalaryMetrics({
            salaryTotal: expData.salaryTotal,
            nonSalaryTotal: expData.nonSalaryTotal,
            grandTotal: expData.grandTotal,
            salaryPercent: expData.salaryPercent
        });
        setUsers(staff);
        setLoading(false);
    }, [dateRange.start, dateRange.end]);

    // Refresh when filters change
    useEffect(() => {
        if (!loading) {
            getExpenses(dateRange.start, dateRange.end).then(data => {
                setExpenses(data.expenses);
                setSalaryMetrics({
                    salaryTotal: data.salaryTotal,
                    nonSalaryTotal: data.nonSalaryTotal,
                    grandTotal: data.grandTotal,
                    salaryPercent: data.salaryPercent
                });
            });
        }
    }, [dateRange]);

    const handleSubmit = useCallback(async (e: React.FormEvent) => {
        e.preventDefault();
        setSubmitting(true);
        try {
            const res = await createExpense({
                description: formData.description,
                amount: parseFloat(formData.amount),
                userId: formData.userId,
                category: formData.category,
                date: formData.date
            });
            if (res.success) {
                setShowForm(false);
                setFormData({
                    description: '',
                    amount: '',
                    userId: '',
                    category: '',
                    date: new Date().toISOString().split('T')[0]
                });
                loadData();
            } else {
                alert('Failed to create expense');
            }
        } catch (error) {
            console.error(error);
        } finally {
            setSubmitting(false);
        }
    }, [formData, loadData]);

    const handleDelete = useCallback(async (id: string) => {
        if (!confirm('Are you sure you want to delete this expense?')) return;
        await deleteExpense(id);
        void loadData();
    }, [loadData]);

    const handleDeleteExpenseClick = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) void handleDelete(id);
    }, [handleDelete]);

    const handleStartDateChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setDateRange(prev => ({ ...prev, start: e.target.value })), []);
    const handleEndDateChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setDateRange(prev => ({ ...prev, end: e.target.value })), []);
    const handleCategoryFilterChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => setCategoryFilter(e.target.value), []);
    const handleToggleForm = useCallback(() => setShowForm(prev => !prev), []);
    
    const handleDescriptionChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setFormData(prev => ({ ...prev, description: e.target.value })), []);
    const handleAmountChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setFormData(prev => ({ ...prev, amount: e.target.value })), []);
    const handleUserIdChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => setFormData(prev => ({ ...prev, userId: e.target.value })), []);
    const handleCategoryChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => setFormData(prev => ({ ...prev, category: e.target.value })), []);
    const handleDateChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setFormData(prev => ({ ...prev, date: e.target.value })), []);

    const handleExportSalaryPdf = useCallback(async () => {
        if (!dateRange.start || !dateRange.end) {
            alert('Please select a date range first to generate salary report.');
            return;
        }
        setGeneratingPdf(true);
        try {
            const report = await getSalaryReport(dateRange.start, dateRange.end);

            // Generate client-side printable report
            const printWindow = window.open('', '_blank');
            if (!printWindow) return;

            const html = `<!DOCTYPE html>
<html dir="rtl"><head><meta charset="utf-8"><title>Salary Report</title>
<style>
    body { font-family: 'Segoe UI', Arial, sans-serif; max-width: 800px; margin: 0 auto; padding: 40px; }
    h1 { text-align: center; border-bottom: 3px solid #333; padding-bottom: 10px; }
    .period { text-align: center; color: #666; margin-bottom: 30px; }
    .summary { background: #f4f4f4; padding: 20px; border-radius: 8px; margin-bottom: 30px; display: flex; justify-content: space-between; }
    .summary-item { text-align: center; }
    .summary-item .value { font-size: 24px; font-weight: bold; color: #1a1a1a; }
    .summary-item .label { font-size: 12px; color: #666; text-transform: uppercase; }
    .employee { margin-bottom: 20px; border: 1px solid #ddd; border-radius: 8px; overflow: hidden; }
    .employee-header { background: #333; color: white; padding: 12px 16px; display: flex; justify-content: space-between; }
    .employee-entries { padding: 0; }
    .entry { display: flex; justify-content: space-between; padding: 10px 16px; border-bottom: 1px solid #eee; }
    .entry:last-child { border-bottom: none; }
    @media print { body { padding: 20px; } }
</style></head><body>
<h1>📋 Salary Expense Report</h1>
<div class="period">Period: ${report.period.startDate} to ${report.period.endDate}</div>
<div class="summary">
    <div class="summary-item"><div class="value">EGP ${report.grandTotal.toLocaleString()}</div><div class="label">Total Salaries</div></div>
    <div class="summary-item"><div class="value">${report.employees.length}</div><div class="label">Employees</div></div>
</div>
${report.employees.map(emp => `
<div class="employee">
    <div class="employee-header">
        <span>${emp.name}</span>
        <span>EGP ${emp.total.toLocaleString()}</span>
    </div>
    <div class="employee-entries">
        ${emp.entries.map(e => `<div class="entry"><span>${new Date(e.date).toLocaleDateString()}</span><span>${e.description}</span><span style="font-weight:bold">EGP ${e.amount.toLocaleString()}</span></div>`).join('')}
    </div>
</div>`).join('')}
</body></html>`;

            printWindow.document.write(html);
            printWindow.document.close();
            printWindow.focus();
            setTimeout(() => printWindow.print(), 500);
        } catch (err) {
            console.error(err);
            alert('Failed to generate report');
        } finally {
            setGeneratingPdf(false);
        }
    }, [dateRange]);

    // Filter by category on client-side
    const filteredExpenses = categoryFilter === 'ALL'
        ? expenses
        : categoryFilter === 'SALARY'
            ? expenses.filter(e => e.category?.toUpperCase() === 'SALARY')
            : expenses.filter(e => e.category?.toUpperCase() !== 'SALARY');

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight flex items-center gap-3">
                        <Receipt className="text-primary" />
                        المصروفات
                    </h1>
                    <p className="text-muted-foreground">Expenses & Salary Tracking</p>
                </div>
            </div>

            {/* Metrics Cards */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="bg-gradient-to-br from-card to-secondary/30 p-5 rounded-2xl border border-border shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 bg-primary/10 rounded-lg text-primary"><DollarSign size={18} /></div>
                        <span className="text-xs font-bold text-muted-foreground uppercase">Total Spend</span>
                    </div>
                    <div className="text-2xl font-black">EGP {salaryMetrics.grandTotal.toLocaleString()}</div>
                </div>

                <div className="bg-gradient-to-br from-card to-secondary/30 p-5 rounded-2xl border border-border shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 bg-blue-500/10 rounded-lg text-blue-500"><Briefcase size={18} /></div>
                        <span className="text-xs font-bold text-muted-foreground uppercase">Salary Total</span>
                    </div>
                    <div className="text-2xl font-black text-blue-600">EGP {salaryMetrics.salaryTotal.toLocaleString()}</div>
                </div>

                <div className="bg-gradient-to-br from-card to-secondary/30 p-5 rounded-2xl border border-border shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 bg-orange-500/10 rounded-lg text-orange-500"><Tag size={18} /></div>
                        <span className="text-xs font-bold text-muted-foreground uppercase">Other Expenses</span>
                    </div>
                    <div className="text-2xl font-black text-orange-600">EGP {salaryMetrics.nonSalaryTotal.toLocaleString()}</div>
                </div>

                <div className="bg-gradient-to-br from-card to-secondary/30 p-5 rounded-2xl border border-border shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 bg-purple-500/10 rounded-lg text-purple-500"><Percent size={18} /></div>
                        <span className="text-xs font-bold text-muted-foreground uppercase">Salary %</span>
                    </div>
                    <div className="flex items-end gap-2">
                        <span className="text-2xl font-black text-purple-600">{salaryMetrics.salaryPercent}%</span>
                        <div className="flex-1 h-2 bg-secondary rounded-full overflow-hidden mb-1">
                            <div className="h-full bg-purple-500 rounded-full transition-all" style={{ width: `${salaryMetrics.salaryPercent}%` }} />
                        </div>
                    </div>
                </div>
            </div>

            {/* Controls */}
            <div className="flex flex-wrap items-center gap-4 bg-card p-4 rounded-xl border border-border">
                <div className="flex items-center gap-2">
                    <input
                        type="date"
                        value={dateRange.start}
                        onChange={handleStartDateChange}
                        className="bg-background border border-border rounded-lg p-2 text-sm"
                    />
                    <span className="text-muted-foreground">-</span>
                    <input
                        type="date"
                        value={dateRange.end}
                        onChange={handleEndDateChange}
                        className="bg-background border border-border rounded-lg p-2 text-sm"
                    />
                </div>

                <select
                    value={categoryFilter}
                    onChange={handleCategoryFilterChange}
                    className="px-3 py-2 bg-background border border-input rounded-lg text-sm"
                >
                    <option value="ALL">All Categories</option>
                    <option value="SALARY">Salaries Only</option>
                    <option value="OTHER">Non-Salary Only</option>
                </select>

                <div className="ml-auto flex items-center gap-2">
                    <button
                        onClick={handleExportSalaryPdf}
                        disabled={generatingPdf}
                        className="flex items-center gap-2 px-4 py-2 bg-secondary hover:bg-secondary/80 rounded-lg transition-colors text-sm font-medium disabled:opacity-50"
                    >
                        {generatingPdf ? <Loader2 className="animate-spin" size={16} /> : <FileText size={16} />}
                        Salary PDF
                    </button>
                    <button
                        onClick={handleToggleForm}
                        className="flex items-center gap-2 bg-primary text-primary-foreground px-4 py-2 rounded-lg font-bold hover:bg-primary/90 transition-colors"
                    >
                        <Plus size={18} />
                        New Expense
                    </button>
                </div>
            </div>

            {/* Form */}
            {showForm && (
                <div className="bg-card border border-border p-6 rounded-xl animate-in slide-in-from-top-2 shadow-lg">
                    <h3 className="text-lg font-bold mb-4">Add New Expense</h3>
                    <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-muted-foreground">Description</label>
                            <div className="flex items-center gap-2 border border-border rounded-lg p-2 bg-background focus-within:ring-2 ring-primary/20">
                                <Tag size={16} className="text-muted-foreground" />
                                <input
                                    required
                                    placeholder="Make coffee, electricity..."
                                    value={formData.description}
                                    onChange={handleDescriptionChange}
                                    className="flex-1 bg-transparent outline-none text-sm"
                                />
                            </div>
                        </div>

                        <div className="space-y-1">
                            <label className="text-xs font-bold text-muted-foreground">Amount (EGP)</label>
                            <div className="flex items-center gap-2 border border-border rounded-lg p-2 bg-background focus-within:ring-2 ring-primary/20">
                                <DollarSign size={16} className="text-muted-foreground" />
                                <input
                                    required
                                    type="number"
                                    min="0"
                                    step="0.01"
                                    placeholder="0.00"
                                    value={formData.amount}
                                    onChange={handleAmountChange}
                                    className="flex-1 bg-transparent outline-none text-sm"
                                />
                            </div>
                        </div>

                        <div className="space-y-1">
                            <label className="text-xs font-bold text-muted-foreground">Who Spent?</label>
                            <div className="flex items-center gap-2 border border-border rounded-lg p-2 bg-background focus-within:ring-2 ring-primary/20">
                                <User size={16} className="text-muted-foreground" />
                                <select
                                    required
                                    value={formData.userId}
                                    onChange={handleUserIdChange}
                                    className="flex-1 bg-transparent outline-none text-sm cursor-pointer"
                                >
                                    <option value="">Select Staff...</option>
                                    {users.map(u => (
                                        <option key={u.id} value={u.id}>{u.name || u.username}</option>
                                    ))}
                                </select>
                            </div>
                        </div>

                        <div className="space-y-1">
                            <label className="text-xs font-bold text-muted-foreground">Category</label>
                            <div className="flex items-center gap-2 border border-border rounded-lg p-2 bg-background focus-within:ring-2 ring-primary/20">
                                <Search size={16} className="text-muted-foreground" />
                                <select
                                    value={formData.category}
                                    onChange={handleCategoryChange}
                                    className="flex-1 bg-transparent outline-none text-sm cursor-pointer"
                                >
                                    <option value="">Select Category...</option>
                                    <option value="SALARY">💰 Salary</option>
                                    <option value="Utilities">⚡ Utilities</option>
                                    <option value="Supplies">📦 Supplies</option>
                                    <option value="Maintenance">🔧 Maintenance</option>
                                    <option value="Other">📋 Other</option>
                                </select>
                            </div>
                        </div>

                        <div className="space-y-1">
                            <label className="text-xs font-bold text-muted-foreground">Date</label>
                            <div className="flex items-center gap-2 border border-border rounded-lg p-2 bg-background focus-within:ring-2 ring-primary/20">
                                <Calendar size={16} className="text-muted-foreground" />
                                <input
                                    required
                                    type="date"
                                    value={formData.date}
                                    onChange={handleDateChange}
                                    className="flex-1 bg-transparent outline-none text-sm"
                                />
                            </div>
                        </div>

                        <div className="flex items-end">
                            <button
                                disabled={submitting}
                                className="w-full bg-primary text-primary-foreground p-2 rounded-lg font-bold hover:bg-primary/90 transition-colors flex items-center justify-center gap-2"
                            >
                                {submitting ? <Loader2 className="animate-spin" /> : 'Save Expense'}
                            </button>
                        </div>
                    </form>
                </div>
            )}

            {/* List */}
            <div className="bg-card border border-border rounded-xl overflow-hidden shadow-sm">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                        <thead className="bg-secondary/20 font-bold text-muted-foreground border-b border-border">
                            <tr>
                                <th className="px-4 py-3 text-left">Date</th>
                                <th className="px-4 py-3 text-left">Description</th>
                                <th className="px-4 py-3 text-left">Category</th>
                                <th className="px-4 py-3 text-left">Spent By</th>
                                <th className="px-4 py-3 text-right">Amount</th>
                                <th className="px-4 py-3 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border/50">
                            {loading ? (
                                <tr>
                                    <td colSpan={6} className="p-8 text-center text-muted-foreground">
                                        <Loader2 className="animate-spin mx-auto mb-2" /> Loading expenses...
                                    </td>
                                </tr>
                            ) : filteredExpenses.length === 0 ? (
                                <tr>
                                    <td colSpan={6} className="p-8 text-center text-muted-foreground">No expenses found for this period.</td>
                                </tr>
                            ) : (
                                filteredExpenses.map(exp => (
                                    <tr key={exp.id} className="hover:bg-secondary/10 transition-colors">
                                        <td className="px-4 py-3">{new Date(exp.date).toLocaleDateString()}</td>
                                        <td className="px-4 py-3 font-medium">{exp.description}</td>
                                        <td className="px-4 py-3">
                                            {exp.category && (
                                                <span className={clsx(
                                                    "px-2 py-1 rounded text-xs font-bold",
                                                    exp.category?.toUpperCase() === 'SALARY' ? "bg-blue-100 text-blue-700" : "bg-secondary text-foreground"
                                                )}>
                                                    {exp.category?.toUpperCase() === 'SALARY' ? '💰 ' : ''}{exp.category}
                                                </span>
                                            )}
                                        </td>
                                        <td className="px-4 py-3">{exp.userName}</td>
                                        <td className="px-4 py-3 text-right font-bold text-red-600">-EGP {exp.amount.toLocaleString()}</td>
                                        <td className="px-4 py-3 text-right">
                                            <button
                                                data-id={exp.id}
                                                onClick={handleDeleteExpenseClick}
                                                className="text-muted-foreground hover:text-red-500 transition-colors"
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { Truck, Plus, Loader2, X, Check } from 'lucide-react';
import { getIncomingTransactions, getLocations, createIncomingStock } from '@/app/actions/incoming';
import { getProducts } from '@/app/actions/sales';

interface IncomingItem {
    id: string;
    productName: string;
    quantity: number;
    supplier: string;
    costPrice: number;
    status: 'pending' | 'received' | 'rejected';
    date?: Date;
}

interface Product {
    id: string;
    name: string;
    sku: string;
}

interface Location {
    id: string;
    name: string;
}

export default function IncomingStockPage() {
    const [items, setItems] = useState<IncomingItem[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [submitting, setSubmitting] = useState(false);

    // Form State
    const [products, setProducts] = useState<Product[]>([]);
    const [locations, setLocations] = useState<Location[]>([]);
    const [formData, setFormData] = useState({
        productId: '',
        quantity: 1,
        locationId: '',
        notes: ''
    });

    const refreshData = async () => {
        setLoading(true);
        const data = await getIncomingTransactions();
        setItems(data as IncomingItem[]);
        setLoading(false);
    };

    useEffect(() => {
        refreshData();
        // Pre-fetch products and locations
        getProducts().then(setProducts);
        getLocations().then(setLocations);
    }, []);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.productId || !formData.locationId || formData.quantity <= 0) return;

        setSubmitting(true);
        try {
            await createIncomingStock(formData);
            await refreshData();
            setIsModalOpen(false);
            setFormData({ productId: '', quantity: 1, locationId: '', notes: '' });
        } catch (error) {
            console.error("Failed to add purchase:", error);
            alert("Failed to add purchase. Please check connection.");
        } finally {
            setSubmitting(false);
        }
    };

    const handleOpenModal = useCallback(() => setIsModalOpen(true), []);
    const handleCloseModal = useCallback(() => setIsModalOpen(false), []);
    
    const handleProductIdChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => {
        setFormData(prev => ({ ...prev, productId: e.target.value }));
    }, []);
    
    const handleQuantityChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
        setFormData(prev => ({ ...prev, quantity: parseInt(e.target.value) || 0 }));
    }, []);
    
    const handleLocationIdChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => {
        setFormData(prev => ({ ...prev, locationId: e.target.value }));
    }, []);
    
    const handleNotesChange = useCallback((e: React.ChangeEvent<HTMLTextAreaElement>) => {
        setFormData(prev => ({ ...prev, notes: e.target.value }));
    }, []);

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <h2 className="text-3xl font-bold tracking-tight">Incoming Stock</h2>
                <button
                    onClick={handleOpenModal}
                    className="flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground hover:bg-primary/90 rounded-lg transition-all shadow-sm active:scale-95"
                >
                    <Plus size={16} />
                    New Purchase Order
                </button>
            </div>

            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                <div className="bg-card p-6 rounded-xl border border-border shadow-sm group hover:border-primary/50 transition-colors">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-blue-100 text-blue-700 rounded-xl dark:bg-blue-900/30 dark:text-blue-300 group-hover:scale-110 transition-transform">
                            <Truck size={24} />
                        </div>
                        <div>
                            <div className="text-sm font-medium text-muted-foreground uppercase tracking-wider">Total Shipments</div>
                            <div className="text-2xl font-bold">{items.length} Records</div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="rounded-xl border border-border bg-card shadow-sm overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-secondary/30 text-muted-foreground font-semibold border-b border-border">
                            <tr>
                                <th className="px-6 py-4 uppercase tracking-wider">Product</th>
                                <th className="px-6 py-4 uppercase tracking-wider">Quantity</th>
                                <th className="px-6 py-4 uppercase tracking-wider">Supplier / Notes</th>
                                <th className="px-6 py-4 uppercase tracking-wider">Total Cost</th>
                                <th className="px-6 py-4 uppercase tracking-wider">Date</th>
                                <th className="px-6 py-4 uppercase tracking-wider text-right">Status</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {loading ? (
                                <tr>
                                    <td colSpan={6} className="px-6 py-12 text-center text-muted-foreground">
                                        <div className="flex flex-col items-center justify-center gap-3">
                                            <Loader2 className="animate-spin text-primary" size={32} />
                                            <span className="animate-pulse">Loading shipments...</span>
                                        </div>
                                    </td>
                                </tr>
                            ) : items.length === 0 ? (
                                <tr>
                                    <td colSpan={6} className="px-6 py-12 text-center text-muted-foreground">
                                        <div className="flex flex-col items-center gap-2">
                                            <Truck size={40} className="mb-2 opacity-20" />
                                            <p className="text-lg font-medium">No incoming stock history.</p>
                                            <p className="text-sm opacity-60">Create a purchase order to populate this list.</p>
                                        </div>
                                    </td>
                                </tr>
                            ) : (
                                items.map(item => (
                                    <tr key={item.id} className="hover:bg-muted/50 transition-colors">
                                        <td className="px-6 py-4 font-semibold text-foreground">{item.productName}</td>
                                        <td className="px-6 py-4 font-medium">{item.quantity}</td>
                                        <td className="px-6 py-4 text-muted-foreground truncate max-w-[200px]">{item.supplier}</td>
                                        <td className="px-6 py-4 font-bold text-primary">EGP {item.costPrice.toLocaleString()}</td>
                                        <td className="px-6 py-4 text-muted-foreground">{item.date ? new Date(item.date).toLocaleDateString() : '-'}</td>
                                        <td className="px-6 py-4 text-right">
                                            <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold uppercase bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300">
                                                <Check size={10} />
                                                {item.status}
                                            </span>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Modal Overlay */}
            {isModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-card w-full max-w-md rounded-2xl border border-border shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
                        <div className="p-6 border-b border-border flex items-center justify-between bg-secondary/20">
                            <h3 className="text-xl font-bold flex items-center gap-2">
                                <Plus className="text-primary" size={20} />
                                New Purchase Order
                            </h3>
                            <button onClick={handleCloseModal} className="p-1 hover:bg-secondary rounded-full transition-colors">
                                <X size={20} />
                            </button>
                        </div>

                        <form onSubmit={handleSubmit} className="p-6 space-y-4">
                            <div className="space-y-2">
                                <label className="text-sm font-semibold text-muted-foreground">Select Product</label>
                                <select
                                    className="w-full p-3 rounded-xl border border-border bg-background focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none transition-all"
                                    required
                                    value={formData.productId}
                                    onChange={handleProductIdChange}
                                >
                                    <option value="">Choose item...</option>
                                    {products.map(p => (
                                        <option key={p.id} value={p.id}>{p.name} ({p.sku})</option>
                                    ))}
                                </select>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="text-sm font-semibold text-muted-foreground">Quantity</label>
                                    <input
                                        type="number"
                                        min="1"
                                        className="w-full p-3 rounded-xl border border-border bg-background focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none transition-all"
                                        required
                                        value={formData.quantity}
                                        onChange={handleQuantityChange}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-semibold text-muted-foreground">Target Location</label>
                                    <select
                                        className="w-full p-3 rounded-xl border border-border bg-background focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none transition-all"
                                        required
                                        value={formData.locationId}
                                        onChange={handleLocationIdChange}
                                    >
                                        <option value="">Select branch...</option>
                                        {locations.map(l => (
                                            <option key={l.id} value={l.id}>{l.name}</option>
                                        ))}
                                    </select>
                                </div>
                            </div>

                            <div className="space-y-2">
                                <label className="text-sm font-semibold text-muted-foreground">Supplier / Notes</label>
                                <textarea
                                    className="w-full p-3 rounded-xl border border-border bg-background focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none transition-all resize-none h-24"
                                    placeholder="Enter supplier name or delivery notes..."
                                    value={formData.notes}
                                    onChange={handleNotesChange}
                                />
                            </div>

                            <div className="pt-4 flex gap-3">
                                <button
                                    type="button"
                                    onClick={handleCloseModal}
                                    className="flex-1 px-4 py-3 rounded-xl border border-border hover:bg-secondary font-semibold transition-colors"
                                >
                                    Cancel
                                </button>
                                <button
                                    type="submit"
                                    disabled={submitting}
                                    className="flex-1 px-4 py-3 rounded-xl bg-primary text-primary-foreground font-bold hover:bg-primary/90 disabled:opacity-50 transition-all flex items-center justify-center gap-2 shadow-lg shadow-primary/20"
                                >
                                    {submitting ? <Loader2 className="animate-spin" size={18} /> : <Check size={18} />}
                                    Add Purchase
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { FileText, Filter, Search, Calendar, Loader2, X, Printer, RefreshCcw } from 'lucide-react';
import { getInvoices } from '@/app/actions/invoices';
import { printElement } from '@/components/ui/PrintExport';
import RefundModal from '@/components/RefundModal';

interface Invoice {
    id: string;
    customerName: string | null;
    customerPhone: string | null;
    customerAddress: string | null;
    user?: {
        id: string;
        name: string | null;
        username: string;
        phone: string | null;
        address: string | null;
    };
    date: Date;
    totalAmount: number;
    paymentMethod: string;
    previousBalance?: number;
    amountPaid?: number;
    currentBalance?: number;
    items?: Array<{
        id: string;
        productId: string;
        product: { name: string, sku: string };
        quantity: number;
        refundableQuantity: number;
        unitPrice: number;
        subtotal: number;
    }>;
}

export default function InvoicesPage() {
    const [invoices, setInvoices] = useState<Invoice[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);
    const [showRefundModal, setShowRefundModal] = useState(false);

    // Date Filter State
    const [showDateFilter, setShowDateFilter] = useState(false);
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    useEffect(() => {
        getInvoices().then(data => {
            // Map Prisma result to UI interface if needed, currently straightforward
            // But we need to handle the types correctly
            setInvoices(data as unknown as Invoice[]);
            setLoading(false);
        });
    }, []);

    const handleDownload = useCallback((invoice: Invoice) => {
        setTimeout(() => {
            printElement(
                `Invoice #${invoice.id.slice(0, 8).toUpperCase()}`,
                'print-invoice-content',
                `<p>Customer: ${invoice.customerName || 'Walk-in'}</p>`
            );
        }, 100);
    }, []);

    const handlePrintReport = useCallback(() => {
        const dateRangeStr = startDate || endDate ? `<p>Period: ${startDate || 'Start'} to ${endDate || 'Now'}</p>` : '';
        printElement('Invoices Report', 'print-invoice-list', dateRangeStr);
    }, [startDate, endDate]);

    const handleToggleDateFilter = useCallback(() => setShowDateFilter(prev => !prev), []);
    const handleSearchChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setSearchQuery(e.target.value), []);
    const handleStartDateChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setStartDate(e.target.value), []);
    const handleEndDateChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setEndDate(e.target.value), []);
    const handleClearDateFilter = useCallback(() => {
        setStartDate('');
        setEndDate('');
    }, []);

    const handleSelectInvoice = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
        const id = e.currentTarget.dataset.id;
        if (!id) return;
        const inv = invoices.find(i => i.id === id);
        if (inv) setSelectedInvoice(inv);
    }, [invoices]);

    const handlePrintIconClick = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        e.stopPropagation();
        const id = e.currentTarget.dataset.id;
        if (!id) return;
        const inv = invoices.find(i => i.id === id);
        if (inv) {
            setSelectedInvoice(inv);
            handleDownload(inv);
        }
    }, [invoices, handleDownload]);

    const handleCloseModal = useCallback(() => setSelectedInvoice(null), []);
    const handleDownloadSelected = useCallback(() => {
        if (selectedInvoice) handleDownload(selectedInvoice);
    }, [selectedInvoice, handleDownload]);
    const handleOpenPrintTab = useCallback(() => {
        if (selectedInvoice) window.open(`/invoices/${selectedInvoice.id}/print`, '_blank');
    }, [selectedInvoice]);
    const handleOpenRefundModal = useCallback(() => setShowRefundModal(true), []);
    const handleCloseRefundModal = useCallback(() => setShowRefundModal(false), []);
    const handleRefundSuccess = useCallback(() => {
        setShowRefundModal(false);
        setSelectedInvoice(null);
        getInvoices().then(data => setInvoices(data as unknown as Invoice[]));
    }, []);

    const filteredInvoices = invoices.filter(inv => {
        const query = searchQuery.toLowerCase();
        const matchesSearch = (
            inv.id.toLowerCase().includes(query) ||
            (inv.customerName && inv.customerName.toLowerCase().includes(query)) ||
            (inv.user?.username && inv.user.username.toLowerCase().includes(query))
        );

        const invDate = new Date(inv.date);
        const matchesDate =
            (!startDate || invDate >= new Date(startDate)) &&
            (!endDate || invDate <= new Date(new Date(endDate).setHours(23, 59, 59)));

        return matchesSearch && matchesDate;
    });



    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
                <h2 className="text-3xl font-bold tracking-tight">Invoices</h2>
                <div className="flex gap-2">
                    <button
                        onClick={handleToggleDateFilter}
                        className={`flex items-center gap-2 px-4 py-2 border rounded-lg transition-colors ${showDateFilter ? 'bg-secondary border-primary' : 'border-border hover:bg-secondary'}`}
                    >
                        <Calendar size={16} />
                        Date Range
                    </button>
                    <button
                        onClick={handlePrintReport}
                        className="flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground hover:bg-primary/90 rounded-lg"
                    >
                        <Printer size={16} />
                        Export Report
                    </button>
                </div>
            </div>

            {/* Filters */}
            <div className="flex items-center gap-4 bg-card p-4 rounded-xl border border-border">
                <Search className="text-muted-foreground" size={18} />
                <input
                    placeholder="Search invoice # or customer..."
                    className="flex-1 bg-transparent outline-none"
                    value={searchQuery}
                    onChange={handleSearchChange}
                />
                <button className="p-2 hover:bg-secondary rounded">
                    <Filter size={18} />
                </button>
            </div>

            {/* Date Range Inputs */}
            {showDateFilter && (
                <div className="flex flex-wrap items-center gap-4 p-4 bg-secondary/20 rounded-xl border border-border animate-in slide-in-from-top-2">
                    <div className="flex items-center gap-2">
                        <label className="text-sm font-medium">From:</label>
                        <input
                            type="date"
                            value={startDate}
                            onChange={handleStartDateChange}
                            className="bg-card border border-border rounded-lg px-3 py-2 text-sm"
                        />
                    </div>
                    <div className="flex items-center gap-2">
                        <label className="text-sm font-medium">To:</label>
                        <input
                            type="date"
                            value={endDate}
                            onChange={handleEndDateChange}
                            className="bg-card border border-border rounded-lg px-3 py-2 text-sm"
                        />
                    </div>
                    <button
                        onClick={handleClearDateFilter}
                        className="text-xs text-muted-foreground hover:text-primary transition-colors underline"
                    >
                        Clear Filter
                    </button>
                </div>
            )}

            {/* List */}
            <div className="space-y-4">
                {loading ? (
                    <div className="flex justify-center p-8 text-muted-foreground">
                        <Loader2 className="animate-spin mr-2" /> Loading invoices...
                    </div>
                ) : filteredInvoices.length === 0 ? (
                    <div className="text-center p-8 text-muted-foreground">No invoices found.</div>
                ) : (
                    filteredInvoices.map(inv => (
                        <div
                            key={inv.id}
                            data-id={inv.id}
                            onClick={handleSelectInvoice}
                            className="flex flex-col md:flex-row md:items-center justify-between p-4 bg-card border border-border rounded-xl hover:shadow-md transition-shadow cursor-pointer group gap-4"
                        >
                            <div className="flex items-center gap-4">
                                <div className="p-3 bg-secondary/50 rounded-lg text-primary group-hover:scale-110 transition-transform">
                                    <FileText size={24} />
                                </div>
                                <div>
                                    <div className="font-bold">
                                        {inv.customerName || (inv.user ? `${inv.user.username}` : 'Walk-in Customer')}
                                    </div>
                                    <div className="text-sm text-muted-foreground flex gap-2">
                                        <span className="font-mono">#{inv.id.slice(0, 8).toUpperCase()}</span>
                                        <span>•</span>
                                        <span>{new Date(inv.date).toLocaleDateString()}</span>
                                    </div>
                                </div>
                            </div>

                            <div className="flex items-center gap-4 md:gap-8 justify-between md:justify-end w-full md:w-auto">
                                <div className="text-right">
                                    <div className="font-bold text-lg">EGP {Number(inv.totalAmount).toLocaleString()}</div>
                                    <div className="text-xs text-muted-foreground">{inv.paymentMethod}</div>
                                </div>

                                <div className="px-3 py-1 rounded-full text-xs font-bold uppercase bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-300">
                                    Paid
                                </div>

                                <button
                                    data-id={inv.id}
                                    onClick={handlePrintIconClick}
                                    className="p-2 hover:bg-secondary rounded-full text-muted-foreground hover:text-foreground transition-colors"
                                    title="Print / Download PDF"
                                >
                                    <Printer size={20} />
                                </button>
                            </div>
                        </div>
                    ))
                )}
            </div>

            {/* Details Modal */}
            {selectedInvoice && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-card w-full max-w-2xl rounded-2xl border border-border shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 flex flex-col max-h-[90vh]">
                        <div className="p-6 border-b border-border flex items-center justify-between bg-secondary/10">
                            <div>
                                <h3 className="text-xl font-bold flex items-center gap-2">
                                    Invoice Details
                                </h3>
                                <p className="text-xs text-muted-foreground font-mono mt-1">ID: {selectedInvoice.id}</p>
                            </div>
                            <button onClick={handleCloseModal} className="p-2 hover:bg-secondary rounded-full transition-colors">
                                <X size={20} />
                            </button>
                        </div>

                        <div id="print-invoice-content" className="flex-1 overflow-y-auto p-6 space-y-6">
                            {/* Summary Header */}
                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-4 bg-muted/20 rounded-xl border border-border">
                                <div>
                                    <label className="text-[10px] font-bold uppercase text-muted-foreground">Date & Time</label>
                                    <div className="text-sm font-semibold">{new Date(selectedInvoice.date).toLocaleString()}</div>
                                </div>
                                <div>
                                    <label className="text-[10px] font-bold uppercase text-muted-foreground">Payment</label>
                                    <div className="text-sm font-semibold">{selectedInvoice.paymentMethod}</div>
                                </div>
                                <div>
                                    <label className="text-[10px] font-bold uppercase text-muted-foreground">Status</label>
                                    <div className="text-sm font-bold text-green-500">PAID</div>
                                </div>
                                <div>
                                    <label className="text-[10px] font-bold uppercase text-muted-foreground">Invoice #</label>
                                    <div className="text-sm font-mono">{selectedInvoice.id.slice(0, 8).toUpperCase()}</div>
                                </div>
                            </div>

                            {/* Salesperson Info */}
                            <div className="p-4 bg-blue-50 dark:bg-blue-900/20 rounded-xl border border-blue-200 dark:border-blue-800">
                                <h4 className="font-bold text-sm uppercase tracking-wider text-blue-600 dark:text-blue-400 mb-2">Salesperson (Recorded By)</h4>
                                <div className="grid grid-cols-2 gap-4 text-sm">
                                    <div>
                                        <span className="text-muted-foreground">Name: </span>
                                        <span className="font-medium">{selectedInvoice.user?.name || selectedInvoice.user?.username || 'N/A'}</span>
                                    </div>
                                    <div>
                                        <span className="text-muted-foreground">Username: </span>
                                        <span className="font-medium">@{selectedInvoice.user?.username || 'N/A'}</span>
                                    </div>
                                    <div>
                                        <span className="text-muted-foreground">Phone: </span>
                                        <span className="font-medium">{selectedInvoice.user?.phone || 'N/A'}</span>
                                    </div>
                                    <div>
                                        <span className="text-muted-foreground">Address: </span>
                                        <span className="font-medium">{selectedInvoice.user?.address || 'N/A'}</span>
                                    </div>
                                </div>
                            </div>

                            {/* Buyer Info */}
                            <div className="p-4 bg-amber-50 dark:bg-amber-900/20 rounded-xl border border-amber-200 dark:border-amber-800">
                                <h4 className="font-bold text-sm uppercase tracking-wider text-amber-600 dark:text-amber-400 mb-2">Buyer Information</h4>
                                <div className="grid grid-cols-2 gap-4 text-sm">
                                    <div>
                                        <span className="text-muted-foreground">Name: </span>
                                        <span className="font-medium">{selectedInvoice.customerName || 'Walk-in Customer'}</span>
                                    </div>
                                    <div>
                                        <span className="text-muted-foreground">Phone: </span>
                                        <span className="font-medium">{selectedInvoice.customerPhone || 'N/A'}</span>
                                    </div>
                                    <div className="col-span-2">
                                        <span className="text-muted-foreground">Address: </span>
                                        <span className="font-medium">{selectedInvoice.customerAddress || 'N/A'}</span>
                                    </div>
                                </div>
                            </div>

                            {/* Items Table */}
                            <div className="space-y-3">
                                <h4 className="font-bold text-sm uppercase tracking-wider text-muted-foreground px-1">Order Items</h4>
                                <div className="border border-border rounded-xl overflow-hidden">
                                    <table className="w-full text-sm">
                                        <thead className="bg-secondary/20 text-muted-foreground font-medium">
                                            <tr>
                                                <th className="px-4 py-2 text-left">Item</th>
                                                <th className="px-4 py-2 text-center">Qty</th>
                                                <th className="px-4 py-2 text-right">Price</th>
                                                <th className="px-4 py-2 text-right">Subtotal</th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-border">
                                            {selectedInvoice.items?.map(item => (
                                                <tr key={item.id} className="hover:bg-muted/30">
                                                    <td className="px-4 py-3">
                                                        <div className="font-medium">{item.product.name}</div>
                                                        <div className="text-[10px] text-muted-foreground">{item.product.sku}</div>
                                                    </td>
                                                    <td className="px-4 py-3 text-center">{item.quantity}</td>
                                                    <td className="px-4 py-3 text-right">EGP {item.unitPrice.toLocaleString()}</td>
                                                    <td className="px-4 py-3 text-right font-bold">EGP {item.subtotal.toLocaleString()}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                        <tfoot className="bg-secondary/10 font-bold border-t border-border">
                                            <tr>
                                                <td colSpan={3} className="px-4 py-3 text-right">GRAND TOTAL</td>
                                                <td className="px-4 py-3 text-right text-primary text-lg">EGP {Number(selectedInvoice.totalAmount).toLocaleString()}</td>
                                            </tr>
                                        </tfoot>
                                    </table>
                                </div>

                                {/* Premium Arabic Financial Footer */}
                                <div className="mt-6 border-2 border-primary/20 rounded-2xl overflow-hidden bg-primary/5 shadow-inner">
                                    <div className="grid grid-cols-2 md:grid-cols-4 divide-x-2 divide-primary/20 rtl text-right font-bold" dir="rtl">
                                        <div className="p-4 flex flex-col items-center justify-center gap-1">
                                            <span className="text-[10px] text-muted-foreground">الرصيد السابق</span>
                                            <span className="text-lg">EGP {Number(selectedInvoice.previousBalance || 0).toLocaleString()}</span>
                                        </div>
                                        <div className="p-4 flex flex-col items-center justify-center gap-1 bg-primary/10">
                                            <span className="text-[10px] text-primary">الصافي</span>
                                            <span className="text-xl text-primary">EGP {Number(selectedInvoice.totalAmount).toLocaleString()}</span>
                                        </div>
                                        <div className="p-4 flex flex-col items-center justify-center gap-1">
                                            <span className="text-[10px] text-green-600">مستلم</span>
                                            <span className="text-lg text-green-600">EGP {Number(selectedInvoice.amountPaid || 0).toLocaleString()}</span>
                                        </div>
                                        <div className="p-4 flex flex-col items-center justify-center gap-1 bg-primary/5">
                                            <span className="text-[10px] text-red-600 font-black">الرصيد الحالي</span>
                                            <span className="text-xl text-red-600 underline decoration-double">EGP {Number(selectedInvoice.currentBalance || 0).toLocaleString()}</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="p-4 border-t border-border bg-secondary/5 flex gap-3">
                            <button
                                onClick={handleDownloadSelected}
                                className="flex-1 flex items-center justify-center gap-2 py-3 bg-secondary hover:bg-secondary/80 rounded-xl font-bold transition-all"
                            >
                                <span className="flex items-center gap-2">
                                    <Printer size={18} />
                                    Quick Print
                                </span>
                            </button>
                            <button
                                onClick={handleOpenPrintTab}
                                className="flex-1 flex items-center justify-center gap-2 py-3 bg-blue-600 text-white rounded-xl font-bold transition-all hover:bg-blue-700"
                            >
                                <FileText size={18} />
                                Official Invoice (فاتورة)
                            </button>
                            <button
                                onClick={handleCloseModal}
                                className="flex-1 py-3 bg-primary text-primary-foreground rounded-xl font-bold hover:bg-primary/90 transition-all shadow-lg shadow-primary/20"
                            >
                                Close
                            </button>
                        </div>

                        <div className="px-6 pb-6 pt-2 border-t border-border/50 bg-red-50/20 dark:bg-red-950/5 flex flex-col gap-2">
                            <h4 className="text-[10px] font-bold uppercase text-red-500 tracking-widest pl-1">Actions</h4>
                            <button
                                onClick={handleOpenRefundModal}
                                className="flex items-center justify-center gap-2 py-3 bg-red-100 dark:bg-red-900/20 text-red-600 rounded-xl font-bold transition-all hover:bg-red-200 dark:hover:bg-red-900/40"
                            >
                                <RefreshCcw size={18} />
                                Process Item Refund
                            </button>
                        </div>
                    </div>
                </div>
            )
            }

            {/* Refund Modal */}
            {showRefundModal && selectedInvoice && (
                <RefundModal
                    invoice={selectedInvoice}
                    onClose={handleCloseRefundModal}
                    onSuccess={handleRefundSuccess}
                />
            )}


            {/* Hidden Print Content */}
            <div id="print-invoice-list" className="hidden">
                <style>{`
                    @media print {
                        table { width: 100%; border-collapse: collapse; font-size: 12px; }
                        th, td { border-bottom: 1px solid #ddd; padding: 8px; text-align: left; }
                        th { background-color: #f5f5f5; font-weight: bold; }
                        .text-right { text-align: right; }
                        .font-bold { font-weight: bold; }
                    }
                `}</style>
                <div className="mb-4">
                    <h1 className="text-xl font-bold">Invoices Report</h1>
                    <p className="text-sm text-gray-500">Generated on {new Date().toLocaleString()}</p>
                </div>
                <table>
                    <thead>
                        <tr>
                            <th>Date</th>
                            <th>Invoice #</th>
                            <th>Customer</th>
                            <th className="text-right">Amount</th>
                            <th>Payment</th>
                        </tr>
                    </thead>
                    <tbody>
                        {filteredInvoices.map(inv => (
                            <tr key={inv.id}>
                                <td>{new Date(inv.date).toLocaleDateString()}</td>
                                <td>{inv.id.slice(0, 8).toUpperCase()}</td>
                                <td>{inv.customerName || (inv.user ? inv.user.username : 'Walk-in')}</td>
                                <td className="text-right">EGP {Number(inv.totalAmount).toLocaleString()}</td>
                                <td>{inv.paymentMethod}</td>
                            </tr>
                        ))}
                    </tbody>
                    <tfoot>
                        <tr>
                            <td colSpan={3} className="text-right font-bold pt-4">TOTAL</td>
                            <td className="text-right font-bold pt-4">
                                EGP {filteredInvoices.reduce((sum, inv) => sum + Number(inv.totalAmount), 0).toLocaleString()}
                            </td>
                            <td></td>
                        </tr>
                    </tfoot>
                </table>
            </div>
        </div >
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import {
    LayoutDashboard,
    Package,
    ShoppingCart,
    Users,
    FileText,
    LogOut,
    Menu,
    X,
    ArrowLeftRight,
    ClipboardCheck,
    TrendingUp,
    UserCheck,
    BarChart3,
    ScrollText,
    DollarSign,
    RefreshCcw
} from 'lucide-react';
import clsx from 'clsx';
import { signOut } from '@/app/actions/auth';
import { getMenuItemsForUser, getCurrentUser } from '@/app/actions/permissions';

const iconMap: Record<string, React.ElementType> = {
    '/dashboard': LayoutDashboard,
    '/sales': ShoppingCart,
    '/stocktake': ClipboardCheck,
    '/movements': ArrowLeftRight,
    '/products': Package,
    '/invoices': FileText,
    '/customers': Users,
    '/analytics': BarChart3,
    '/profits': TrendingUp,
    '/staff-sales': UserCheck,
    '/logs': ScrollText,
    '/users': Users,
    '/expenses': DollarSign,
    '/refunds': RefreshCcw,
};

interface MenuItem {
    to: string;
    label: string;
    labelAr: string;
    permission: string;
}

interface CurrentUser {
    id: string;
    username: string;
    name: string | null;
    role: string;
}

const SidebarItem = ({ to, icon: Icon, label, labelAr, active }: { to: string, icon: React.ElementType, label: string, labelAr: string, active: boolean }) => (
    <Link prefetch={false}
        href={to}
        className={clsx(
            "flex items-center gap-3 px-4 py-3 rounded-lg transition-colors mx-2",
            active ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:bg-secondary hover:text-foreground"
        )}
    >
        <Icon size={20} />
        <div className="flex flex-col">
            <span className="font-bold text-sm">{labelAr}</span>
            <span className="text-[10px] opacity-70">{label}</span>
        </div>
    </Link>
);

export default function DashboardLayout({ children }: { children: React.ReactNode }) {
    const [isSidebarOpen, setSidebarOpen] = useState(false);
    const [menuItems, setMenuItems] = useState<MenuItem[]>([]);
    const [currentUser, setCurrentUser] = useState<CurrentUser | null>(null);
    const pathname = usePathname();

    useEffect(() => {
        // Load menu items based on user permissions
        getMenuItemsForUser().then(setMenuItems);
        getCurrentUser().then(setCurrentUser);
    }, []);

    const handleCloseSidebar = useCallback(() => setSidebarOpen(false), []);
    const handleToggleSidebar = useCallback(() => setSidebarOpen(prev => !prev), []);
    const handleSignOut = useCallback(async () => {
        await signOut();
    }, []);

    return (
        <div className="flex h-screen bg-background text-foreground overflow-hidden">
            {/* Mobile Sidebar Overlay */}
            {isSidebarOpen && (
                <div
                    className="fixed inset-0 bg-black/50 z-20 md:hidden"
                    onClick={handleCloseSidebar}
                />
            )}

            {/* Sidebar */}
            <aside className={clsx(
                "fixed md:relative z-30 w-64 h-full bg-card border-r border-border flex flex-col transition-transform duration-300",
                !isSidebarOpen ? "-translate-x-full md:translate-x-0" : "translate-x-0"
            )}>
                <div className="p-6 border-b border-border flex items-center gap-3">
                    <div className="w-8 h-8 rounded-lg overflow-hidden flex-shrink-0">
                        <img src="/logo.webp" alt="Logo" className="w-full h-full object-cover" />
                    </div>
                    <h1 className="text-xl font-black bg-gradient-to-r from-primary to-orange-600 bg-clip-text text-transparent uppercase tracking-tighter">
                        EPIC COMPANY
                    </h1>
                    <button onClick={handleToggleSidebar} className="md:hidden ml-auto">
                        <X />
                    </button>
                </div>

                <nav className="flex-1 py-6 space-y-1 overflow-y-auto">
                    {menuItems.map((item) => (
                        <SidebarItem
                            key={item.to}
                            to={item.to}
                            icon={iconMap[item.to] || LayoutDashboard}
                            label={item.label}
                            labelAr={item.labelAr}
                            active={pathname === item.to || pathname.startsWith(item.to + '/')}
                        />
                    ))}
                </nav>

                <div className="p-4 border-t border-border">
                    <button
                        onClick={handleSignOut}
                        className="flex items-center gap-3 px-4 py-3 w-full text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                    >
                        <LogOut size={20} />
                        <span className="font-medium">Logout</span>
                    </button>
                </div>
            </aside>

            {/* Main Content */}
            <main className="flex-1 flex flex-col h-full overflow-hidden relative">
                <header className="h-16 border-b border-border bg-card/50 backdrop-blur px-6 flex items-center justify-between">
                    <button onClick={handleToggleSidebar} className="p-2 hover:bg-secondary rounded-lg md:hidden">
                        <Menu />
                    </button>
                    <div className="flex items-center gap-4">
                        <div className="text-right">
                            <div className="text-sm font-medium">{currentUser?.name || currentUser?.username || 'User'}</div>
                            <div className="text-[10px] text-muted-foreground uppercase">{currentUser?.role || 'Loading...'}</div>
                        </div>
                        <div className={clsx(
                            "w-8 h-8 rounded-full flex items-center justify-center font-bold text-white",
                            currentUser?.role === 'ROOT' ? 'bg-purple-500' :
                                currentUser?.role === 'ADMIN' ? 'bg-blue-500' :
                                    currentUser?.role === 'ACCOUNTANT' ? 'bg-green-500' :
                                        currentUser?.role === 'SALESPERSON' ? 'bg-orange-500' :
                                            'bg-gray-500'
                        )}>
                            {(currentUser?.name || currentUser?.username || 'U')[0].toUpperCase()}
                        </div>
                    </div>
                </header>

                <div className="flex-1 overflow-auto p-6 bg-secondary/20">
                    {children}
                </div>
            </main>
        </div>
    );
}

'use client';

import { Suspense, useState, useEffect, useCallback } from 'react';
import { useSearchParams } from 'next/navigation';
import { getAuditLogs } from '@/app/actions/audit';
import { getUsers } from '@/app/actions/users';
import { ScrollText, RefreshCcw, Loader2, User, ChevronLeft, ChevronRight, Filter } from 'lucide-react';
import clsx from 'clsx';

interface LogUser {
    id: string;
    name: string | null;
    username: string;
    role: string;
}

interface LogEntry {
    id: string;
    action: string;
    details: string;
    timestamp: string | Date;
    user?: LogUser;
}

const ITEMS_PER_PAGE = 50;

function LogsContent() {
    const searchParams = useSearchParams();
    const [logs, setLogs] = useState<LogEntry[]>([]);
    const [users, setUsers] = useState<LogUser[]>([]);
    const [loading, setLoading] = useState(true);
    const [page, setPage] = useState(1);
    const [selectedUserId, setSelectedUserId] = useState<string>(searchParams.get('user') || '');
    const [pagination, setPagination] = useState({ total: 0, pages: 1, current: 1 });

    const fetchLogs = async () => {
        setLoading(true);
        try {
            const res = await getAuditLogs(page, ITEMS_PER_PAGE, selectedUserId || undefined);
            if (res.success && res.logs) {
                setLogs(res.logs);
                setPagination(res.pagination || { total: 0, pages: 1, current: 1 });
            }
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        getUsers().then(setUsers);
    }, []);

    useEffect(() => {
        fetchLogs();
    }, [page, selectedUserId]);

    const getActionColor = (action: string) => {
        if (action.includes('SALE')) return 'bg-green-100 text-green-700 border-green-200';
        if (action.includes('DELETE')) return 'bg-red-100 text-red-700 border-red-200';
        if (action.includes('UPDATE')) return 'bg-blue-100 text-blue-700 border-blue-200';
        if (action.includes('CREATE')) return 'bg-purple-100 text-purple-700 border-purple-200';
        return 'bg-secondary text-secondary-foreground border-border';
    };

    const handleUserFilterChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => {
        setSelectedUserId(e.target.value);
        setPage(1);
    }, []);

    const handleClearFilter = useCallback(() => {
        setSelectedUserId('');
        setPage(1);
    }, []);

    const handlePrevPage = useCallback(() => setPage(p => Math.max(1, p - 1)), []);
    const handleNextPage = useCallback(() => setPage(p => Math.min(pagination.pages, p + 1)), [pagination.pages]);

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight text-foreground flex items-center gap-3">
                        <ScrollText className="text-primary" />
                        سجل النظام
                    </h2>
                    <p className="text-muted-foreground">Audit Logs & Activity History</p>
                </div>
                <button
                    onClick={fetchLogs}
                    disabled={loading}
                    className="flex items-center gap-2 px-4 py-2 bg-secondary hover:bg-secondary/80 rounded-lg transition-colors disabled:opacity-50"
                >
                    <RefreshCcw size={16} className={loading ? "animate-spin" : ""} />
                    Refresh
                </button>
            </div>

            {/* User Filter */}
            <div className="flex items-center gap-3 bg-card p-3 rounded-lg border border-border">
                <Filter size={16} className="text-muted-foreground" />
                <span className="text-sm font-medium">Filter by User:</span>
                <select
                    value={selectedUserId}
                    onChange={handleUserFilterChange}
                    className="bg-secondary/50 border border-border rounded-lg px-3 py-1.5 text-sm outline-none focus:ring-2 ring-primary/20"
                >
                    <option value="">All Users</option>
                    {users.map((u) => (
                        <option key={u.id} value={u.id}>
                            {u.name || u.username} ({u.role})
                        </option>
                    ))}
                </select>
                {selectedUserId && (
                    <button
                        onClick={handleClearFilter}
                        className="text-xs text-primary hover:underline"
                    >
                        Clear filter
                    </button>
                )}
            </div>

            <div className="rounded-xl border border-border bg-card shadow-sm overflow-hidden">
                <table className="w-full text-sm text-left">
                    <thead className="bg-secondary/30 text-muted-foreground font-semibold border-b border-border">
                        <tr>
                            <th className="px-6 py-4">Status & Action</th>
                            <th className="px-6 py-4">Details</th>
                            <th className="px-6 py-4">User</th>
                            <th className="px-6 py-4 text-right">Time</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-border">
                        {loading ? (
                            <tr><td colSpan={4} className="px-6 py-12 text-center text-muted-foreground"><Loader2 className="animate-spin mx-auto" /></td></tr>
                        ) : logs.length === 0 ? (
                            <tr><td colSpan={4} className="px-6 py-12 text-center text-muted-foreground">No logs found.</td></tr>
                        ) : (
                            logs.map((log) => (
                                <tr key={log.id} className="hover:bg-muted/50 transition-colors">
                                    <td className="px-6 py-4">
                                        <span className={clsx("px-2.5 py-1 rounded-full text-xs font-bold border", getActionColor(log.action))}>
                                            {log.action}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 font-medium text-foreground/80">{log.details}</td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2 text-muted-foreground">
                                            <User size={14} />
                                            {log.user?.name || log.user?.username || 'System'}
                                            {log.user?.role && <span className="text-[10px] bg-secondary px-1 rounded">{log.user.role}</span>}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-right tabular-nums text-muted-foreground">
                                        {new Date(log.timestamp).toLocaleString()}
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>

                {/* Pagination */}
                {pagination.pages > 1 && (
                    <div className="px-6 py-4 border-t border-border flex items-center justify-between bg-secondary/10">
                        <div className="text-sm text-muted-foreground">
                            Page {page} of {pagination.pages} ({pagination.total} entries)
                        </div>
                        <div className="flex gap-2">
                            <button
                                onClick={handlePrevPage}
                                disabled={page === 1}
                                className="p-2 rounded-lg border border-border hover:bg-secondary disabled:opacity-30"
                            >
                                <ChevronLeft size={16} />
                            </button>
                            <button
                                onClick={handleNextPage}
                                disabled={page === pagination.pages}
                                className="p-2 rounded-lg border border-border hover:bg-secondary disabled:opacity-30"
                            >
                                <ChevronRight size={16} />
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

export default function LogsPage() {
    return (
        <Suspense fallback={<div className="flex justify-center py-12"><Loader2 className="animate-spin" /></div>}>
            <LogsContent />
        </Suspense>
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { getStockMovements } from '@/app/actions/transactions';
import {
    History, RefreshCcw, Loader2,
    ArrowDownLeft, ArrowUpRight, ShoppingCart, ArrowRightLeft,
    MapPin, Package, Calendar
} from 'lucide-react';
import clsx from 'clsx';

const ITEMS_PER_PAGE = 50;

type TransactionType = 'SALE' | 'IN' | 'OUT' | 'TRANSFER' | 'RETURN';

interface TransactionItem {
    id: string;
    quantity: number;
    product: { name: string; sku: string };
}

interface Transaction {
    id: string;
    type: TransactionType;
    date: string | Date;
    createdById?: string;
    items: TransactionItem[];
    fromLocation?: { name: string };
    toLocation?: { name: string };
}

export default function MovementsPage() {
    const [transactions, setTransactions] = useState<Transaction[]>([]);
    const [loading, setLoading] = useState(true);
    const [page, setPage] = useState(1);
    const [filterType, setFilterType] = useState('ALL');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [pagination, setPagination] = useState({ total: 0, pages: 1, current: 1 });

    const fetchData = async () => {
        setLoading(true);
        try {
            const res = await getStockMovements(page, ITEMS_PER_PAGE, { type: filterType, startDate: startDate || undefined, endDate: endDate || undefined });
            if (res.success && res.movements) {
                setTransactions(res.movements);
                setPagination(res.pagination || { total: 0, pages: 1, current: 1 });
            }
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, [page, filterType, startDate, endDate]);

    const handleFilterTypeChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => setFilterType(e.target.value), []);
    const handleStartDateChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setStartDate(e.target.value), []);
    const handleEndDateChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setEndDate(e.target.value), []);
    const handlePrevPage = useCallback(() => setPage(p => Math.max(1, p - 1)), []);
    const handleNextPage = useCallback(() => setPage(p => Math.min(pagination.pages, p + 1)), [pagination.pages]);

    const getTypeConfig = (type: TransactionType) => {
        switch (type) {
            case 'SALE': return { icon: ShoppingCart, color: 'text-blue-600 bg-blue-100 border-blue-200', label: 'Sale' };
            case 'IN': return { icon: ArrowDownLeft, color: 'text-green-600 bg-green-100 border-green-200', label: 'Stock In' };
            case 'OUT': return { icon: ArrowUpRight, color: 'text-red-600 bg-red-100 border-red-200', label: 'Stock Out' };
            case 'TRANSFER': return { icon: ArrowRightLeft, color: 'text-orange-600 bg-orange-100 border-orange-200', label: 'Transfer' };
            case 'RETURN': return { icon: RefreshCcw, color: 'text-purple-600 bg-purple-100 border-purple-200', label: 'Return' };
            default: return { icon: History, color: 'text-gray-600 bg-gray-100 border-gray-200', label: type };
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight text-foreground flex items-center gap-3">
                        <History className="text-primary" />
                        حركات المخزون
                    </h2>
                    <p className="text-muted-foreground">Stock Movement History</p>
                </div>

                <div className="flex flex-wrap items-center gap-2">
                    <select
                        value={filterType}
                        onChange={handleFilterTypeChange}
                        className="px-3 py-2 bg-background border border-input rounded-lg text-sm font-medium focus:ring-2 focus:ring-primary"
                    >
                        <option value="ALL">All Types</option>
                        <option value="SALE">Sales</option>
                        <option value="IN">Stock In</option>
                        <option value="OUT">Stock Out</option>
                        <option value="TRANSFER">Transfers</option>
                    </select>

                    <div className="flex items-center gap-2 bg-card border border-border p-1 rounded-lg">
                        <input
                            type="date"
                            value={startDate}
                            onChange={handleStartDateChange}
                            className="bg-transparent text-sm p-2 outline-none"
                            placeholder="From"
                        />
                        <span className="text-muted-foreground">-</span>
                        <input
                            type="date"
                            value={endDate}
                            onChange={handleEndDateChange}
                            className="bg-transparent text-sm p-2 outline-none"
                            placeholder="To"
                        />
                    </div>

                    <button onClick={fetchData} disabled={loading} className="flex items-center gap-2 px-4 py-2 bg-secondary hover:bg-secondary/80 rounded-lg transition-colors disabled:opacity-50">
                        <RefreshCcw size={16} className={loading ? "animate-spin" : ""} />
                        Refresh
                    </button>
                </div>
            </div>

            <div className="space-y-4">
                {loading ? (
                    <div className="flex justify-center py-20"><Loader2 className="animate-spin text-muted-foreground" size={32} /></div>
                ) : transactions.length === 0 ? (
                    <div className="text-center py-20 bg-card border border-border rounded-xl text-muted-foreground">
                        No transactions found matching your filters.
                    </div>
                ) : (
                    transactions.map((tx) => {
                        const { icon: Icon, color, label } = getTypeConfig(tx.type);
                        return (
                            <div key={tx.id} className="bg-card border border-border rounded-xl p-4 shadow-sm hover:shadow-md transition-shadow">
                                <div className="flex flex-col md:flex-row gap-4 justify-between">
                                    {/* Header: Type & Date */}
                                    <div className="flex items-start gap-4 min-w-[200px]">
                                        <div className={clsx("p-3 rounded-xl border", color)}>
                                            <Icon size={20} />
                                        </div>
                                        <div>
                                            <h4 className="font-bold text-foreground">{label}</h4>
                                            <div className="flex items-center gap-1 text-xs text-muted-foreground mt-1">
                                                <Calendar size={12} />
                                                {new Date(tx.date).toLocaleString()}
                                            </div>
                                            {tx.createdById && <div className="text-xs text-muted-foreground mt-0.5">By: {tx.createdById}</div>}
                                        </div>
                                    </div>

                                    {/* Items List */}
                                    <div className="flex-1 space-y-2">
                                        {tx.items.map((item: TransactionItem) => (
                                            <div key={item.id} className="flex items-center justify-between text-sm p-2 bg-secondary/20 rounded-lg">
                                                <div className="flex items-center gap-2 font-medium">
                                                    <Package size={14} className="text-muted-foreground" />
                                                    {item.product.name}
                                                    <span className="text-xs text-muted-foreground font-mono">({item.product.sku})</span>
                                                </div>
                                                <div className="font-bold font-mono">
                                                    x{item.quantity}
                                                </div>
                                            </div>
                                        ))}
                                    </div>

                                    {/* Locations */}
                                    <div className="min-w-[150px] text-right space-y-2 text-sm">
                                        {(tx.fromLocation || tx.type === 'SALE' || tx.type === 'OUT') && (
                                            <div className="flex items-center justify-end gap-1.5 text-muted-foreground">
                                                <span className="text-xs uppercase font-bold">From</span>
                                                <span className="font-medium text-foreground">{tx.fromLocation?.name || 'Unknown'}</span>
                                                <MapPin size={14} />
                                            </div>
                                        )}
                                        {tx.toLocation && (
                                            <div className="flex items-center justify-end gap-1.5 text-muted-foreground">
                                                <span className="text-xs uppercase font-bold">To</span>
                                                <span className="font-medium text-foreground">{tx.toLocation?.name}</span>
                                                <MapPin size={14} className="text-green-500" />
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        );
                    })
                )}

                {/* Pagination Controls */}
                {pagination.pages > 1 && (
                    <div className="flex justify-center gap-2 pt-4">
                        <button
                            onClick={handlePrevPage}
                            disabled={page === 1}
                            className="px-4 py-2 rounded-lg border border-border hover:bg-secondary disabled:opacity-30"
                        >
                            Previous
                        </button>
                        <span className="px-4 py-2 text-sm text-muted-foreground self-center">
                            Page {page} of {pagination.pages}
                        </span>
                        <button
                            onClick={handleNextPage}
                            disabled={page === pagination.pages}
                            className="px-4 py-2 rounded-lg border border-border hover:bg-secondary disabled:opacity-30"
                        >
                            Next
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { Tag, Edit, Percent } from 'lucide-react';
import { getInventory } from '@/app/actions/inventory';

export default function PricingPage() {
    const [products, setProducts] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        getInventory().then(data => {
            setProducts(data);
            setLoading(false);
        });
    }, []);

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight text-foreground flex items-center gap-3">
                        <Tag className="text-primary" />
                        التسعير
                    </h2>
                    <p className="text-muted-foreground">Price Management & Margins</p>
                </div>
                <button className="flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground rounded-lg hover:bg-primary/90 transition-all">
                    <Percent size={16} />
                    Bulk Update
                </button>
            </div>

            <div className="rounded-xl border border-border bg-card shadow-sm overflow-hidden">
                <table className="w-full text-sm text-left">
                    <thead className="bg-secondary/30 text-muted-foreground font-semibold border-b border-border">
                        <tr>
                            <th className="px-6 py-4">Product</th>
                            <th className="px-6 py-4 text-right">Cost (EGP)</th>
                            <th className="px-6 py-4 text-right">Selling (EGP)</th>
                            <th className="px-6 py-4 text-right">Margin</th>
                            <th className="px-6 py-4 text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-border">
                        {loading ? (
                            <tr>
                                <td colSpan={5} className="px-6 py-12 text-center text-muted-foreground">
                                    Loading pricing data...
                                </td>
                            </tr>
                        ) : products.length === 0 ? (
                            <tr>
                                <td colSpan={5} className="px-6 py-12 text-center text-muted-foreground">
                                    No products found.
                                </td>
                            </tr>
                        ) : (
                            products.map((item) => {
                                const cost = Number(item.product.costPrice);
                                const sell = Number(item.product.baseSellingPrice);
                                const margin = sell > 0 ? ((sell - cost) / sell * 100).toFixed(1) : 0;
                                return (
                                    <tr key={item.id} className="hover:bg-muted/50">
                                        <td className="px-6 py-4 font-medium">{item.product.name}</td>
                                        <td className="px-6 py-4 text-right font-mono">{cost.toLocaleString()}</td>
                                        <td className="px-6 py-4 text-right font-mono font-bold">{sell.toLocaleString()}</td>
                                        <td className="px-6 py-4 text-right">
                                            <span className="px-2 py-1 bg-green-100 text-green-700 rounded text-xs font-bold">
                                                {margin}%
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-right">
                                            <button className="p-2 hover:bg-secondary rounded-lg">
                                                <Edit size={14} />
                                            </button>
                                        </td>
                                    </tr>
                                );
                            })
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, useMemo, useCallback } from 'react';
import { Package, Search, Plus, RefreshCcw, Loader2, X, Check, Edit, Trash2, AlertCircle, FolderPlus, Settings, ArrowUpDown, ArrowUp, ArrowDown, ChevronLeft, ChevronRight, ChevronDown, MapPin } from 'lucide-react';
import { getUnifiedProducts, getCategories, createProduct, updateProduct, createCategory, deleteCategory } from '@/app/actions/inventory';
import clsx from 'clsx';

type SortField = 'name' | 'sku' | 'category' | 'stock' | 'cost' | 'sell' | 'margin' | 'percent';
type SortOrder = 'asc' | 'desc';

interface LocationBreakdown {
    locationId: string;
    locationName: string;
    locationType: string;
    quantity: number;
}

interface Product {
    id: string;
    name: string;
    sku: string;
    categoryId: string;
    categoryName: string;
    costPrice: number;
    baseSellingPrice: number;
    unit: string;
    totalStock: number;
    percentOfTotal: number;
    locationBreakdown: LocationBreakdown[];
}

interface Category {
    id: string;
    name: string;
    _count?: { products: number };
}

const ITEMS_PER_PAGE = 15;

export default function ProductsPage() {
