    const [editingId, setEditingId] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [expandedRow, setExpandedRow] = useState<string | null>(null);

    // Sorting state
    const [sortField, setSortField] = useState<SortField>('name');
    const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

    // Pagination state
    const [currentPage, setCurrentPage] = useState(1);

    // Category modal state
    const [isCategoryModalOpen, setIsCategoryModalOpen] = useState(false);
    const [newCategoryName, setNewCategoryName] = useState('');
    const [categoryError, setCategoryError] = useState<string | null>(null);
    const [categorySubmitting, setCategorySubmitting] = useState(false);

    const [formData, setFormData] = useState({
        name: '',
        sku: '',
        categoryId: '',
        costPrice: 0,
        baseSellingPrice: 0,
        unit: 'piece',
        initialQuantity: 0
    });

    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            const [prods, cats] = await Promise.all([getUnifiedProducts(), getCategories()]);
            setProducts(prods);
            setCategories(cats);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { void fetchData(); }, [fetchData]);

    // Reset to page 1 when filters change
    useEffect(() => {
        setCurrentPage(1);
    }, [searchQuery, categoryFilter, sortField, sortOrder]);

    const openAddModal = useCallback(() => {
        setIsEditMode(false);
        setEditingId(null);
        setFormData({ name: '', sku: '', categoryId: '', costPrice: 0, baseSellingPrice: 0, unit: 'piece', initialQuantity: 0 });
        setError(null);
        setIsModalOpen(true);
    }, []);

    const openEditModal = useCallback((product: Product) => {
        setIsEditMode(true);
        setEditingId(product.id);
        setFormData({
            name: product.name,
            sku: product.sku,
            categoryId: product.categoryId,
            costPrice: product.costPrice,
            baseSellingPrice: product.baseSellingPrice,
            unit: product.unit,
            initialQuantity: product.totalStock
        });
        setError(null);
        setIsModalOpen(true);
    }, []);

    const handleSubmit = useCallback(async (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.name || !formData.sku || !formData.categoryId) return;
        setSubmitting(true);
        setError(null);
        try {
            let result;
            if (isEditMode && editingId) {
                const { name, sku, categoryId, costPrice, baseSellingPrice, unit } = formData;
                result = await updateProduct(editingId, { name, sku, categoryId, costPrice, baseSellingPrice, unit });
            } else {
                result = await createProduct(formData);
            }
            if (!result.success) {
                setError(result.error || 'Operation failed');
                return;
            }
            await fetchData();
            setIsModalOpen(false);
        } catch {
            setError("Connection error. Please try again.");
        } finally {
            setSubmitting(false);
        }
    }, [formData, isEditMode, editingId, fetchData]);

    const handleAddCategory = useCallback(async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newCategoryName.trim()) return;
        setCategorySubmitting(true);
        setCategoryError(null);
        try {
            const result = await createCategory(newCategoryName.trim());
            if (!result.success) {
                setCategoryError(result.error || 'Failed to create category');
                return;
            }
            setNewCategoryName('');
            await fetchData();
        } catch {
            setCategoryError('Connection error.');
        } finally {
            setCategorySubmitting(false);
        }
    }, [newCategoryName, fetchData]);

    const handleDeleteCategory = useCallback(async (id: string) => {
        setCategorySubmitting(true);
        setCategoryError(null);
        try {
            const result = await deleteCategory(id);
            if (!result.success) {
                setCategoryError(result.error || 'Failed to delete');
                return;
            }
            await fetchData();
        } catch {
            setCategoryError('Connection error.');
        } finally {
            setCategorySubmitting(false);
        }
    }, [fetchData]);

    const handleSort = useCallback((field: SortField) => {
        if (sortField === field) {
            setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
        } else {
            setSortField(field);
            setSortOrder('asc');
        }
    }, [sortField, sortOrder]);

    const handleCloseModal = useCallback(() => setIsModalOpen(false), []);
    const handleCloseCategoryModal = useCallback(() => setIsCategoryModalOpen(false), []);
    const handleOpenCategoryModal = useCallback(() => setIsCategoryModalOpen(true), []);
    const handleSearchChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setSearchQuery(e.target.value), []);
    const handleCategoryFilterChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => setCategoryFilter(e.target.value), []);
    const handleFormNameChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setFormData(prev => ({ ...prev, name: e.target.value })), []);
    const handleFormSkuChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setFormData(prev => ({ ...prev, sku: e.target.value })), []);
    const handleFormCategoryChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => setFormData(prev => ({ ...prev, categoryId: e.target.value })), []);
    const handleFormCostChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setFormData(prev => ({ ...prev, costPrice: Number(e.target.value) })), []);
    const handleFormPriceChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setFormData(prev => ({ ...prev, baseSellingPrice: Number(e.target.value) })), []);
    const handleFormUnitChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => setFormData(prev => ({ ...prev, unit: e.target.value })), []);
    const handleFormQtyChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setFormData(prev => ({ ...prev, initialQuantity: Number(e.target.value) })), []);
    const handleNewCategoryNameChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setNewCategoryName(e.target.value), []);

    const handleToggleExpandRow = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) {
            setExpandedRow(prev => prev === id ? null : id);
        }
    }, []);

    const handleEditProductClick = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) {
            const product = products.find(p => p.id === id);
            if (product) openEditModal(product);
        }
    }, [products, openEditModal]);

    const handlePageChange = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const pageStr = e.currentTarget.dataset.page;
        if (pageStr) {
            setCurrentPage(parseInt(pageStr, 10));
        }
    }, []);

    const handlePrevPage = useCallback(() => setCurrentPage(prev => Math.max(1, prev - 1)), []);
    const handleNextPage = useCallback(() => setCurrentPage(prev => prev + 1), []);

    const handleSortClick = useCallback((e: React.MouseEvent<HTMLTableCellElement>) => {
        const field = e.currentTarget.dataset.field as SortField;
        if (field) handleSort(field);
    }, [handleSort]);

    const handleDeleteCategoryClick = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) void handleDeleteCategory(id);
    }, [handleDeleteCategory]);

    const getSortIcon = (field: SortField) => {
        if (sortField !== field) return <ArrowUpDown size={14} className="opacity-30" />;
        return sortOrder === 'asc' ? <ArrowUp size={14} className="text-primary" /> : <ArrowDown size={14} className="text-primary" />;
    };

    // Filter and sort products
    const filteredAndSortedItems = useMemo(() => {
        const result = (products || []).filter(p => {
            const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                p.sku.toLowerCase().includes(searchQuery.toLowerCase());
            const matchesCategory = categoryFilter === 'all' || p.categoryId === categoryFilter;
            return matchesSearch && matchesCategory;
        });

        result.sort((a, b) => {
            let aVal: string | number = 0;
            let bVal: string | number = 0;
            switch (sortField) {
                case 'name': aVal = a.name.toLowerCase(); bVal = b.name.toLowerCase(); break;
                case 'sku': aVal = a.sku.toLowerCase(); bVal = b.sku.toLowerCase(); break;
                case 'category': aVal = a.categoryName.toLowerCase(); bVal = b.categoryName.toLowerCase(); break;
                case 'stock': aVal = a.totalStock; bVal = b.totalStock; break;
                case 'cost': aVal = a.costPrice; bVal = b.costPrice; break;
                case 'sell': aVal = a.baseSellingPrice; bVal = b.baseSellingPrice; break;
                case 'percent': aVal = a.percentOfTotal; bVal = b.percentOfTotal; break;
                case 'margin':
                    aVal = a.baseSellingPrice > 0 ? ((a.baseSellingPrice - a.costPrice) / a.baseSellingPrice) : 0;
                    bVal = b.baseSellingPrice > 0 ? ((b.baseSellingPrice - b.costPrice) / b.baseSellingPrice) : 0;
                    break;
                default: return 0;
            }
            if (aVal < bVal) return sortOrder === 'asc' ? -1 : 1;
            if (aVal > bVal) return sortOrder === 'asc' ? 1 : -1;
            return 0;
        });

        return result;
    }, [products, searchQuery, categoryFilter, sortField, sortOrder]);

    // Pagination
    const totalPages = Math.ceil(filteredAndSortedItems.length / ITEMS_PER_PAGE);
    const paginatedItems = filteredAndSortedItems.slice(
        (currentPage - 1) * ITEMS_PER_PAGE,
        currentPage * ITEMS_PER_PAGE
    );

    const renderSortableHeader = (field: SortField, children: React.ReactNode, className = "") => (
        <th
            className={clsx("px-4 py-3 cursor-pointer hover:bg-secondary/50 transition-colors select-none text-xs", className)}
            data-field={field}
            onClick={handleSortClick}
        >
            <div className="flex items-center gap-1">
                {children}
                {getSortIcon(field)}
            </div>
        </th>
    );

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight text-foreground flex items-center gap-3">
                        <Package className="text-primary" />
                        الأصناف والتسعير
                    </h2>
                    <p className="text-muted-foreground">Products, Pricing & Stock</p>
                </div>
                <div className="flex gap-2">
                    <button onClick={fetchData} disabled={loading} className="flex items-center gap-2 px-4 py-2 bg-secondary hover:bg-secondary/80 rounded-lg transition-colors disabled:opacity-50">
                        <RefreshCcw size={16} className={loading ? "animate-spin" : ""} />
                    </button>
                    <button onClick={handleOpenCategoryModal} className="flex items-center gap-2 px-4 py-2 bg-secondary hover:bg-secondary/80 rounded-lg transition-colors">
                        <Settings size={16} />
                        Categories
                    </button>
                    <button onClick={openAddModal} className="flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground hover:bg-primary/90 rounded-lg transition-all shadow-sm active:scale-95">
                        <Plus size={16} />
                        New Product
                    </button>
                </div>
            </div>

            {/* Filters Bar */}
            <div className="flex flex-wrap items-center gap-4 bg-card p-4 rounded-xl border border-border shadow-sm">
                {/* Category Filter */}
                <select
                    value={categoryFilter}
                    onChange={handleCategoryFilterChange}
                    className="px-3 py-2 bg-background border border-input rounded-lg text-sm"
                >
                    <option value="all">All Categories</option>
                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>

                {/* Search */}
                <div className="relative flex-1 min-w-[200px]">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" size={18} />
                    <input
                        type="text"
                        placeholder="Search products..."
                        value={searchQuery}
                        onChange={handleSearchChange}
                        className="w-full pl-10 pr-4 py-2 bg-background border border-input rounded-lg focus:outline-none focus:ring-2 focus:ring-ring"
                    />
                </div>

                {/* Results count */}
                <div className="text-sm text-muted-foreground">
                    {filteredAndSortedItems.length} products
                </div>
            </div>

            {/* Unified Table */}
            <div className="rounded-xl border border-border bg-card shadow-sm overflow-hidden">
                <table className="w-full text-sm text-left">
                    <thead className="bg-secondary/30 text-muted-foreground font-semibold border-b border-border">
                        <tr>
                            <th className="px-4 py-3 w-8"></th>
                            {renderSortableHeader('name', 'Product')}
                            {renderSortableHeader('sku', 'SKU')}
                            {renderSortableHeader('category', 'Category')}
                            <th className="px-4 py-3 text-xs">Unit</th>
                            {renderSortableHeader('cost', 'Cost', 'text-right')}
                            {renderSortableHeader('sell', 'Sell', 'text-right')}
                            {renderSortableHeader('margin', 'Margin', 'text-right')}
                            {renderSortableHeader('stock', 'Stock', 'text-right')}
                            {renderSortableHeader('percent', '% Total', 'text-right')}
                            <th className="px-4 py-3 text-right text-xs">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-border">
                        {loading ? (
                            <tr><td colSpan={11} className="px-6 py-12 text-center text-muted-foreground"><Loader2 className="animate-spin mx-auto" /></td></tr>
                        ) : paginatedItems.length === 0 ? (
                            <tr><td colSpan={11} className="px-6 py-12 text-center text-muted-foreground">No products found.</td></tr>
                        ) : (
                            paginatedItems.map((p) => {
                                const margin = p.baseSellingPrice > 0 ? ((p.baseSellingPrice - p.costPrice) / p.baseSellingPrice * 100).toFixed(1) : '0';
                                const isExpanded = expandedRow === p.id;
                                return (
                                    <>
                                        <tr key={p.id} className="hover:bg-muted/50 transition-colors group">
                                            <td className="px-4 py-3">
                                                {p.locationBreakdown.length > 0 && (
                                                    <button
                                                        data-id={p.id}
                                                        onClick={handleToggleExpandRow}
                                                        className="p-1 rounded hover:bg-secondary transition-colors"
                                                    >
                                                        <ChevronDown size={14} className={clsx("transition-transform", isExpanded && "rotate-180")} />
                                                    </button>
                                                )}
                                            </td>
                                            <td className="px-4 py-3 font-semibold">{p.name}</td>
                                            <td className="px-4 py-3 font-mono text-xs">{p.sku}</td>
                                            <td className="px-4 py-3"><span className="px-2 py-1 bg-secondary rounded text-[10px] font-bold">{p.categoryName}</span></td>
                                            <td className="px-4 py-3 text-xs capitalize text-muted-foreground">{p.unit}</td>
                                            <td className="px-4 py-3 text-right font-mono text-xs">{p.costPrice.toLocaleString()}</td>
                                            <td className="px-4 py-3 text-right font-mono text-xs font-bold">{p.baseSellingPrice.toLocaleString()}</td>
                                            <td className="px-4 py-3 text-right">
                                                <span className={clsx(
                                                    "px-2 py-0.5 rounded text-[10px] font-bold",
                                                    Number(margin) >= 20 ? "bg-green-100 text-green-700" : Number(margin) >= 10 ? "bg-yellow-100 text-yellow-700" : "bg-red-100 text-red-700"
                                                )}>
                                                    {margin}%
                                                </span>
                                            </td>
                                            <td className="px-4 py-3 text-right">
                                                <span className={clsx("font-bold", p.totalStock < 10 ? "text-red-500" : "")}>{p.totalStock}</span>
                                                {p.totalStock < 10 && <AlertCircle size={12} className="inline ml-1 text-red-500" />}
                                            </td>
                                            <td className="px-4 py-3 text-right">
                                                <div className="flex items-center justify-end gap-2">
                                                    <div className="w-16 h-1.5 bg-secondary rounded-full overflow-hidden">
                                                        <div
                                                            className="h-full bg-primary rounded-full transition-all"
                                                            style={{ width: `${Math.min(p.percentOfTotal, 100)}%` } as React.CSSProperties}
                                                        />
                                                    </div>
                                                    <span className="text-xs font-mono w-12 text-right">{p.percentOfTotal}%</span>
                                                </div>
                                            </td>
                                            <td className="px-4 py-3 text-right">
                                                <button data-id={p.id} onClick={handleEditProductClick} className="p-2 hover:bg-secondary rounded-lg" aria-label="Edit product"><Edit size={14} /></button>
                                            </td>
                                        </tr>
                                        {/* Expanded Location Breakdown */}
                                        {isExpanded && (
                                            <tr key={`${p.id}-expanded`} className="bg-secondary/10">
                                                <td colSpan={11} className="px-4 py-3">
                                                    <div className="ml-8 space-y-1">
                                                        <div className="text-[10px] font-bold uppercase text-muted-foreground mb-2">Stock by Location</div>
                                                        {p.locationBreakdown.map((loc: LocationBreakdown) => (
                                                            <div key={loc.locationId} className="flex items-center gap-3 text-sm py-1.5 px-3 rounded-lg hover:bg-secondary/30">
                                                                <MapPin size={14} className={loc.locationType === 'WAREHOUSE' ? 'text-blue-500' : 'text-orange-500'} />
                                                                <span className="font-medium flex-1">{loc.locationName}</span>
                                                                <span className={clsx(
                                                                    "px-2 py-0.5 rounded text-[10px] font-bold",
                                                                    loc.locationType === 'WAREHOUSE' ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'
                                                                )}>
                                                                    {loc.locationType}
                                                                </span>
                                                                <span className="font-bold font-mono w-16 text-right">{loc.quantity}</span>
                                                            </div>
                                                        ))}
                                                    </div>
                                                </td>
                                            </tr>
                                        )}
                                    </>
                                );
                            })
                        )}
                    </tbody>
                </table>

                {/* Pagination */}
                {totalPages > 1 && (
                    <div className="px-6 py-4 border-t border-border flex items-center justify-between bg-secondary/10">
                        <div className="text-sm text-muted-foreground">
                            Showing {((currentPage - 1) * ITEMS_PER_PAGE) + 1} - {Math.min(currentPage * ITEMS_PER_PAGE, filteredAndSortedItems.length)} of {filteredAndSortedItems.length}
                        </div>
                        <div className="flex items-center gap-2">
                            <button
                                onClick={handlePrevPage}
                                disabled={currentPage === 1}
                                className="p-2 rounded-lg border border-border hover:bg-secondary disabled:opacity-30 disabled:cursor-not-allowed"
                            >
                                <ChevronLeft size={16} />
                            </button>
                            <div className="flex gap-1">
                                {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                                    let page;
                                    if (totalPages <= 5) {
                                        page = i + 1;
                                    } else if (currentPage <= 3) {
                                        page = i + 1;
                                    } else if (currentPage >= totalPages - 2) {
                                        page = totalPages - 4 + i;
                                    } else {
                                        page = currentPage - 2 + i;
                                    }
                                    return (
                                        <button
                                            key={page}
                                            data-page={page}
                                            onClick={handlePageChange}
                                            className={clsx(
                                                "w-8 h-8 rounded-lg text-sm font-medium",
                                                currentPage === page ? "bg-primary text-primary-foreground" : "hover:bg-secondary"
                                            )}
                                        >
                                            {page}
                                        </button>
                                    );
                                })}
                            </div>
                            <button
                                onClick={handleNextPage}
                                disabled={currentPage >= totalPages}
                                className="p-2 rounded-lg border border-border hover:bg-secondary disabled:opacity-30 disabled:cursor-not-allowed"
                            >
                                <ChevronRight size={16} />
                            </button>
                        </div>
                    </div>
                )}
            </div>

            {/* Product Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <div className="bg-card w-full max-w-lg rounded-2xl border border-border shadow-2xl overflow-hidden">
                        <div className="p-6 border-b border-border flex items-center justify-between bg-primary/5">
                            <h3 className="text-xl font-bold">{isEditMode ? 'Edit Product' : 'Add New Product'}</h3>
                            <button onClick={handleCloseModal} className="p-1 hover:bg-secondary rounded-full"><X size={20} /></button>
                        </div>
                        <form onSubmit={handleSubmit} className="p-6 space-y-4">
                            {error && <div className="p-3 bg-red-50 border border-red-200 rounded-lg text-red-600 text-sm flex items-center gap-2"><AlertCircle size={16} />{error}</div>}
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1.5 col-span-2 sm:col-span-1">
                                    <label className="text-xs font-bold uppercase text-muted-foreground">Product Name</label>
                                    <input type="text" className="w-full p-3 rounded-xl border border-border bg-background" required value={formData.name} onChange={handleFormNameChange} />
                                </div>
                                <div className="space-y-1.5 col-span-2 sm:col-span-1">
                                    <label className="text-xs font-bold uppercase text-muted-foreground">SKU</label>
                                    <input type="text" className="w-full p-3 rounded-xl border border-border bg-background" required value={formData.sku} onChange={handleFormSkuChange} />
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1.5">
                                    <label className="text-xs font-bold uppercase text-muted-foreground">Category</label>
                                    <select className="w-full p-3 rounded-xl border border-border bg-background" required value={formData.categoryId} onChange={handleFormCategoryChange}>
                                        <option value="">Select Category</option>
                                        {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-xs font-bold uppercase text-muted-foreground">Unit</label>
                                    <select className="w-full p-3 rounded-xl border border-border bg-background" value={formData.unit} onChange={handleFormUnitChange}>
                                        <option value="piece">Piece</option>
                                        <option value="kg">Kilogram</option>
                                        <option value="carton">Carton</option>
                                        <option value="liter">Liter</option>
                                    </select>
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1.5">
                                    <label className="text-xs font-bold uppercase text-muted-foreground">Cost Price (EGP)</label>
                                    <input type="number" step="0.01" className="w-full p-3 rounded-xl border border-border bg-background" required value={formData.costPrice} onChange={handleFormCostChange} />
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-xs font-bold uppercase text-muted-foreground">Selling Price (EGP)</label>
                                    <input type="number" step="0.01" className="w-full p-3 rounded-xl border border-border bg-background" required value={formData.baseSellingPrice} onChange={handleFormPriceChange} />
                                </div>
                            </div>
                            {!isEditMode && (
                                <div className="space-y-1.5 p-4 bg-primary/5 rounded-xl border border-primary/20">
                                    <label className="text-xs font-bold uppercase text-primary">Opening Stock</label>
                                    <input type="number" className="w-full p-3 rounded-lg border border-border bg-background" required min="0" value={formData.initialQuantity} onChange={handleFormQtyChange} />
                                </div>
                            )}
                            <div className="pt-6 flex gap-3">
                                <button type="button" onClick={handleCloseModal} className="flex-1 px-4 py-3 rounded-xl border border-border hover:bg-secondary font-semibold">Cancel</button>
                                <button type="submit" disabled={submitting} className="flex-1 px-4 py-3 rounded-xl bg-primary text-primary-foreground font-bold hover:bg-primary/90 disabled:opacity-50 flex items-center justify-center gap-2">
                                    {submitting ? <Loader2 className="animate-spin" size={18} /> : (isEditMode ? <Check size={18} /> : <Plus size={18} />)}
                                    {isEditMode ? 'Update' : 'Create'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Category Management Modal */}
            {isCategoryModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <div className="bg-card w-full max-w-md rounded-2xl border border-border shadow-2xl overflow-hidden">
                        <div className="p-6 border-b border-border flex items-center justify-between bg-primary/5">
                            <h3 className="text-xl font-bold flex items-center gap-2">
                                <FolderPlus size={20} />
                                إدارة الفئات
                                <span className="text-xs font-normal text-muted-foreground">Manage Categories</span>
                            </h3>
                            <button onClick={handleCloseCategoryModal} className="p-1 hover:bg-secondary rounded-full"><X size={20} /></button>
                        </div>
                        <div className="p-6 space-y-4">
                            {categoryError && (
                                <div className="p-3 bg-red-50 border border-red-200 rounded-lg text-red-600 text-sm">{categoryError}</div>
                            )}

                            {/* Add New Category Form */}
                            <form onSubmit={handleAddCategory} className="flex gap-2">
                                <input
                                    type="text"
                                    placeholder="New category name..."
                                    value={newCategoryName}
                                    onChange={handleNewCategoryNameChange}
                                    className="flex-1 p-3 rounded-xl border border-border bg-background"
                                />
                                <button
                                    type="submit"
                                    disabled={categorySubmitting || !newCategoryName.trim()}
                                    className="px-4 py-3 bg-primary text-primary-foreground rounded-xl font-bold hover:bg-primary/90 disabled:opacity-50 flex items-center gap-2"
                                >
                                    {categorySubmitting ? <Loader2 className="animate-spin" size={16} /> : <Plus size={16} />}
                                    Add
                                </button>
                            </form>

                            {/* Existing Categories List */}
                            <div className="space-y-2 max-h-[300px] overflow-y-auto">
                                {categories.length === 0 ? (
                                    <div className="text-center py-8 text-muted-foreground">No categories yet.</div>
                                ) : (
                                    categories.map(cat => (
                                        <div key={cat.id} className="flex items-center justify-between p-3 bg-secondary/30 rounded-xl group">
                                            <div>
                                                <span className="font-semibold">{cat.name}</span>
                                                <span className="ml-2 text-xs text-muted-foreground">
                                                    ({cat._count?.products || 0} products)
                                                </span>
                                            </div>
                                            <button
                                                data-id={cat.id}
                                                onClick={handleDeleteCategoryClick}
                                                disabled={categorySubmitting || (cat._count?.products || 0) > 0}
                                                className="p-2 text-red-500 hover:bg-red-50 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity disabled:opacity-30 disabled:cursor-not-allowed"
                                                title={(cat._count?.products || 0) > 0 ? "Cannot delete: has products" : "Delete category"}
                                            >
                                                <Trash2 size={14} />
                                            </button>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { RefreshCcw, Search, Calendar, Loader2, FileText, X, AlertTriangle, User } from 'lucide-react';
import { getRefunds } from '@/app/actions/refunds';
import clsx from 'clsx';

interface RefundItem {
    id: string;
    product: { name: string; sku: string };
    quantity: number;
    unitPrice: number;
    subtotal: number;
    condition: string;
}

interface Refund {
    id: string;
    invoiceId: string;
    totalAmount: number;
    reason: string | null;
    createdAt: Date;
    user: { name: string | null, username: string };
    invoice: { customerName: string | null, customerPhone: string | null };
    items: RefundItem[];
}

export default function RefundHistoryPage() {
    const [refunds, setRefunds] = useState<Refund[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedRefund, setSelectedRefund] = useState<Refund | null>(null);

    // Date Filter State
    const [showDateFilter, setShowDateFilter] = useState(false);
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    const fetchRefunds = async () => {
        setLoading(true);
        try {
            const data = await getRefunds();
            setRefunds(data as Refund[]);
        } catch (error) {
            console.error('Failed to fetch refunds:', error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchRefunds();
    }, []);

    const filteredRefunds = refunds.filter(ref => {
        const query = searchQuery.toLowerCase();
        const matchesSearch = (
            ref.invoiceId.toLowerCase().includes(query) ||
            (ref.invoice.customerName && ref.invoice.customerName.toLowerCase().includes(query)) ||
            (ref.user.username.toLowerCase().includes(query)) ||
            (ref.reason && ref.reason.toLowerCase().includes(query))
        );

        const refDate = new Date(ref.createdAt);
        const matchesDate =
            (!startDate || refDate >= new Date(startDate)) &&
            (!endDate || refDate <= new Date(new Date(endDate).setHours(23, 59, 59)));

        return matchesSearch && matchesDate;
    });

    const handleToggleDateFilter = useCallback(() => setShowDateFilter(prev => !prev), []);
    const handleSearchQueryChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setSearchQuery(e.target.value), []);
    const handleStartDateChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setStartDate(e.target.value), []);
    const handleEndDateChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setEndDate(e.target.value), []);
    const handleResetFilters = useCallback(() => {
        setStartDate('');
        setEndDate('');
    }, []);
    
    const handleSelectRefundClick = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) {
            const found = refunds.find(r => r.id === id);
            if (found) setSelectedRefund(found);
        }
    }, [refunds]);
    
    const handleCloseMemoClick = useCallback(() => setSelectedRefund(null), []);
    const handlePrintInvoiceClick = useCallback(() => {
        if (selectedRefund?.invoiceId) {
            window.open(`/invoices/${selectedRefund.invoiceId}/print`, '_blank');
        }
    }, [selectedRefund]);

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
                <div className="flex items-center gap-3">
                    <div className="p-3 bg-red-100 dark:bg-red-950/30 text-red-600 rounded-xl shadow-sm">
                        <RefreshCcw size={28} />
                    </div>
                    <div>
                        <h2 className="text-3xl font-black tracking-tighter uppercase">Refund History</h2>
                        <p className="text-sm text-muted-foreground">Track all product returns and financial reversals</p>
                    </div>
                </div>
                <div className="flex gap-2">
                    <button
                        onClick={handleToggleDateFilter}
                        className={clsx(
                            "flex items-center gap-2 px-4 py-2 border rounded-xl transition-all font-bold text-sm",
                            showDateFilter ? "bg-red-50 border-red-200 text-red-600 dark:bg-red-950/20 dark:border-red-800" : "bg-card border-border hover:bg-secondary"
                        )}
                    >
                        <Calendar size={16} />
                        Filter Date
                    </button>
                    <button
                        onClick={fetchRefunds}
                        className="p-2 bg-card border border-border hover:bg-secondary rounded-xl transition-colors"
                        title="Refresh Data"
                    >
                        <Loader2 className={clsx(loading && "animate-spin")} size={20} />
                    </button>
                </div>
            </div>

            {/* Filters */}
            <div className="flex items-center gap-4 bg-card p-4 rounded-2xl border border-border shadow-sm focus-within:ring-2 focus-within:ring-primary/10 transition-all">
                <Search className="text-muted-foreground" size={18} />
                <input
                    placeholder="Search by Invoice ID, Customer, or Staff..."
                    className="flex-1 bg-transparent outline-none text-sm"
                    value={searchQuery}
                    onChange={handleSearchQueryChange}
                />
            </div>

            {/* Date Range Inputs */}
            {showDateFilter && (
                <div className="flex flex-wrap items-center gap-4 p-4 bg-card rounded-2xl border border-border animate-in slide-in-from-top-2 shadow-sm">
                    <div className="flex items-center gap-2">
                        <label className="text-xs font-bold uppercase text-muted-foreground">From:</label>
                        <input
                            type="date"
                            value={startDate}
                            onChange={handleStartDateChange}
                            className="bg-secondary/40 border-none rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary/20 outline-none"
                        />
                    </div>
                    <div className="flex items-center gap-2">
                        <label className="text-xs font-bold uppercase text-muted-foreground">To:</label>
                        <input
                            type="date"
                            value={endDate}
                            onChange={handleEndDateChange}
                            className="bg-secondary/40 border-none rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary/20 outline-none"
                        />
                    </div>
                    <button
                        onClick={handleResetFilters}
                        className="text-xs font-bold text-red-500 hover:text-red-600 transition-colors uppercase ml-auto"
                    >
                        Reset Filters
                    </button>
                </div>
            )}

            {/* Refund List */}
            <div className="grid grid-cols-1 gap-4">
                {loading && refunds.length === 0 ? (
                    <div className="flex flex-col items-center justify-center p-12 text-muted-foreground bg-card rounded-2xl border border-dashed border-border">
                        <Loader2 className="animate-spin mb-4" size={32} />
                        <p className="font-medium">Loading refund history...</p>
                    </div>
                ) : filteredRefunds.length === 0 ? (
                    <div className="flex flex-col items-center justify-center p-12 text-muted-foreground bg-card rounded-2xl border border-dashed border-border">
                        <X size={32} className="mb-4 opacity-20" />
                        <p className="font-medium">No refund records found matching your search.</p>
                    </div>
                ) : (
                    filteredRefunds.map(ref => (
                        <div
                            key={ref.id}
                            data-id={ref.id}
                            onClick={handleSelectRefundClick}
                            className="group flex flex-col md:flex-row md:items-center justify-between p-5 bg-card border border-border rounded-2xl hover:border-red-200 dark:hover:border-red-900 hover:shadow-lg transition-all cursor-pointer gap-4 relative overflow-hidden"
                        >
                            <div className="absolute top-0 left-0 w-1 h-full bg-red-500 opacity-0 group-hover:opacity-100 transition-opacity" />

                            <div className="flex items-center gap-4">
                                <div className="p-3 bg-red-50 dark:bg-red-950/20 text-red-600 rounded-xl transition-transform group-hover:scale-110">
                                    <RefreshCcw size={24} />
                                </div>
                                <div className="space-y-1">
                                    <div className="font-black text-lg flex items-center gap-2 uppercase tracking-tight">
                                        {ref.invoice.customerName || 'Walk-in Customer'}
                                        {ref.reason && <span className="text-[10px] font-bold bg-secondary px-2 py-0.5 rounded-full text-muted-foreground">WITH REASON</span>}
                                    </div>
                                    <div className="text-xs text-muted-foreground flex flex-wrap items-center gap-y-1 gap-x-3 font-medium">
                                        <span className="flex items-center gap-1"><FileText size={12} /> Invoice #{ref.invoiceId.slice(0, 8).toUpperCase()}</span>
                                        <span className="hidden sm:inline">•</span>
                                        <span className="flex items-center gap-1"><Calendar size={12} /> {new Date(ref.createdAt).toLocaleDateString()}</span>
                                        <span className="hidden sm:inline">•</span>
                                        <span className="flex items-center gap-1 text-primary"><User size={12} /> @{ref.user.username}</span>
                                    </div>
                                </div>
                            </div>

                            <div className="flex items-center gap-4 md:gap-8 justify-between md:justify-end">
                                <div className="text-right">
                                    <div className="text-2xl font-black text-red-600 tabular-nums">
                                        - EGP {Number(ref.totalAmount).toLocaleString()}
                                    </div>
                                    <div className="text-[10px] font-bold uppercase text-muted-foreground tracking-widest mt-1">
                                        {ref.items.length} ITEM{ref.items.length !== 1 ? 'S' : ''} REFUNDED
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))
                )}
            </div>

            {/* Refund Details Modal */}
            {selectedRefund && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-card w-full max-w-2xl rounded-3xl border border-border shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 flex flex-col max-h-[90vh]">
                        <div className="p-6 border-b border-border flex items-center justify-between bg-red-50/50 dark:bg-red-950/10">
                            <div>
                                <h3 className="text-xl font-black uppercase tracking-tight flex items-center gap-2">
                                    Refund Memo
                                </h3>
                                <p className="text-[10px] text-muted-foreground font-mono mt-1">REF_ID: {selectedRefund.id}</p>
                            </div>
                            <button onClick={handleCloseMemoClick} className="p-2 hover:bg-secondary rounded-full transition-colors">
                                <X size={20} />
                            </button>
                        </div>

                        <div className="flex-1 overflow-y-auto p-6 space-y-6">
                            {/* Information Grid */}
                            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                                <div className="p-4 bg-secondary/20 rounded-2xl border border-border shadow-sm">
                                    <label className="text-[10px] font-black uppercase text-muted-foreground mb-1 block">Staff</label>
                                    <div className="text-sm font-bold flex items-center gap-2">
                                        <User size={14} className="text-primary" />
                                        @{selectedRefund.user.username}
                                    </div>
                                </div>
                                <div className="p-4 bg-secondary/20 rounded-2xl border border-border shadow-sm">
                                    <label className="text-[10px] font-black uppercase text-muted-foreground mb-1 block">Customer</label>
                                    <div className="text-sm font-bold truncate">
                                        {selectedRefund.invoice.customerName || 'Walk-in'}
                                    </div>
                                </div>
                                <div className="p-4 bg-secondary/20 rounded-2xl border border-border shadow-sm col-span-2 md:col-span-1">
                                    <label className="text-[10px] font-black uppercase text-muted-foreground mb-1 block">Date</label>
                                    <div className="text-sm font-bold">
                                        {new Date(selectedRefund.createdAt).toLocaleString()}
                                    </div>
                                </div>
                            </div>

                            {/* Reason Box */}
                            <div className="p-4 bg-amber-50 dark:bg-amber-950/20 border border-amber-200 dark:border-amber-800 rounded-2xl shadow-sm">
                                <label className="text-[10px] font-black uppercase text-amber-600 dark:text-amber-400 mb-2 block flex items-center gap-1">
                                    <AlertTriangle size={12} /> Reason for Refund
                                </label>
                                <p className="text-sm italic text-amber-900 dark:text-amber-200 leading-relaxed font-medium">
                                    {selectedRefund.reason || 'No specific reason provided for this transaction.'}
                                </p>
                            </div>

                            {/* Items List */}
                            <div className="space-y-3">
                                <div className="flex items-center justify-between px-1">
                                    <h4 className="font-black text-[10px] uppercase tracking-widest text-muted-foreground">Returned Items</h4>
                                    <span className="text-[10px] font-bold text-red-500 uppercase">Financial Reversal</span>
                                </div>
                                <div className="border border-border rounded-2xl overflow-hidden shadow-sm bg-card">
                                    <table className="w-full text-sm">
                                        <thead className="bg-secondary/30 text-muted-foreground">
                                            <tr>
                                                <th className="px-4 py-3 text-left font-black text-[10px] uppercase">Item Details</th>
                                                <th className="px-4 py-3 text-center font-black text-[10px] uppercase">Cond.</th>
                                                <th className="px-4 py-3 text-center font-black text-[10px] uppercase">Qty</th>
                                                <th className="px-4 py-3 text-right font-black text-[10px] uppercase">Price</th>
                                                <th className="px-4 py-3 text-right font-black text-[10px] uppercase">Total</th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-border">
                                            {selectedRefund.items.map(item => (
                                                <tr key={item.id} className="hover:bg-muted/30">
                                                    <td className="px-4 py-4">
                                                        <div className="font-bold text-sm tracking-tight">{item.product.name}</div>
                                                        <div className="text-[10px] font-mono text-muted-foreground uppercase">{item.product.sku}</div>
                                                    </td>
                                                    <td className="px-4 py-4 text-center">
                                                        <span className={clsx(
                                                            "text-[10px] font-black px-2 py-0.5 rounded-full border shadow-sm",
                                                            item.condition === 'NEW' ? "bg-green-100 text-green-700 border-green-200" : "bg-red-100 text-red-700 border-red-200"
                                                        )}>
                                                            {item.condition}
                                                        </span>
                                                    </td>
                                                    <td className="px-4 py-4 text-center font-mono font-bold">{item.quantity}</td>
                                                    <td className="px-4 py-4 text-right font-mono text-xs">EGP {item.unitPrice.toLocaleString()}</td>
                                                    <td className="px-4 py-4 text-right font-mono font-black text-red-600">- EGP {item.subtotal.toLocaleString()}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                        <tfoot className="bg-red-50/50 dark:bg-red-950/10 font-black border-t-2 border-red-100 dark:border-red-900/50">
                                            <tr>
                                                <td colSpan={4} className="px-4 py-5 text-right text-xs uppercase tracking-widest text-muted-foreground font-bold">Grand Total Reversed</td>
                                                <td className="px-4 py-5 text-right text-red-600 text-xl font-black tabular-nums">- EGP {Number(selectedRefund.totalAmount).toLocaleString()}</td>
                                            </tr>
                                        </tfoot>
                                    </table>
                                </div>
                            </div>
                        </div>

                        <div className="p-6 border-t border-border bg-secondary/5 flex gap-3">
                            <button
                                onClick={handlePrintInvoiceClick}
                                className="flex-1 flex items-center justify-center gap-2 py-3 bg-card border border-border rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-secondary transition-all active:scale-95 shadow-sm"
                            >
                                <FileText size={16} />
                                View Source Invoice
                            </button>
                            <button
                                onClick={handleCloseMemoClick}
                                className="flex-1 py-4 bg-primary text-primary-foreground rounded-2xl font-black text-xs uppercase tracking-widest hover:opacity-90 transition-all active:scale-95 shadow-xl shadow-primary/20"
                            >
                                Close Memo
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { Search, ShoppingCart, Trash2, Plus, Minus, Loader2, Check, User, ChevronDown, AlertCircle, AlertTriangle, X, CreditCard, Banknote, Smartphone } from 'lucide-react';
import { getProducts, processSale, getCategories, getStaffList } from '@/app/actions/sales';
import { searchCustomers } from '@/app/actions/customers';
import { getCurrentUser } from '@/app/actions/auth';
import clsx from 'clsx';

interface Product {
    id: string;
    name: string;
    sku: string;
    baseSellingPrice: number;
    categoryId: string;
    category?: { id: string; name: string };
    stock: number;
}

interface CartItem {
    product: Product;
    quantity: number;
}

interface Staff {
    id: string;
    name: string | null;
    username: string;
}

interface CustomerSearch {
    id: string;
    name: string;
    phone: string | null;
    address: string | null;
    type: string;
}

type PaymentMethodType = 'CASH' | 'CREDIT' | 'INSTAPAY';

export default function SalesPage() {
    const [cart, setCart] = useState<CartItem[]>([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [categoryFilter, setCategoryFilter] = useState<string>('all');
    const [categories, setCategories] = useState<{ id: string; name: string }[]>([]);
    const [products, setProducts] = useState<Product[]>([]);
    const [loading, setLoading] = useState(true);
    const [processing, setProcessing] = useState(false);
    const [paymentMethod, setPaymentMethod] = useState<PaymentMethodType>('CASH');
    const [showSuccess, setShowSuccess] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [showConfirmDialog, setShowConfirmDialog] = useState(false);

    // Salesperson
    const [staffList, setStaffList] = useState<Staff[]>([]);
    const [selectedStaffId, setSelectedStaffId] = useState<string>('');

    // Discount & Notes
    const [discount, setDiscount] = useState<number | ''>('');
    const [orderNotes, setOrderNotes] = useState('');

    // Buyer info state
    const [buyerInfo, setBuyerInfo] = useState({
        customerName: '',
        customerPhone: '',
        customerAddress: ''
    });

    // Customer Search State
    const [searchResults, setSearchResults] = useState<CustomerSearch[]>([]);
    const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
    const [amountPaid, setAmountPaid] = useState<number | ''>('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isSearching, setIsSearching] = useState(false);
    const searchTimeoutRef = useRef<NodeJS.Timeout | null>(null);

    const handleBuyerInfoChange = useCallback((field: string, val: string) => {
        setBuyerInfo(prev => ({ ...prev, [field]: val }));
        if (field !== 'customerName' && field !== 'customerPhone') return;
        if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current);
        if (val.length < 2) { setSearchResults([]); setShowSuggestions(false); return; }
        setIsSearching(true);
        searchTimeoutRef.current = setTimeout(async () => {
            const results = await searchCustomers(val);
            setSearchResults(results);
            setShowSuggestions(results.length > 0);
            setIsSearching(false);
        }, 300);
    }, []);

    const selectCustomer = useCallback((cust: CustomerSearch) => {
        setBuyerInfo({ customerName: cust.name, customerPhone: cust.phone || '', customerAddress: cust.address || '' });
        setSelectedCustomerId(cust.id);
        setShowSuggestions(false);
    }, []);

    const clearCustomer = useCallback(() => {
        setBuyerInfo({ customerName: '', customerPhone: '', customerAddress: '' });
        setSelectedCustomerId(null);
    }, []);

    useEffect(() => {
        Promise.all([getProducts(), getCategories(), getStaffList(), getCurrentUser()]).then(([prods, cats, staff, user]) => {
            setProducts(prods);
            setCategories(cats);
            setStaffList(staff);
            setLoading(false);
            if (user && staff.some(s => s.id === user.id)) {
                setSelectedStaffId(user.id);
            }
        });
    }, []);

    const addToCart = useCallback((product: Product) => {
        setCart(prev => {
            const currentInCart = prev.find(item => item.product.id === product.id)?.quantity || 0;
            if (currentInCart >= product.stock) {
                setError(`Cannot add more ${product.name}. Only ${product.stock} in stock.`);
                setTimeout(() => setError(null), 3000);
                return prev;
            }
            const existing = prev.find(item => item.product.id === product.id);
            if (existing) {
                return prev.map(item =>
                    item.product.id === product.id
                        ? { ...item, quantity: item.quantity + 1 }
                        : item
                );
            }
            return [...prev, { product, quantity: 1 }];
        });
    }, []);

    const updateQuantity = useCallback((productId: string, delta: number) => {
        setCart(prev => {
            return prev.map(item => {
                if (item.product.id === productId) {
                    const newQty = item.quantity + delta;
                    if (newQty <= 0) return null;
                    if (delta > 0 && newQty > item.product.stock) {
                        setError(`Cannot add more. Only ${item.product.stock} in stock.`);
                        setTimeout(() => setError(null), 3000);
                        return item;
                    }
                    return { ...item, quantity: newQty };
                }
                return item;
            }).filter(Boolean) as CartItem[];
        });
    }, []);

    const handleCheckoutClick = () => {
        if (cart.length === 0) return;

        // Validation: Require customer data
        if (!selectedCustomerId && !buyerInfo.customerName.trim()) {
            setError('Please enter a customer name or select an existing customer.');
            setTimeout(() => setError(null), 3000);
            return;
        }

        // Validation: Walk-in (non-registered) customers must pay full amount
        if (!selectedCustomerId) {
            if (paymentMethod === 'CASH') {
                const paid = typeof amountPaid === 'number' ? amountPaid : 0;
                if (paid < total) {
                    setError('Walk-in customers must pay the full amount. No debt allowed.');
                    setTimeout(() => setError(null), 3000);
                    return;
                }
            }
            // For CREDIT/INSTAPAY walk-ins, auto-set amountPaid to total (exact payment)
            if (paymentMethod !== 'CASH') {
                setAmountPaid(total);
            }
        }

        setShowConfirmDialog(true);
    };

    const handleConfirmCheckout = async () => {
        setShowConfirmDialog(false);
        setProcessing(true);
        setError(null);
        try {
            const result = await processSale(
                cart.map(item => ({ productId: item.product.id, quantity: item.quantity })),
                paymentMethod,
                buyerInfo.customerName ? buyerInfo : undefined,
                undefined,
                selectedStaffId,
                amountPaid === '' ? undefined : amountPaid,
                selectedCustomerId || undefined
            );

            if (result.success) {
                setShowSuccess(true);
                setCart([]);
                setBuyerInfo({ customerName: '', customerPhone: '', customerAddress: '' });
                setSelectedCustomerId(null);
                setAmountPaid('');
                setDiscount('');
                setOrderNotes('');
                setTimeout(() => setShowSuccess(false), 3000);
                getProducts().then(setProducts);
            } else {
                setError(result.error || 'Failed to process sale.');
            }
        } catch (err) {
            console.error(err);
            setError('Connection error. Please check your internet and try again.');
        } finally {
            setProcessing(false);
        }
    };

    const subtotal = cart.reduce((sum, item) => sum + (item.product.baseSellingPrice * item.quantity), 0);
    const validDiscount = typeof discount === 'number' ? discount : 0;
    const discountAmount = validDiscount > 0 ? (subtotal * validDiscount / 100) : 0;
    const total = subtotal - discountAmount;

    const filteredProducts = products.filter(p => {
        const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || p.sku.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesCategory = categoryFilter === 'all' || p.categoryId === categoryFilter;
        return matchesSearch && matchesCategory;
    });

    const addQuickCash50 = useCallback(() => setAmountPaid(prev => (typeof prev === 'number' ? prev + 50 : 50)), []);
    const addQuickCash100 = useCallback(() => setAmountPaid(prev => (typeof prev === 'number' ? prev + 100 : 100)), []);
    const addQuickCash200 = useCallback(() => setAmountPaid(prev => (typeof prev === 'number' ? prev + 200 : 200)), []);
    const setExactCash = useCallback(() => setAmountPaid(total), [total]);
    const handleSearchChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setSearchQuery(e.target.value), []);
    const handleNotesChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setOrderNotes(e.target.value), []);
    const handleDiscountChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setDiscount(e.target.value === '' ? '' : Math.min(100, Math.max(0, parseInt(e.target.value) || 0))), []);
    const handleAmountPaidChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setAmountPaid(e.target.value === '' ? '' : parseFloat(e.target.value)), []);
    const handleStaffChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => setSelectedStaffId(e.target.value), []);
    const handleCustomerNameChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => handleBuyerInfoChange('customerName', e.target.value), [handleBuyerInfoChange]);
    const handleCustomerPhoneChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => handleBuyerInfoChange('customerPhone', e.target.value), [handleBuyerInfoChange]);
    const handleCustomerAddressChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => handleBuyerInfoChange('customerAddress', e.target.value), [handleBuyerInfoChange]);
    const handleCloseConfirmDialog = useCallback(() => setShowConfirmDialog(false), []);
    const setCategoryAll = useCallback(() => setCategoryFilter('all'), []);

    const handleCategorySelect = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) setCategoryFilter(id);
    }, []);

    const handleAddProductToCart = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) {
            const product = products.find(p => p.id === id);
            if (product) {
                if (product.stock === 0) return;
                const quantity = cart.find(item => item.product.id === id)?.quantity || 0;
                if (quantity === 0) addToCart(product);
            }
        }
    }, [products, cart, addToCart]);

    const handleDecrementQuantity = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        e.stopPropagation();
        const id = e.currentTarget.dataset.id;
        if (id) updateQuantity(id, -1);
    }, [updateQuantity]);

    const handleIncrementQuantity = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        e.stopPropagation();
        const id = e.currentTarget.dataset.id;
        if (id) updateQuantity(id, 1);
    }, [updateQuantity]);

    const handleSelectCustomerClick = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) {
            const cust = searchResults.find(c => c.id === id);
            if (cust) selectCustomer(cust);
        }
    }, [searchResults, selectCustomer]);

    const handlePaymentMethodSelect = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const methodId = e.currentTarget.dataset.id as PaymentMethodType;
        if (methodId) {
            setPaymentMethod(methodId);
            if (methodId !== 'CASH') setAmountPaid(total);
            else setAmountPaid('');
        }
    }, [total]);

    return (
        <div className="flex flex-col lg:flex-row h-[calc(100vh-6rem)] gap-6 overflow-hidden max-w-7xl mx-auto w-full pb-4">
            {/* Main Product Area */}
            <div className="flex-1 flex flex-col gap-6 min-w-0">
                {/* Search & Filter Header */}
                <div className="flex flex-col sm:flex-row items-center gap-4 bg-card/60 backdrop-blur-xl p-4 rounded-3xl border border-border/50 shadow-sm">
                    <div className="flex items-center flex-1 w-full bg-background/50 rounded-2xl px-4 py-3 border border-border/50 focus-within:ring-2 focus-within:ring-primary/20 focus-within:border-primary/50 transition-all">
                        <Search className="text-muted-foreground shrink-0 mr-3" size={20} />
                        <input
                            className="bg-transparent outline-none flex-1 text-sm font-medium placeholder:text-muted-foreground/60 w-full"
                            placeholder="Search products by name or SKU..."
                            value={searchQuery}
                            onChange={handleSearchChange}
                        />
                    </div>

                    <div className="w-full sm:w-auto overflow-x-auto pb-1 sm:pb-0 scrollbar-none">
                        <div className="flex items-center gap-2">
                            <button
                                onClick={setCategoryAll}
                                className={clsx(
                                    "px-5 py-2.5 rounded-2xl text-sm font-bold transition-all whitespace-nowrap",
                                    categoryFilter === 'all' 
                                        ? "bg-primary text-primary-foreground shadow-md" 
                                        : "bg-secondary/50 text-muted-foreground hover:bg-secondary hover:text-foreground"
                                )}
                            >
                                All items
                            </button>
                            {categories.map(c => (
                                <button
                                    key={c.id}
                                    data-id={c.id}
                                    onClick={handleCategorySelect}
                                    className={clsx(
                                        "px-5 py-2.5 rounded-2xl text-sm font-bold transition-all whitespace-nowrap",
                                        categoryFilter === c.id 
                                            ? "bg-primary text-primary-foreground shadow-md" 
                                            : "bg-secondary/50 text-muted-foreground hover:bg-secondary hover:text-foreground"
                                    )}
                                >
                                    {c.name}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                {/* Product Grid */}
                <div className="flex-1 overflow-y-auto rounded-3xl pr-2">
                    {loading ? (
                        <div className="flex flex-col items-center justify-center h-full text-muted-foreground/60 gap-4">
                            <div className="p-4 bg-secondary/30 rounded-full">
                                <Loader2 className="animate-spin" size={32} />
                            </div>
                            <span className="font-medium">Loading inventory...</span>
                        </div>
                    ) : (
                        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 pb-20">
                            {filteredProducts.map(product => {
                                const cartItem = cart.find(item => item.product.id === product.id);
                                const quantity = cartItem?.quantity || 0;
                                const isOutOfStock = product.stock === 0;
                                const isLowStock = product.stock > 0 && product.stock <= 5;

                                return (
                                    <div
                                        key={product.id}
                                        data-id={product.id}
                                        onClick={handleAddProductToCart}
                                        className={clsx(
                                            "group flex flex-col p-4 bg-card/40 backdrop-blur-sm border rounded-3xl relative overflow-hidden transition-all duration-300",
                                            isOutOfStock ? "border-red-200/50 bg-red-50/10 opacity-75" : "border-border/50 hover:border-primary/30 hover:shadow-xl hover:shadow-primary/5 cursor-pointer"
                                        )}
                                    >
                                        {/* Status Badges */}
                                        <div className="absolute top-3 left-3 flex flex-col gap-2 z-10">
                                            {isOutOfStock && (
                                                <div className="bg-red-500/90 backdrop-blur-md text-white px-2.5 py-1 rounded-full text-[10px] font-black uppercase tracking-wider shadow-sm flex items-center gap-1">
                                                    <X size={10} strokeWidth={3} /> Sold Out
                                                </div>
                                            )}
                                            {isLowStock && !isOutOfStock && (
                                                <div className="bg-amber-500/90 backdrop-blur-md text-white px-2.5 py-1 rounded-full text-[10px] font-black uppercase tracking-wider shadow-sm flex items-center gap-1">
                                                    <AlertTriangle size={10} strokeWidth={3} /> {product.stock} Left
                                                </div>
                                            )}
                                        </div>

                                        {/* Product Image Placeholder */}
                                        <div className={clsx(
                                            "w-full aspect-square rounded-2xl mb-4 flex items-center justify-center text-5xl font-black transition-all duration-500 relative overflow-hidden",
                                            isOutOfStock ? "bg-muted/30 text-muted-foreground/20" : "bg-gradient-to-br from-primary/5 to-primary/10 text-primary/40 group-hover:scale-105"
                                        )}>
                                            {product.name.charAt(0)}
                                            <div className="absolute inset-0 bg-gradient-to-t from-background/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
                                        </div>

                                        {/* Product Details */}
                                        <div className="flex flex-col flex-1">
                                            <div className="font-bold text-base line-clamp-1 group-hover:text-primary transition-colors">{product.name}</div>
                                            <div className="text-xs text-muted-foreground font-medium uppercase tracking-wider mt-1">{product.sku}</div>

                                            <div className="mt-auto pt-4 flex items-end justify-between gap-2">
                                                <div className="flex flex-col">
                                                    <span className="text-[10px] text-muted-foreground uppercase font-bold tracking-wider">Price</span>
                                                    <span className="font-black text-lg">EGP {product.baseSellingPrice.toLocaleString()}</span>
                                                </div>

                                                {/* Quantity Controls */}
                                                {!isOutOfStock && (
                                                    <div className={clsx(
                                                        "transition-all duration-300 overflow-hidden",
                                                        quantity > 0 ? "opacity-100 translate-y-0" : "opacity-0 translate-y-4 absolute right-4 bottom-4 pointer-events-none group-hover:opacity-100 group-hover:translate-y-0 group-hover:pointer-events-auto"
                                                    )}>
                                                        {quantity > 0 ? (
                                                            <div className="flex items-center gap-1 bg-primary/10 p-1 rounded-xl border border-primary/20 backdrop-blur-md">
                                                                <button
                                                                    data-id={product.id}
                                                                    onClick={handleDecrementQuantity}
                                                                    className="w-8 h-8 flex items-center justify-center bg-background rounded-lg hover:bg-red-50 hover:text-red-500 shadow-sm transition-all"
                                                                >
                                                                    {quantity === 1 ? <Trash2 size={14} /> : <Minus size={14} strokeWidth={3} />}
                                                                </button>
                                                                <span className="w-8 text-center font-black text-primary">{quantity}</span>
                                                                <button
                                                                    data-id={product.id}
                                                                    onClick={handleIncrementQuantity}
                                                                    disabled={quantity >= product.stock}
                                                                    className="w-8 h-8 flex items-center justify-center bg-primary text-primary-foreground rounded-lg shadow-sm hover:bg-primary/90 transition-all disabled:opacity-50 disabled:bg-primary"
                                                                >
                                                                    <Plus size={14} strokeWidth={3} />
                                                                </button>
                                                            </div>
                                                        ) : (
                                                            <div className="w-10 h-10 bg-primary text-primary-foreground rounded-xl flex items-center justify-center shadow-lg hover:scale-110 transition-transform">
                                                                <Plus size={20} strokeWidth={3} />
                                                            </div>
                                                        )}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>

            {/* Sidebar / Checkout Pane */}
            <div className="w-full lg:w-[420px] flex flex-col h-full shrink-0">
                <div className="bg-card/80 backdrop-blur-2xl border border-border/50 rounded-3xl flex flex-col h-full shadow-2xl overflow-hidden relative">

                    {/* Top Header & Cashier */}
                    <div className="px-6 py-4 flex items-center justify-between border-b border-border/30 bg-background/50">
                        <div className="flex items-center gap-2">
                            <div className="p-2 bg-primary/10 rounded-xl">
                                <ShoppingCart size={20} className="text-primary" />
                            </div>
                            <span className="font-extrabold text-lg">Current Order</span>
                        </div>
                        <div className="flex flex-col items-end">
                            <span className="text-[10px] text-muted-foreground font-bold uppercase tracking-wider">Cashier</span>
                            <select
                                value={selectedStaffId}
                                onChange={handleStaffChange}
                                className="bg-transparent text-sm font-bold text-primary outline-none cursor-pointer text-right max-w-[120px] truncate"
                            >
                                <option value="" disabled>Select Staff</option>
                                {staffList.map(emp => (
                                    <option key={emp.id} value={emp.id}>{emp.name || emp.username}</option>
                                ))}
                            </select>
                        </div>
                    </div>

                    {/* Customer Section */}
                    <div className="px-6 py-4 border-b border-border/30 bg-muted/10 relative z-20">
                        {!selectedCustomerId ? (
                            <div className="relative">
                                <div className="flex items-center bg-background border border-border/60 rounded-xl p-1 focus-within:ring-2 focus-within:ring-primary/20 transition-all">
                                    <div className="pl-3 text-muted-foreground">
                                        {isSearching ? <Loader2 size={16} className="animate-spin" /> : <User size={16} />}
                                    </div>
                                    <input
                                        type="text"
                                        placeholder="Add customer (Search by name or phone)"
                                        value={buyerInfo.customerName}
                                        onChange={handleCustomerNameChange}
                                        className="w-full bg-transparent p-2 text-sm outline-none font-medium placeholder:text-muted-foreground/60"
                                    />
                                </div>

                                {showSuggestions && searchResults.length > 0 && (
                                    <div className="absolute top-full left-0 right-0 mt-2 bg-popover border border-border/50 rounded-2xl shadow-xl overflow-hidden animate-in slide-in-from-top-2">
                                        {searchResults.map((cust, idx) => (
                                            <button
                                                key={idx}
                                                data-id={cust.id}
                                                onClick={handleSelectCustomerClick}
                                                className="w-full text-left px-4 py-3 hover:bg-secondary/50 border-b border-border/20 last:border-0 transition-colors flex items-center justify-between"
                                            >
                                                <div>
                                                    <div className="font-bold text-sm flex items-center gap-2">
                                                        {cust.name}
                                                        {cust.type === 'USER' && <span className="bg-primary/10 text-primary px-1.5 py-0.5 rounded-md text-[9px] font-black uppercase">Member</span>}
                                                    </div>
                                                    {cust.phone && <div className="text-xs text-muted-foreground mt-0.5 font-medium">{cust.phone}</div>}
                                                </div>
                                                <ChevronDown size={16} className="text-muted-foreground -rotate-90" />
                                            </button>
                                        ))}
                                    </div>
                                )}

                                {/* Quick inline manual info if no results but typed something */}
                                {buyerInfo.customerName.length > 2 && !showSuggestions && !isSearching && (
                                    <div className="mt-3 p-3 bg-primary/5 rounded-xl border border-primary/10 space-y-2 animate-in fade-in">
                                        <div className="text-xs font-bold text-primary mb-2 flex items-center gap-1">
                                            <Plus size={12} /> New Customer Entry
                                        </div>
                                        <div className="flex gap-2">
                                            <input
                                                type="tel"
                                                placeholder="Phone (Optional)"
                                                value={buyerInfo.customerPhone}
                                                onChange={handleCustomerPhoneChange}
                                                className="w-1/2 p-2 text-xs rounded-lg border border-border/50 bg-background outline-none focus:border-primary/50"
                                            />
                                            <input
                                                type="text"
                                                placeholder="Address (Optional)"
                                                value={buyerInfo.customerAddress}
                                                onChange={handleCustomerAddressChange}
                                                className="w-1/2 p-2 text-xs rounded-lg border border-border/50 bg-background outline-none focus:border-primary/50"
                                            />
                                        </div>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <div className="flex items-center justify-between bg-primary/5 border border-primary/20 p-3 rounded-xl">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 bg-primary/10 rounded-full flex items-center justify-center text-primary font-bold">
                                        {buyerInfo.customerName.charAt(0)}
                                    </div>
                                    <div>
                                        <div className="font-bold text-sm leading-tight">{buyerInfo.customerName}</div>
                                        {buyerInfo.customerPhone && <div className="text-xs text-muted-foreground font-medium">{buyerInfo.customerPhone}</div>}
                                    </div>
                                </div>
                                <button onClick={clearCustomer} className="p-2 text-muted-foreground hover:bg-red-50 hover:text-red-500 rounded-lg transition-colors">
                                    <X size={16} />
                                </button>
                            </div>
                        )}
                    </div>

                    {/* Cart Items List */}
                    <div className="flex-1 overflow-y-auto px-6 py-2">
                        {error && (
                            <div className="mb-4 p-3 bg-red-500/10 border border-red-500/20 rounded-xl text-red-600 text-xs font-bold flex items-center gap-2 animate-in slide-in-from-top-1">
                                <AlertCircle size={16} className="shrink-0" />
                                {error}
                            </div>
                        )}

                        {cart.length === 0 ? (
                            <div className="h-full flex flex-col items-center justify-center text-muted-foreground/40 gap-4">
                                <div className="w-24 h-24 rounded-full bg-secondary/50 flex items-center justify-center mb-2">
                                    <ShoppingCart size={40} strokeWidth={1.5} />
                                </div>
                                <div className="font-medium">Scan or add items to cart</div>
                            </div>
                        ) : (
                            <div className="space-y-1">
                                {cart.map(item => (
                                    <div key={item.product.id} className="group flex gap-4 py-3 border-b border-border/40 last:border-0 items-center">
                                        <div className="flex-1 min-w-0">
                                            <div className="font-bold text-sm text-foreground truncate">{item.product.name}</div>
                                            <div className="text-xs text-muted-foreground font-medium mt-0.5">EGP {item.product.baseSellingPrice.toLocaleString()}</div>
                                        </div>

                                        <div className="flex items-center gap-3 bg-secondary/50 p-1 rounded-xl">
                                            <button data-id={item.product.id} onClick={handleDecrementQuantity} className="w-7 h-7 flex items-center justify-center rounded-lg hover:bg-background shadow-sm transition-all text-muted-foreground hover:text-foreground">
                                                <Minus size={14} strokeWidth={2.5} />
                                            </button>
                                            <span className="font-black text-sm w-4 text-center">{item.quantity}</span>
                                            <button data-id={item.product.id} onClick={handleIncrementQuantity} disabled={item.quantity >= item.product.stock} className="w-7 h-7 flex items-center justify-center rounded-lg hover:bg-background shadow-sm transition-all text-muted-foreground hover:text-foreground disabled:opacity-30">
                                                <Plus size={14} strokeWidth={2.5} />
                                            </button>
                                        </div>

                                        <div className="text-right w-20 shrink-0">
                                            <div className="font-black text-sm">EGP {(item.product.baseSellingPrice * item.quantity).toLocaleString()}</div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Checkout Details & Actions */}
                    <div className="bg-background/80 backdrop-blur-xl border-t border-border/50 p-6 flex flex-col gap-4 z-20">
                        {/* Discount & Notes */}
                        <div className="flex gap-3">
                            <div className="relative flex-1">
                                <input
                                    type="text"
                                    placeholder="Add note..."
                                    value={orderNotes}
                                    onChange={handleNotesChange}
                                    className="w-full bg-secondary/30 border border-border/50 p-3 rounded-xl text-sm font-medium outline-none focus:border-primary/50 transition-colors"
                                />
                            </div>
                            <div className="relative w-28 shrink-0 group">
                                <input
                                    type="number"
                                    placeholder="Disc %"
                                    value={discount}
                                    onChange={handleDiscountChange}
                                    className="w-full bg-secondary/30 border border-border/50 p-3 pl-8 rounded-xl text-sm font-bold outline-none focus:border-primary/50 transition-colors"
                                />
                                <div className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground group-focus-within:text-primary font-bold">%</div>
                            </div>
                        </div>

                        {/* Totals */}
                        <div className="space-y-1.5 pt-2">
                            <div className="flex justify-between text-sm font-medium text-muted-foreground">
                                <span>Subtotal</span>
                                <span>EGP {subtotal.toLocaleString()}</span>
                            </div>
                            {validDiscount > 0 && (
                                <div className="flex justify-between text-sm font-bold text-red-500">
                                    <span>Discount ({validDiscount}%)</span>
                                    <span>-EGP {discountAmount.toLocaleString()}</span>
                                </div>
                            )}
                            <div className="flex justify-between items-end pt-3 pb-1">
                                <span className="font-bold text-muted-foreground uppercase tracking-wider text-xs mb-1">Total Due</span>
                                <span className="font-black text-4xl tracking-tight">EGP {total.toLocaleString()}</span>
                            </div>
                        </div>

                        {/* Payment Type Selection (Segmented Control) */}
                        <div className="bg-secondary/50 p-1.5 rounded-2xl flex gap-1 relative">
                            {[
                                { id: 'CASH', icon: Banknote, label: 'Cash' },
                                { id: 'CREDIT', icon: CreditCard, label: 'Card' },
                                { id: 'INSTAPAY', icon: Smartphone, label: 'InstaPay' }
                            ].map((method) => {
                                const isActive = paymentMethod === method.id;
                                const Icon = method.icon;
                                return (
                                    <button
                                        key={method.id}
                                        data-id={method.id}
                                        onClick={handlePaymentMethodSelect}
                                        className={clsx(
                                            "flex-1 flex flex-col items-center justify-center py-2.5 rounded-xl font-bold text-xs transition-all duration-300 relative z-10 gap-1",
                                            isActive ? "text-foreground shadow-sm" : "text-muted-foreground hover:text-foreground"
                                        )}
                                    >
                                        {isActive && <div className="absolute inset-0 bg-background rounded-xl -z-10 shadow-sm" />}
                                        <Icon size={16} />
                                        {method.label}
                                    </button>
                                );
                            })}
                        </div>

                        {/* Amount Paid section (Prominent for cash) */}
                        {paymentMethod === 'CASH' && (
                            <div className="space-y-3 animate-in fade-in slide-in-from-top-2">
                                <div className="relative">
                                    <span className="absolute left-4 top-1/2 -translate-y-1/2 font-black text-muted-foreground">EGP</span>
                                    <input
                                        type="number"
                                        placeholder="Amount Tendered"
                                        value={amountPaid}
                                        onChange={handleAmountPaidChange}
                                        className="w-full bg-background border-2 border-primary/20 p-4 pl-14 rounded-2xl text-xl font-black outline-none focus:border-primary focus:ring-4 focus:ring-primary/10 transition-all text-right"
                                    />
                                    {typeof amountPaid === 'number' && amountPaid > total && (
                                        <div className="absolute right-4 -top-3 bg-green-500 text-white text-[10px] font-black px-2 py-0.5 rounded-full shadow-sm">
                                            Change: EGP {(amountPaid - total).toLocaleString()}
                                        </div>
                                    )}
                                </div>

                                {/* Quick Cash Buttons */}
                                <div className="grid grid-cols-4 gap-2">
                                    <button onClick={setExactCash} className="py-2 bg-secondary text-foreground font-bold text-xs rounded-xl hover:bg-secondary/80 transition-colors">Exact</button>
                                    <button onClick={addQuickCash50} className="py-2 bg-secondary text-foreground font-bold text-xs rounded-xl hover:bg-secondary/80 transition-colors">+50</button>
                                    <button onClick={addQuickCash100} className="py-2 bg-secondary text-foreground font-bold text-xs rounded-xl hover:bg-secondary/80 transition-colors">+100</button>
                                    <button onClick={addQuickCash200} className="py-2 bg-secondary text-foreground font-bold text-xs rounded-xl hover:bg-secondary/80 transition-colors">+200</button>
                                </div>
                            </div>
                        )}

                        {/* Checkout CTA */}
                        <button
                            onClick={handleCheckoutClick}
                            disabled={processing || cart.length === 0}
                            className={clsx(
                                "w-full h-16 rounded-2xl font-black text-lg flex items-center justify-center gap-2 transition-all duration-300 shadow-lg relative overflow-hidden group mt-2",
                                cart.length === 0 
                                    ? "bg-secondary text-muted-foreground shadow-none cursor-not-allowed" 
                                    : "bg-primary text-primary-foreground hover:shadow-xl hover:shadow-primary/20 hover:-translate-y-0.5"
                            )}
                        >
                            <div className="absolute inset-0 w-full h-full bg-white/20 scale-x-0 group-hover:scale-x-100 origin-left transition-transform duration-500 ease-out" />
                            {processing ? (
                                <Loader2 className="animate-spin" size={24} />
                            ) : (
                                <>
                                    Complete Sale
                                    <div className="bg-white/20 p-1 rounded-lg ml-2">
                                        <Check size={18} strokeWidth={3} />
                                    </div>
                                </>
                            )}
                        </button>
                    </div>
                </div>
            </div>

            {/* Confirmation Dialog */}
            {showConfirmDialog && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-card w-full max-w-md rounded-[2rem] border border-border shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
                        <div className="p-8 pb-6 flex flex-col items-center text-center gap-4">
                            <div className="w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center text-primary">
                                <ShoppingCart size={32} strokeWidth={2} />
                            </div>
                            <div>
                                <h3 className="text-2xl font-black tracking-tight mb-1">Confirm Sale</h3>
                                <p className="text-muted-foreground font-medium text-sm">Review the transaction details before completing.</p>
                            </div>
                        </div>

                        <div className="px-8 pb-6 space-y-4">
                            <div className="bg-secondary/50 p-5 rounded-2xl space-y-3">
                                <div className="flex justify-between text-sm font-medium">
                                    <span className="text-muted-foreground">Items</span>
                                    <span className="font-bold">{cart.length}</span>
                                </div>
                                <div className="flex justify-between text-sm font-medium">
                                    <span className="text-muted-foreground">Payment Method</span>
                                    <span className="font-bold">{paymentMethod}</span>
                                </div>
                                {buyerInfo.customerName && (
                                    <div className="flex justify-between text-sm font-medium">
                                        <span className="text-muted-foreground">Customer</span>
                                        <span className="font-bold text-right">{buyerInfo.customerName}</span>
                                    </div>
                                )}
                                <div className="h-px bg-border my-2" />
                                <div className="flex justify-between font-black text-xl">
                                    <span>Total Due</span>
                                    <span className="text-primary">EGP {total.toLocaleString()}</span>
                                </div>
                                {paymentMethod === 'CASH' && amountPaid && typeof amountPaid === 'number' && (
                                    <div className="flex justify-between font-bold text-sm text-green-600 pt-1">
                                        <span>Change</span>
                                        <span>EGP {Math.max(0, amountPaid - total).toLocaleString()}</span>
                                    </div>
                                )}
                            </div>
                        </div>

                        <div className="p-6 bg-secondary/20 flex gap-3">
                            <button
                                onClick={handleCloseConfirmDialog}
                                className="flex-1 py-4 bg-background border border-border/60 rounded-xl font-bold hover:bg-secondary transition-colors"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handleConfirmCheckout}
                                className="flex-1 py-4 bg-primary text-primary-foreground rounded-xl font-black shadow-lg shadow-primary/20 hover:bg-primary/90 hover:scale-[1.02] transition-all"
                            >
                                Confirm Sale
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Success Animation Overlay */}
            {showSuccess && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center bg-background/90 backdrop-blur-md animate-in fade-in duration-300">
                    <div className="flex flex-col items-center gap-6 animate-in zoom-in-50 duration-500 ease-out">
                        <div className="w-28 h-28 bg-green-500 rounded-full flex items-center justify-center text-white shadow-2xl shadow-green-500/30 ring-8 ring-green-500/20">
                            <Check size={56} strokeWidth={4} />
                        </div>
                        <div className="text-center space-y-2">
                            <h2 className="text-4xl font-black tracking-tight text-foreground">Sale Complete!</h2>
                            <p className="text-lg text-muted-foreground font-medium">The invoice has been successfully recorded.</p>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect, useRef, Fragment, useCallback } from 'react';
import { UserCheck, Trophy, Phone, Eye, X, FileDown, Calendar, DollarSign } from 'lucide-react';
import { getStaffList, getStaffSalesDetail } from '@/app/actions/staff';
import clsx from 'clsx';

type Period = 'day' | 'week' | 'month' | '2months' | '6months' | 'all';

interface StaffMember {
    id: string;
    name: string | null;
    username: string;
    phone?: string | null;
}

interface Invoice {
    id: string;
    date: Date | string;
    customerName: string | null;
    totalAmount: number | string | { toNumber: () => number };
}

interface StaffSalesDetail {
    totalSales: number;
    totalTransactions: number;
    invoices: Invoice[];
}

const periodLabels: Record<Period, string> = {
    day: 'Today',
    week: 'This Week',
    month: 'This Month',
    '2months': '2 Months',
    '6months': '6 Months',
    all: 'All Time'
};

export default function StaffSalesPage() {
    const [staff, setStaff] = useState<StaffMember[]>([]);
    const [salesData, setSalesData] = useState<Record<string, { total: number, count: number }>>({});
    const [loading, setLoading] = useState(true);

    // Modal state
    const [selectedStaff, setSelectedStaff] = useState<StaffMember | null>(null);
    const [modalPeriod, setModalPeriod] = useState<Period>('month');
    const [modalData, setModalData] = useState<StaffSalesDetail | null>(null);
    const [modalLoading, setModalLoading] = useState(false);

    const printRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        loadData();
    }, []);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const staffList = await getStaffList();
            setStaff(staffList);

            // Get summary sales for each staff
            const summaryData: Record<string, { total: number, count: number }> = {};
            for (const s of staffList) {
                const detail = await getStaffSalesDetail(s.id, 'all');
                summaryData[s.id] = { total: detail.totalSales, count: detail.totalTransactions };
            }
            setSalesData(summaryData);
        } finally {
            setLoading(false);
        }
    }, []);

    const openModal = useCallback(async (staffMember: StaffMember) => {
        setSelectedStaff(staffMember);
        setModalPeriod('month');
        setModalLoading(true);
        const data = await getStaffSalesDetail(staffMember.id, 'month');
        setModalData(data);
        setModalLoading(false);
    }, []);

    const changePeriod = useCallback(async (period: Period) => {
        if (!selectedStaff) return;
        setModalPeriod(period);
        setModalLoading(true);
        const data = await getStaffSalesDetail(selectedStaff.id, period);
        setModalData(data);
        setModalLoading(false);
    }, [selectedStaff]);

    const handleOpenModal = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) {
            const found = staff.find(s => s.id === id);
            if (found) openModal(found);
        }
    }, [staff, openModal]);

    const handleChangePeriod = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const p = e.currentTarget.dataset.period as Period;
        if (p) changePeriod(p);
    }, [changePeriod]);

    const handleCloseModal = useCallback(() => setSelectedStaff(null), []);

    const exportPDF = useCallback(() => {
        if (!printRef.current || !selectedStaff) return;

        // Use window.print() for simple PDF export
        const printContent = printRef.current.innerHTML;
        const printWindow = window.open('', '_blank');
        if (printWindow) {
            printWindow.document.write(`
                <html>
                <head>
                    <title>Staff Report - ${selectedStaff.name || selectedStaff.username}</title>
                    <style>
                        body { font-family: Arial, sans-serif; padding: 20px; }
                        table { width: 100%; border-collapse: collapse; margin-top: 20px; }
                        th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
                        th { background-color: #f5f5f5; }
                        .header { border-bottom: 2px solid #333; padding-bottom: 10px; margin-bottom: 20px; }
                        .stats { display: flex; gap: 40px; margin: 20px 0; }
                        .stat { }
                        .stat-label { color: #666; font-size: 12px; }
                        .stat-value { font-size: 24px; font-weight: bold; }
                    </style>
                </head>
                <body>
                    <div class="header">
                        <h1>Staff Sales Report</h1>
                        <p><strong>${selectedStaff.name || selectedStaff.username}</strong></p>
                        <p>Phone: ${selectedStaff.phone || 'N/A'}</p>
                        <p>Period: ${periodLabels[modalPeriod]}</p>
                        <p>Generated: ${new Date().toLocaleString()}</p>
                    </div>
                    ${printContent}
                </body>
                </html>
            `);
            printWindow.document.close();
            printWindow.print();
        }
    }, [selectedStaff, modalPeriod]);

    // Sort staff by total sales
    const sortedStaff = [...staff].sort((a, b) => {
        const aTotal = salesData[a.id]?.total || 0;
        const bTotal = salesData[b.id]?.total || 0;
        return bTotal - aTotal;
    });

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight text-foreground flex items-center gap-3">
                        <UserCheck className="text-primary" />
                        Staff Sales
                    </h2>
                    <p className="text-muted-foreground">Performance Tracking</p>
                </div>
            </div>

            <div className="rounded-xl border border-border bg-card shadow-sm overflow-hidden">
                <table className="w-full text-sm text-left">
                    <thead className="bg-secondary/30 text-muted-foreground font-semibold border-b border-border">
                        <tr>
                            <th className="px-6 py-4">Rank</th>
                            <th className="px-6 py-4">Staff Member</th>
                            <th className="px-6 py-4">Phone</th>
                            <th className="px-6 py-4 text-right">Transactions</th>
                            <th className="px-6 py-4 text-right">Total Sales (EGP)</th>
                            <th className="px-6 py-4 text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-border">
                        {loading ? (
                            <tr><td colSpan={6} className="px-6 py-12 text-center text-muted-foreground">Loading staff data...</td></tr>
                        ) : sortedStaff.length === 0 ? (
                            <tr><td colSpan={6} className="px-6 py-12 text-center text-muted-foreground">No staff members found.</td></tr>
                        ) : (
                            sortedStaff.map((s, index) => (
                                <tr key={s.id} className="hover:bg-muted/50 transition-colors">
                                    <td className="px-6 py-4">
                                        {index === 0 ? (
                                            <Trophy className="text-yellow-500" size={20} />
                                        ) : index === 1 ? (
                                            <Trophy className="text-gray-400" size={20} />
                                        ) : index === 2 ? (
                                            <Trophy className="text-amber-700" size={20} />
                                        ) : (
                                            <span className="text-muted-foreground font-bold">{index + 1}</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4 font-semibold">{s.name || s.username}</td>
                                    <td className="px-6 py-4 text-muted-foreground">{s.phone || '—'}</td>
                                    <td className="px-6 py-4 text-right">{salesData[s.id]?.count || 0}</td>
                                    <td className="px-6 py-4 text-right font-bold text-green-600">
                                        {(salesData[s.id]?.total || 0).toLocaleString()}
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <button
                                            data-id={s.id}
                                            onClick={handleOpenModal}
                                            className="p-2 hover:bg-secondary rounded-lg text-primary"
                                            title="View Details"
                                        >
                                            <Eye size={16} />
                                        </button>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            {/* Staff Detail Modal */}
            {selectedStaff && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <div className="bg-card w-full max-w-3xl rounded-2xl border border-border shadow-2xl overflow-hidden max-h-[90vh] flex flex-col">
                        <div className="p-6 border-b border-border flex items-center justify-between bg-primary/5">
                            <div>
                                <h3 className="text-xl font-bold">{selectedStaff.name || selectedStaff.username}</h3>
                                {selectedStaff.phone && (
                                    <p className="text-sm text-muted-foreground flex items-center gap-1">
                                        <Phone size={12} /> {selectedStaff.phone}
                                    </p>
                                )}
                            </div>
                            <div className="flex gap-2">
                                <button
                                    onClick={exportPDF}
                                    className="flex items-center gap-2 px-3 py-2 bg-primary/10 text-primary rounded-lg hover:bg-primary/20 text-sm font-medium"
                                >
                                    <FileDown size={16} />
                                    Export PDF
                                </button>
                                <button onClick={handleCloseModal} className="p-2 hover:bg-secondary rounded-full">
                                    <X size={20} />
                                </button>
                            </div>
                        </div>

                        {/* Period Tabs */}
                        <div className="flex gap-2 p-4 border-b border-border overflow-x-auto">
                            {(Object.keys(periodLabels) as Period[]).map(p => (
                                <button
                                    key={p}
                                    data-period={p}
                                    onClick={handleChangePeriod}
                                    className={clsx(
                                        "px-4 py-2 rounded-lg text-sm font-bold whitespace-nowrap transition-all",
                                        modalPeriod === p
                                            ? "bg-primary text-primary-foreground"
                                            : "bg-secondary text-muted-foreground hover:bg-secondary/80"
                                    )}
                                >
                                    {periodLabels[p]}
                                </button>
                            ))}
                        </div>

                        {/* Stats Summary */}
                        <div className="p-6 grid grid-cols-2 gap-4">
                            <div className="bg-secondary/30 rounded-xl p-4">
                                <div className="flex items-center gap-2 text-muted-foreground text-sm mb-1">
                                    <Calendar size={14} />
                                    Transactions
                                </div>
                                <div className="text-2xl font-black">
                                    {modalLoading ? '...' : modalData?.totalTransactions || 0}
                                </div>
                            </div>
                            <div className="bg-green-50 dark:bg-green-950/20 rounded-xl p-4">
                                <div className="flex items-center gap-2 text-green-600 text-sm mb-1">
                                    <DollarSign size={14} />
                                    Total Sales
                                </div>
                                <div className="text-2xl font-black text-green-600">
                                    EGP {modalLoading ? '...' : (modalData?.totalSales || 0).toLocaleString()}
                                </div>
                            </div>
                        </div>

                        {/* Invoices List */}
                        <div ref={printRef} className="flex-1 overflow-y-auto px-6 pb-6">
                            <table className="w-full text-sm">
                                <thead className="sticky top-0 bg-card">
                                    <tr className="border-b border-border">
                                        <th className="py-2 text-left font-semibold">Date</th>
                                        <th className="py-2 text-left font-semibold">Customer</th>
                                        <th className="py-2 text-right font-semibold">Amount</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-border">
                                    {modalLoading ? (
                                        <tr><td colSpan={3} className="py-8 text-center text-muted-foreground">Loading...</td></tr>
                                    ) : !modalData?.invoices?.length ? (
                                        <tr><td colSpan={3} className="py-8 text-center text-muted-foreground">No sales in this period.</td></tr>
                                    ) : (
                                        modalData.invoices.map((inv: any) => (
                                            <Fragment key={inv.id}>
                                                <tr className="hover:bg-muted/30">
                                                    <td className="py-2 font-medium">{new Date(inv.date).toLocaleDateString()}</td>
                                                    <td className="py-2">{inv.customerName || '—'}</td>
                                                    <td className="py-2 text-right font-bold text-green-600">
                                                        +{Number(inv.totalAmount).toLocaleString()}
                                                    </td>
                                                </tr>
                                                {/* Detailed Items Row */}
                                                <tr className="bg-secondary/10">
                                                    <td colSpan={3} className="pl-4 pr-2 pb-4 pt-1">
                                                        <div className="text-xs text-muted-foreground ml-2 border-l-2 border-primary/20 pl-3">
                                                            {inv.items?.map((item: any) => (
                                                                <div key={item.id} className="flex justify-between py-1 border-b border-border/50 last:border-0">
                                                                    <span>
                                                                        <span className="font-semibold text-foreground">{item.product?.name || 'Unknown'}</span>
                                                                        <span className="text-muted-foreground mx-1">x</span>
                                                                        {item.quantity}
                                                                        {item.product?.unit && <span className="text-[10px] ml-1 opacity-70">({item.product.unit})</span>}
                                                                    </span>
                                                                    <span>{Number(item.subtotal).toLocaleString()}</span>
                                                                </div>
                                                            ))}
                                                        </div>
                                                    </td>
                                                </tr>
                                            </Fragment>
                                        ))
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { ClipboardCheck, Search, RefreshCcw, Save, Filter } from 'lucide-react';
import { getStocktakeItems, reconcileStock, StockAdjustment } from '@/app/actions/stocktake';
import clsx from 'clsx';

interface Product {
    id: string;
    name: string;
    stock: number;
    category: string;
    price: number;
    locations: { id: string; name: string; quantity: number }[];
}

export default function StocktakePage() {
    const [products, setProducts] = useState<Product[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState('');
    const [categoryFilter, setCategoryFilter] = useState<string>('all');

    // Map of productId -> actualStock
    const [counts, setCounts] = useState<Record<string, number>>({});
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        loadData();
    }, []);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const data = await getStocktakeItems();
            setProducts(data);
            // Initialize counts with current stock
            const initialCounts: Record<string, number> = {};
            data.forEach(p => initialCounts[p.id] = p.stock);
            setCounts(initialCounts);
        } finally {
            setLoading(false);
        }
    }, []);

    const handleCountChange = useCallback((id: string, value: string) => {
        const num = parseInt(value);
        if (!isNaN(num)) {
            setCounts(prev => ({ ...prev, [id]: num }));
        }
    }, []);

    const handleCountChangeCb = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
        const id = e.target.dataset.id;
        if (id) {
            handleCountChange(id, e.target.value);
        }
    }, [handleCountChange]);

    const handleFocusSelect = useCallback((e: React.FocusEvent<HTMLInputElement>) => e.target.select(), []);

    const getAdjustments = (): StockAdjustment[] => {
        const adjustments: StockAdjustment[] = [];
        products.forEach(p => {
            const actual = counts[p.id];
            if (actual !== undefined && actual !== p.stock) {
                adjustments.push({
                    productId: p.id,
                    currentStock: p.stock,
                    actualStock: actual
                    // simplistic: we let backend distribute diff to default location if multiple exist
                    // In a complex app, we'd iterate over p.locations
                });
            }
        });
        return adjustments;
    };

    const adjustments = getAdjustments();
    const hasAdjustments = adjustments.length > 0;

    const handleSave = useCallback(async () => {
        if (!hasAdjustments) return;

        const confirmed = window.confirm(
            `You are about to reconcile ${adjustments.length} items. This will update inventory levels. Continue?`
        );

        if (!confirmed) return;

        setSaving(true);
        try {
            await reconcileStock(adjustments);
            alert('Stock reconciled successfully!');
            await loadData();
        } catch (error) {
            alert('Failed to reconcile stock');
            console.error(error);
        } finally {
            setSaving(false);
        }
    }, [hasAdjustments, adjustments, loadData]);

    const handleSearchChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setSearch(e.target.value), []);
    const handleCategoryFilterChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => setCategoryFilter(e.target.value), []);

    const categories = Array.from(new Set(products.map(p => p.category))).filter(Boolean);

    const filteredProducts = products.filter(p => {
        const matchesSearch = p.name.toLowerCase().includes(search.toLowerCase());
        const matchesCategory = categoryFilter === 'all' || p.category === categoryFilter;
        return matchesSearch && matchesCategory;
    });

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight text-foreground flex items-center gap-3">
                        <ClipboardCheck className="text-primary" />
                        Stock Count
                    </h2>
                    <p className="text-muted-foreground">Reconcile physical inventory</p>
                </div>
                <div className="flex items-center gap-2">
                    <button
                        onClick={loadData}
                        className="p-2 text-muted-foreground hover:bg-secondary rounded-lg"
                        title="Refresh"
                    >
                        <RefreshCcw size={20} className={clsx(loading && "animate-spin")} />
                    </button>
                    {hasAdjustments && (
                        <button
                            onClick={handleSave}
                            disabled={saving}
                            className="flex items-center gap-2 px-6 py-2 bg-primary text-primary-foreground rounded-lg hover:bg-primary/90 transition-all font-bold shadow-lg shadow-primary/20 animate-in fade-in zoom-in"
                        >
                            {saving ? (
                                <>
                                    <RefreshCcw size={18} className="animate-spin" />
                                    Saving...
                                </>
                            ) : (
                                <>
                                    <Save size={18} />
                                    Submit {adjustments.length} Adjustment{adjustments.length !== 1 ? 's' : ''}
                                </>
                            )}
                        </button>
                    )}
                </div>
            </div>

            {/* Filters */}
            <div className="flex flex-col sm:flex-row gap-4 bg-card p-4 rounded-xl border border-border shadow-sm">
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" size={18} />
                    <input
                        type="text"
                        placeholder="Search products..."
                        value={search}
                        onChange={handleSearchChange}
                        className="w-full pl-10 pr-4 py-2 bg-background border border-input rounded-lg focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none transition-all"
                    />
                </div>
                <div className="flex items-center gap-2 overflow-x-auto pb-2 sm:pb-0">
                    <Filter size={18} className="text-muted-foreground" />
                    <select
                        value={categoryFilter}
                        onChange={handleCategoryFilterChange}
                        className="px-4 py-2 bg-background border border-input rounded-lg focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none"
                    >
                        <option value="all">All Categories</option>
                        {categories.map(c => (
                            <option key={c} value={c}>{c}</option>
                        ))}
                    </select>
                </div>
            </div>

            {/* Table */}
            <div className="rounded-xl border border-border bg-card shadow-sm overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-secondary/30 text-muted-foreground font-semibold border-b border-border">
                            <tr>
                                <th className="px-6 py-4">Product</th>
                                <th className="px-6 py-4">Category</th>
                                <th className="px-6 py-4 text-center">System Stock</th>
                                <th className="px-6 py-4 text-center w-32">Actual Count</th>
                                <th className="px-6 py-4 text-center">Diff</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {loading ? (
                                <tr><td colSpan={5} className="px-6 py-12 text-center text-muted-foreground">Loading inventory...</td></tr>
                            ) : filteredProducts.length === 0 ? (
                                <tr><td colSpan={5} className="px-6 py-12 text-center text-muted-foreground">No products found.</td></tr>
                            ) : (
                                filteredProducts.map(product => {
                                    const actual = counts[product.id] ?? product.stock;
                                    const diff = actual - product.stock;
                                    const hasDiff = diff !== 0;

                                    return (
                                        <tr key={product.id} className={clsx(
                                            "transition-colors",
                                            hasDiff ? "bg-yellow-500/5 hover:bg-yellow-500/10" : "hover:bg-muted/50"
                                        )}>
                                            <td className="px-6 py-4 font-semibold text-foreground">
                                                {product.name}
                                                {hasDiff && (
                                                    <span className="ml-2 inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-500">
                                                        Modified
                                                    </span>
                                                )}
                                                {product.locations.length > 1 && (
                                                    <div className="text-xs text-muted-foreground mt-1">
                                                        {product.locations.map(l => `${l.name}: ${l.quantity}`).join(', ')}
                                                    </div>
                                                )}
                                            </td>
                                            <td className="px-6 py-4 text-muted-foreground">
                                                <span className="px-2 py-1 bg-secondary rounded-md text-xs">
                                                    {product.category || 'Uncategorized'}
                                                </span>
                                            </td>
                                            <td className="px-6 py-4 text-center font-medium">
                                                {product.stock}
                                            </td>
                                            <td className="px-6 py-4 text-center">
                                                <div className="flex items-center justify-center">
                                                    <input
                                                        type="number"
                                                        value={actual}
                                                        data-id={product.id}
                                                        onChange={handleCountChangeCb}
                                                        className={clsx(
                                                            "w-20 px-2 py-1 text-center font-bold rounded border outline-none focus:ring-2 transition-all",
                                                            hasDiff
                                                                ? "border-yellow-500 text-yellow-600 bg-background focus:ring-yellow-500/20"
                                                                : "border-input bg-muted/30 focus:bg-background focus:ring-primary/20 focus:border-primary"
                                                        )}
                                                        onFocus={handleFocusSelect}
                                                    />
                                                </div>
                                            </td>
                                            <td className="px-6 py-4 text-center">
                                                {diff === 0 ? (
                                                    <span className="text-muted-foreground/30">—</span>
                                                ) : (
                                                    <span className={clsx(
                                                        "font-bold",
                                                        diff > 0 ? "text-green-600" : "text-red-500"
                                                    )}>
                                                        {diff > 0 ? '+' : ''}{diff}
                                                    </span>
                                                )}
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { getUsers, deleteUser, createUser, updateUser } from '@/app/actions/users';
import { getDefaultPermissions, ALL_PERMISSIONS } from '@/lib/permissions';
import { UserPlus, Trash2, Shield, Eye, Phone, MapPin, Settings } from 'lucide-react';
import Link from 'next/link';

interface User {
    id: string;
    username: string;
    name: string | null;
    role: string;
    phone: string | null;
    address: string | null;
    permissions: string[];
    createdAt: Date;
}

const ROLE_COLORS: Record<string, string> = {
    ROOT: 'bg-purple-100 text-purple-700 border-purple-200',
    ADMIN: 'bg-blue-100 text-blue-700 border-blue-200',
    ACCOUNTANT: 'bg-green-100 text-green-700 border-green-200',
    SALESPERSON: 'bg-orange-100 text-orange-700 border-orange-200',
    READ_ONLY: 'bg-gray-100 text-gray-700 border-gray-200',
};

export default function UsersPage() {
    const [users, setUsers] = useState<User[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingUser, setEditingUser] = useState<User | null>(null);
    const [selectedRole, setSelectedRole] = useState('SALESPERSON');
    const [selectedPermissions, setSelectedPermissions] = useState<string[]>([]);
    const [useCustomPermissions, setUseCustomPermissions] = useState(false);
    const [error, setError] = useState('');

    const fetchUsers = useCallback(async (showLoading = false) => {
        if (showLoading) setIsLoading(true);
        const data = await getUsers();
        setUsers(data as User[]);
        setIsLoading(false);
    }, []);

    useEffect(() => {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        void fetchUsers(false);
    }, [fetchUsers]);

    // permissions derived directly when needed

    const handleDelete = async (id: string) => {
        if (confirm('Are you sure you want to delete this user?')) {
            const res = await deleteUser(id);
            if (res.success) {
                fetchUsers(true);
            } else {
                alert(res.error);
            }
        }
    };

    const handleDeleteClick = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) handleDelete(id);
    }, [fetchUsers]);

    const openCreateModal = () => {
        setEditingUser(null);
        setSelectedRole('SALESPERSON');
        setSelectedPermissions(getDefaultPermissions('SALESPERSON'));
        setUseCustomPermissions(false);
        setError('');
        setIsModalOpen(true);
    };

    const openEditModal = (user: User) => {
        setEditingUser(user);
        setSelectedRole(user.role);
        setSelectedPermissions(user.permissions.length > 0 ? user.permissions : getDefaultPermissions(user.role));
        setUseCustomPermissions(user.permissions.length > 0);
        setError('');
        setIsModalOpen(true);
    };

    const handleEditClick = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) {
            const found = users.find(u => u.id === id);
            if (found) openEditModal(found);
        }
    }, [users]);

    const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setError('');
        const formData = new FormData(e.currentTarget);

        // Add permissions to form data
        formData.set('permissions', JSON.stringify(useCustomPermissions ? selectedPermissions : []));

        if (editingUser) {
            const res = await updateUser(editingUser.id, formData);
            if (res.success) {
                setIsModalOpen(false);
                fetchUsers();
            } else {
                setError(res.error || 'Failed to update user');
            }
        } else {
            const res = await createUser(formData);
            if (res.success) {
                setIsModalOpen(false);
                fetchUsers();
            } else {
                setError(res.error || 'Failed to create user');
            }
        }
    };

    const togglePermission = (key: string) => {
        setSelectedPermissions(prev =>
            prev.includes(key)
                ? prev.filter(p => p !== key)
                : [...prev, key]
        );
    };

    const handleRoleChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => setSelectedRole(e.target.value), []);
    const handleCustomPermissionsChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setUseCustomPermissions(e.target.checked), []);
    const handleTogglePermissionClick = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
        const key = e.target.dataset.key;
        if (key) togglePermission(key);
    }, []);
    const handleCloseModalClick = useCallback(() => setIsModalOpen(false), []);

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-2xl font-bold">Team Management</h1>
                    <p className="text-muted-foreground">Manage employees, salespersons, and accountants.</p>
                </div>
                <button
                    onClick={openCreateModal}
                    className="flex items-center gap-2 bg-primary text-primary-foreground px-4 py-2 rounded-lg hover:opacity-90 transition-opacity"
                >
                    <UserPlus size={20} />
                    Add Member
                </button>
            </div>

            {/* Role Legend */}
            <div className="flex flex-wrap gap-2">
                {Object.entries(ROLE_COLORS).map(([role, color]) => (
                    <span key={role} className={`text-xs px-2 py-1 rounded-full border ${color}`}>
                        {role}
                    </span>
                ))}
            </div>

            <div className="bg-card rounded-xl border border-border overflow-hidden">
                <table className="w-full text-left border-collapse">
                    <thead className="bg-secondary/50">
                        <tr>
                            <th className="px-6 py-4 font-semibold text-sm">Employee</th>
                            <th className="px-6 py-4 font-semibold text-sm">Contact</th>
                            <th className="px-6 py-4 font-semibold text-sm">Role</th>
                            <th className="px-6 py-4 font-semibold text-sm">Joined</th>
                            <th className="px-6 py-4 font-semibold text-sm text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-border">
                        {isLoading ? (
                            <tr>
                                <td colSpan={5} className="px-6 py-8 text-center text-muted-foreground">Loading...</td>
                            </tr>
                        ) : users.map((user) => (
                            <tr key={user.id} className="hover:bg-secondary/20 transition-colors">
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-3">
                                        <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white font-bold ${user.role === 'ROOT' ? 'bg-purple-500' :
                                            user.role === 'ADMIN' ? 'bg-blue-500' :
                                                user.role === 'ACCOUNTANT' ? 'bg-green-500' :
                                                    user.role === 'SALESPERSON' ? 'bg-orange-500' :
                                                        'bg-gray-500'
                                            }`}>
                                            {(user.name || user.username)[0].toUpperCase()}
                                        </div>
                                        <div>
                                            <div className="font-medium">{user.name || 'Anonymous'}</div>
                                            <div className="text-xs text-muted-foreground">@{user.username}</div>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="space-y-1">
                                        {user.phone && (
                                            <div className="flex items-center gap-1 text-xs text-muted-foreground">
                                                <Phone size={12} /> {user.phone}
                                            </div>
                                        )}
                                        {user.address && (
                                            <div className="flex items-center gap-1 text-xs text-muted-foreground">
                                                <MapPin size={12} /> {user.address}
                                            </div>
                                        )}
                                        {!user.phone && !user.address && (
                                            <span className="text-xs text-muted-foreground">-</span>
                                        )}
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <span className={`inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-medium border ${ROLE_COLORS[user.role] || ROLE_COLORS.READ_ONLY}`}>
                                        <Shield size={12} />
                                        {user.role}
                                    </span>
                                </td>
                                <td className="px-6 py-4 text-sm text-muted-foreground">
                                    {new Date(user.createdAt).toLocaleDateString()}
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <div className="flex items-center justify-end gap-2">
                                        <Link prefetch={false}
                                            href={`/logs?user=${user.id}`}
                                            className="p-2 text-muted-foreground hover:text-blue-500 transition-colors"
                                            title="View Activity"
                                        >
                                            <Eye size={18} />
                                        </Link>
                                        {user.role !== 'ROOT' && (
                                            <>
                                                <button
                                                    data-id={user.id}
                                                    onClick={handleEditClick}
                                                    className="p-2 text-muted-foreground hover:text-primary transition-colors"
                                                    title="Edit"
                                                >
                                                    <Settings size={18} />
                                                </button>
                                                <button
                                                    data-id={user.id}
                                                    onClick={handleDeleteClick}
                                                    className="p-2 text-muted-foreground hover:text-red-500 transition-colors"
                                                    title="Delete"
                                                >
                                                    <Trash2 size={18} />
                                                </button>
                                            </>
                                        )}
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Create/Edit User Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
                    <div className="bg-card w-full max-w-lg max-h-[90vh] overflow-y-auto p-6 rounded-2xl shadow-xl border border-border">
                        <h2 className="text-xl font-bold mb-4">
                            {editingUser ? 'Edit Team Member' : 'Add Team Member'}
                        </h2>
                        {error && (
                            <div className="bg-red-50 text-red-600 p-3 rounded-lg mb-4 text-sm">
                                {error}
                            </div>
                        )}
                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Full Name</label>
                                    <input
                                        name="name"
                                        type="text"
                                        defaultValue={editingUser?.name || ''}
                                        className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20"
                                        required
                                        placeholder="John Doe"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Username</label>
                                    <input
                                        name="username"
                                        type="text"
                                        defaultValue={editingUser?.username || ''}
                                        className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20"
                                        required
                                        placeholder="johndoe"
                                        disabled={!!editingUser}
                                    />
                                </div>
                            </div>

                            {!editingUser && (
                                <>
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium">Email Address</label>
                                        <input name="email" type="email" className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20" required placeholder="john@coffee.com" />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium">Password</label>
                                        <input name="password" type="password" className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20" required placeholder="••••••••" minLength={6} />
                                    </div>
                                </>
                            )}

                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Phone</label>
                                    <input
                                        name="phone"
                                        type="tel"
                                        defaultValue={editingUser?.phone || ''}
                                        className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20"
                                        placeholder="01xxxxxxxxx"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Address</label>
                                    <input
                                        name="address"
                                        type="text"
                                        defaultValue={editingUser?.address || ''}
                                        className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20"
                                        placeholder="Cairo, Egypt"
                                    />
                                </div>
                            </div>

                            <div className="space-y-2">
                                <label className="text-sm font-medium">Role</label>
                                <select
                                    name="role"
                                    value={selectedRole}
                                    onChange={handleRoleChange}
                                    className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20"
                                >
                                    <option value="SALESPERSON">Salesperson (Carrier)</option>
                                    <option value="ACCOUNTANT">Accountant</option>
                                    <option value="ADMIN">Admin</option>
                                    <option value="READ_ONLY">Read Only</option>
                                </select>
                                <p className="text-[10px] text-muted-foreground italic">ROOT role can only be assigned via database.</p>
                            </div>

                            {/* Permissions Section */}
                            <div className="space-y-3 p-4 bg-secondary/30 rounded-xl border border-border">
                                <div className="flex items-center justify-between">
                                    <label className="text-sm font-bold">Page Permissions</label>
                                    <label className="flex items-center gap-2 text-xs">
                                        <input
                                            type="checkbox"
                                            checked={useCustomPermissions}
                                            onChange={handleCustomPermissionsChange}
                                            className="rounded"
                                        />
                                        Custom permissions
                                    </label>
                                </div>
                                <div className="grid grid-cols-2 gap-2">
                                    {ALL_PERMISSIONS.map(perm => (
                                        <label
                                            key={perm.key}
                                            className={`flex items-center gap-2 text-sm p-2 rounded-lg cursor-pointer transition-colors ${selectedPermissions.includes(perm.key)
                                                ? 'bg-primary/10 text-primary'
                                                : 'bg-secondary/50 text-muted-foreground'
                                                } ${!useCustomPermissions ? 'opacity-60' : ''}`}
                                        >
                                            <input
                                                type="checkbox"
                                                checked={selectedPermissions.includes(perm.key)}
                                                data-key={perm.key}
                                                onChange={handleTogglePermissionClick}
                                                disabled={!useCustomPermissions}
                                                className="rounded"
                                            />
                                            {perm.label}
                                        </label>
                                    ))}
                                </div>
                                {!useCustomPermissions && (
                                    <p className="text-[10px] text-muted-foreground">Using default permissions for {selectedRole} role.</p>
                                )}
                            </div>

                            <div className="flex gap-3 pt-4">
                                <button type="button" onClick={handleCloseModalClick} className="flex-1 px-4 py-2.5 rounded-lg border border-border hover:bg-secondary transition-colors">Cancel</button>
                                <button type="submit" className="flex-1 bg-primary text-primary-foreground px-4 py-2.5 rounded-lg hover:opacity-90 transition-opacity">
                                    {editingUser ? 'Update' : 'Create'} User
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

'use server';

import getPrisma from '@/lib/prisma';
import { revalidatePath } from 'next/cache';

export async function searchCustomers(query: string) {
    if (!query || query.length < 2) return [];

    const prisma = getPrisma();

    // Search in Customers (New Model)
    const customers = await prisma.customer.findMany({
        where: {
            OR: [
                { name: { contains: query, mode: 'insensitive' } },
                { phone: { contains: query, mode: 'insensitive' } }
            ]
        },
        include: {
            group: true
        },
        take: 10
    });

    return customers.map(c => ({
        id: c.id,
        name: c.name,
        phone: c.phone || 'N/A',
        address: c.address || 'N/A',
        balance: Number(c.balance),
        group: c.group?.name || 'No Group',
        type: 'CUSTOMER'
    }));
}

export async function getCustomersList() {
    const prisma = getPrisma();

    return prisma.customer.findMany({
        include: {
            group: true,
            parent: true
        },
        orderBy: { name: 'asc' }
    });
}

export async function getCustomerProfile(id: string) {
    const prisma = getPrisma();

    const customer = await prisma.customer.findUnique({
        where: { id },
        include: {
            group: true,
            parent: true,
            invoices: {
                include: {
                    items: {
                        include: { product: true }
                    },
                    user: { select: { name: true } }
                },
                orderBy: { date: 'desc' }
            }
        }
    });

    if (!customer) throw new Error("Customer not found");

    return {
        profile: {
            id: customer.id,
            name: customer.name,
            phone: customer.phone || 'N/A',
            address: customer.address || 'N/A',
            balance: Number(customer.balance),
            type: customer.groupId ? 'GROUP_MEMBER' : 'INDIVIDUAL',
            groupName: customer.group?.name,
            parentName: customer.parent?.name,
            joinedAt: customer.createdAt
        },
        invoices: customer.invoices.map(inv => ({
            id: inv.id,
            date: inv.date,
            total: Number(inv.totalAmount),
            paid: Number(inv.amountPaid),
            currentBalance: Number(inv.currentBalance),
            method: inv.paymentMethod,
            seller: inv.user?.name || 'Unknown',
            items: inv.items.map(it => ({
                product: it.product.name,
                quantity: it.quantity,
                price: Number(it.unitPrice),
                subtotal: Number(it.subtotal)
            }))
        }))
    };
}

export async function createCustomer(data: {
    name: string;
    phone?: string;
    address?: string;
    groupId?: string;
}) {
    if (!data.name || data.name.trim().length < 2) {
        return { success: false, error: 'Customer name must be at least 2 characters.' };
    }

    const prisma = getPrisma();

    try {
        const customer = await prisma.customer.create({
            data: {
                name: data.name.trim(),
                phone: data.phone?.trim() || null,
                address: data.address?.trim() || null,
                groupId: data.groupId || null,
                balance: 0,
            }
        });

        revalidatePath('/customers');
        return { success: true, customer };
    } catch (err: any) {
        // Handle unique constraint violation (name + phone combo)
        if (err?.code === 'P2002') {
            return { success: false, error: 'A customer with this name and phone already exists.' };
        }
        console.error('Failed to create customer:', err);
        return { success: false, error: 'Failed to create customer. Please try again.' };
    }
}

'use server';

import getPrisma from '@/lib/prisma';
import { revalidatePath } from 'next/cache';

export async function getInventory() {
    const prisma = getPrisma();

    const inventory = await prisma.inventory.findMany({
        include: {
            product: {
                include: {
                    category: true
                }
            },
            location: true
        },
        orderBy: {
            product: { name: 'asc' }
        }
    });

    return inventory.map(item => ({
        ...item,
        product: {
            ...item.product,
            costPrice: Number(item.product.costPrice),
            baseSellingPrice: Number(item.product.baseSellingPrice)
        }
    }));
}

export async function getCategories() {
    const prisma = getPrisma();
    return prisma.category.findMany({
        orderBy: { name: 'asc' },
        include: {
            _count: { select: { products: true } }
        }
    });
}

export async function createCategory(name: string) {
    const prisma = getPrisma();
    try {
        const category = await prisma.category.create({
            data: { name }
        });

        try {
            const { logActivity } = await import('./audit');
            await logActivity('CREATE_CATEGORY', `Created category "${name}"`);
        } catch (e) {
            console.error('Audit log failed', e);
        }

        revalidatePath('/products');
        return { success: true, category };
    } catch (error: unknown) {
        if (typeof error === 'object' && error !== null && 'code' in error && (error as any).code === 'P2002') {
            return { success: false, error: 'Category name already exists.' };
        }
        return { success: false, error: 'Failed to create category.' };
    }
}

export async function deleteCategory(id: string) {
    const prisma = getPrisma();
    try {
        // Check if category has products
        const count = await prisma.product.count({ where: { categoryId: id } });
        if (count > 0) {
            return { success: false, error: `Cannot delete: ${count} products use this category.` };
        }
        await prisma.category.delete({ where: { id } });

        try {
            const { logActivity } = await import('./audit');
            await logActivity('DELETE_CATEGORY', `Deleted category ID: ${id}`);
        } catch (e) {
            console.error('Audit log failed', e);
        }

        revalidatePath('/products');
        return { success: true };
    } catch {
        return { success: false, error: 'Failed to delete category.' };
    }
}

export async function createProduct(data: {
    name: string;
    sku: string;
    categoryId: string;
    costPrice: number;
    baseSellingPrice: number;
    retailPrice?: number;
    lowestRetailPrice?: number;
    wholesalePrice?: number;
    lowestWholesalePrice?: number;
    unit?: string;
    image?: string;
    initialQuantity?: number;
}) {
    const prisma = getPrisma();

    try {
        // Check for duplicate SKU
        const existingSku = await prisma.product.findFirst({
            where: { sku: data.sku }
        });
        if (existingSku) {
            return { success: false, error: `SKU "${data.sku}" already exists. Please use a unique SKU.` };
        }

        const product = await prisma.$transaction(async (tx) => {
            // 1. Create Product
            const newProduct = await tx.product.create({
                data: {
                    name: data.name,
                    sku: data.sku,
                    categoryId: data.categoryId,
                    costPrice: data.costPrice,
                    baseSellingPrice: data.baseSellingPrice,
                    retailPrice: data.retailPrice || 0,
                    lowestRetailPrice: data.lowestRetailPrice || 0,
                    wholesalePrice: data.wholesalePrice || 0,
                    lowestWholesalePrice: data.lowestWholesalePrice || 0,
                    unit: data.unit || 'piece',
                    image: data.image
                }
            });

            // 2. Self-healing Location (Ensure at least one location exists)
            let location = await tx.location.findFirst();
            if (!location) {
                location = await tx.location.create({
                    data: { name: "Main Warehouse", type: "WAREHOUSE" }
                });
            }

            // 3. Create Initial Inventory if provided
            if (data.initialQuantity !== undefined && data.initialQuantity > 0) {
                await tx.inventory.create({
                    data: {
                        productId: newProduct.id,
                        locationId: location.id,
                        quantity: data.initialQuantity
                    }
                });

                // [NEW] Create Transaction for Opening Stock
                await tx.transaction.create({
                    data: {
                        type: 'IN',
                        toLocationId: location.id,
                        items: {
                            create: [{
                                productId: newProduct.id,
                                quantity: data.initialQuantity
                            }]
                        }
                    }
                });
            }

            return newProduct;
        });

        // 4. Audit Log
        try {
            const { logActivity } = await import('./audit');
            await logActivity('CREATE_PRODUCT', `Created product "${data.name}" (${data.sku})`);
        } catch (e) {
            console.error('Audit log failed', e);
        }

        revalidatePath('/inventory');
        revalidatePath('/sales');
        revalidatePath('/dashboard');

        return {
            success: true,
            product: {
                ...product,
                costPrice: Number(product.costPrice),
                baseSellingPrice: Number(product.baseSellingPrice)
            }
        };
    } catch (error: unknown) {
        if (typeof error === 'object' && error !== null && 'code' in error && (error as any).code === 'P2002' && (error as any).meta?.target?.includes('sku')) {
            return {
                success: false,
                error: 'SKU already exists. Please use a unique code.'
            };
        }
        return {
            success: false,
            error: 'Failed to create product. Please try again.'
        };
    }
}

export async function getUnifiedProducts() {
    const prisma = getPrisma();

    const products = await prisma.product.findMany({
        include: {
            category: true,
            inventoryItems: {
                include: { location: true }
            }
        },
        orderBy: { name: 'asc' }
    });

    // Compute grand total stock across all products
    const grandTotal = products.reduce((sum, p) =>
        sum + p.inventoryItems.reduce((s, inv) => s + inv.quantity, 0), 0
    );

    return products.map(p => {
        const totalStock = p.inventoryItems.reduce((s, inv) => s + inv.quantity, 0);
        const percentOfTotal = grandTotal > 0 ? Number(((totalStock / grandTotal) * 100).toFixed(1)) : 0;

        return {
            id: p.id,
            name: p.name,
            sku: p.sku,
            unit: p.unit,
            categoryId: p.categoryId,
            categoryName: p.category?.name || 'Uncategorized',
            costPrice: Number(p.costPrice),
            baseSellingPrice: Number(p.baseSellingPrice),
            retailPrice: Number(p.retailPrice),
            lowestRetailPrice: Number(p.lowestRetailPrice),
            wholesalePrice: Number(p.wholesalePrice),
            lowestWholesalePrice: Number(p.lowestWholesalePrice),
            image: p.image,
            totalStock,
            percentOfTotal,
            locationBreakdown: p.inventoryItems.map(inv => ({
                locationId: inv.locationId,
                locationName: inv.location.name,
                locationType: inv.location.type,
                quantity: inv.quantity
            }))
        };
    });
}

export async function updateProduct(id: string, data: {
    name: string;
    sku: string;
    categoryId: string;
    costPrice: number;
    baseSellingPrice: number;
    retailPrice?: number;
    lowestRetailPrice?: number;
    wholesalePrice?: number;
    lowestWholesalePrice?: number;
    unit?: string;
    image?: string;
}) {
    const prisma = getPrisma();

    try {
        const product = await prisma.product.update({
            where: { id },
            data: {
                name: data.name,
                sku: data.sku,
                categoryId: data.categoryId,
                costPrice: data.costPrice,
                baseSellingPrice: data.baseSellingPrice,
                retailPrice: data.retailPrice || 0,
                lowestRetailPrice: data.lowestRetailPrice || 0,
                wholesalePrice: data.wholesalePrice || 0,
                lowestWholesalePrice: data.lowestWholesalePrice || 0,
                unit: data.unit || 'piece',
                image: data.image
            }
        });

        // Audit Log
        try {
            const { logActivity } = await import('./audit');
            await logActivity('UPDATE_PRODUCT', `Updated product "${data.name}" (${data.sku})`);
        } catch (e) {
            console.error('Audit log failed', e);
        }

        revalidatePath('/inventory');
        revalidatePath('/sales');
        revalidatePath('/dashboard');

        return {
            success: true,
            product: {
                ...product,
                costPrice: Number(product.costPrice),
                baseSellingPrice: Number(product.baseSellingPrice)
            }
        };
    } catch (error: unknown) {
        if (typeof error === 'object' && error !== null && 'code' in error && (error as any).code === 'P2002' && (error as any).meta?.target?.includes('sku')) {
            return {
                success: false,
                error: 'SKU already exists. Please use a unique code.'
            };
        }
        return {
            success: false,
            error: 'Failed to update product. Please try again.'
        };
    }
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { Filter, Upload, Printer, Edit2, Search } from "lucide-react";
import BulkImportDropzone from "@/components/BulkImportDropzone";
import PrePrintEditModal from "@/components/PrePrintEditModal";

interface Customer {
  id: string;
  name: string;
  address?: string | null;
  governorate?: string | null;
  phone?: string | null;
  balance: number;
}

export default function DebtsReportPage() {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [governorates, setGovernorates] = useState<string[]>([]);
  const [selectedGov, setSelectedGov] = useState<string>("");
  const [searchName, setSearchName] = useState<string>("");
  const [isLoading, setIsLoading] = useState(true);

  // Modals state
  const [showBulkImport, setShowBulkImport] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);

  const fetchDebts = useCallback(async (showLoading = false) => {
    if (showLoading) setIsLoading(true);
    try {
      const url = new URL("/api/reports/debts", window.location.origin);
      if (selectedGov) url.searchParams.append("governorate", selectedGov);

      const res = await fetch(url.toString());
      const data = await res.json();
      setCustomers(data.customers);
      if (data.governorates) setGovernorates(data.governorates);
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  }, [selectedGov]);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchDebts(false);
  }, [fetchDebts]);

  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(searchName.toLowerCase())
  );

  const handlePrintTable = () => {
    window.print();
  };

  const handlePrintSingle = useCallback(() => {
    // In a real app, this might navigate to an invoice print view
    // Here we just print the current window which we could style with print CSS
    window.print();
  }, []);

  const handleShowBulkImport = useCallback(() => setShowBulkImport(true), []);
  const handleCloseBulkImport = useCallback(() => setShowBulkImport(false), []);
  const handleBulkImportSuccess = useCallback(() => {
    setShowBulkImport(false);
    void fetchDebts(true);
  }, [fetchDebts]);

  const handleSearchNameChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setSearchName(e.target.value), []);
  const handleGovChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => setSelectedGov(e.target.value), []);

  const handleEditCustomerClick = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
    const id = e.currentTarget.dataset.id;
    if (id) {
        const cust = customers.find(c => c.id === id);
        if (cust) setEditingCustomer(cust);
    }
  }, [customers]);

  const handleCloseEditModal = useCallback(() => setEditingCustomer(null), []);
  const handlePrintEditModal = useCallback(() => handlePrintSingle(), [handlePrintSingle]);

  return (
    <div className="min-h-screen bg-gray-50/50 p-6 md:p-10 font-sans">

      {/* Header section */}
      <div className="max-w-7xl mx-auto mb-8 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 print:hidden">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 tracking-tight">تقرير المديونيات</h1>
          <p className="text-gray-500 mt-1">عرض مديونيات العملاء حسب المحافظة</p>
        </div>

        <div className="flex gap-3">
          <button 
            onClick={handleShowBulkImport}
            className="flex items-center gap-2 bg-white border border-gray-200 text-gray-700 px-4 py-2 rounded-xl hover:bg-gray-50 transition-all shadow-sm"
          >
            <Upload className="w-4 h-4" />
            <span>إضافة بالجملة</span>
          </button>

          <button 
            onClick={handlePrintTable}
            className="flex items-center gap-2 bg-blue-600 text-white px-5 py-2 rounded-xl hover:bg-blue-700 transition-all shadow-[0_4px_12px_rgba(37,99,235,0.2)] hover:shadow-[0_8px_16px_rgba(37,99,235,0.3)] hover:-translate-y-0.5"
          >
            <Printer className="w-4 h-4" />
            <span>طباعة الجدول</span>
          </button>
        </div>
      </div>

      {/* Filters */}
      <div className="max-w-7xl mx-auto mb-8 grid grid-cols-1 md:grid-cols-3 gap-4 print:hidden">
        <div className="bg-white/70 backdrop-blur-md border border-white/40 p-1 rounded-2xl shadow-sm flex items-center">
          <div className="pl-3 text-gray-400"><Search className="w-5 h-5" /></div>
          <input 
            type="text" 
            placeholder="بحث باسم العميل..." 
            value={searchName}
            onChange={handleSearchNameChange}
            className="w-full bg-transparent border-none focus:ring-0 px-3 py-2 text-gray-700"
          />
        </div>

        <div className="bg-white/70 backdrop-blur-md border border-white/40 p-1 rounded-2xl shadow-sm flex items-center">
          <div className="pl-3 text-gray-400"><Filter className="w-5 h-5" /></div>
          <select 
            value={selectedGov}
            onChange={handleGovChange}
            className="w-full bg-transparent border-none focus:ring-0 px-3 py-2 text-gray-700"
          >
            <option value="">كل المحافظات</option>
            {governorates.map(gov => (
              <option key={gov} value={gov}>{gov}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Data Table */}
      <div className="max-w-7xl mx-auto bg-white border border-gray-100 rounded-3xl shadow-[0_20px_40px_rgba(0,0,0,0.04)] overflow-hidden transition-all print:shadow-none print:border-none">

        {/* Print Header (Only visible in print) */}
        <div className="hidden print:block p-8 text-center border-b border-gray-200">
          <h1 className="text-2xl font-bold">كشف مديونيات العملاء</h1>
          <p className="text-gray-500">{selectedGov ? `محافظة: ${selectedGov}` : 'جميع المحافظات'}</p>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-right">
            <thead>
              <tr className="bg-gray-50/80 text-gray-500 text-sm">
                <th className="px-6 py-4 font-medium">اسم العميل</th>
                <th className="px-6 py-4 font-medium">المحافظة</th>
                <th className="px-6 py-4 font-medium">رقم الهاتف</th>
                <th className="px-6 py-4 font-medium text-left">إجمالي المديونية</th>
                <th className="px-6 py-4 font-medium text-center print:hidden">إجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {isLoading ? (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-gray-400">
                    <div className="w-6 h-6 border-2 border-blue-500 border-t-transparent rounded-full animate-spin mx-auto mb-2"></div>
                    جاري التحميل...
                  </td>
                </tr>
              ) : filteredCustomers.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-gray-400">
                    لا يوجد عملاء
                  </td>
                </tr>
              ) : (
                filteredCustomers.map(customer => (
                  <tr key={customer.id} className="hover:bg-blue-50/30 transition-colors group">
                    <td className="px-6 py-4">
                      <div className="font-semibold text-gray-800">{customer.name}</div>
                      <div className="text-xs text-gray-400 hidden print:block mt-1">{customer.address}</div>
                    </td>
                    <td className="px-6 py-4 text-gray-600">
                      <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-gray-100 text-gray-800">
                        {customer.governorate || 'غير محدد'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-gray-500 text-sm" dir="ltr">{customer.phone || '-'}</td>
                    <td className="px-6 py-4 text-left font-bold text-gray-900">
                      {Number(customer.balance).toFixed(2)}
                    </td>
                    <td className="px-6 py-4 text-center print:hidden">
                      <div className="flex items-center justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button 
                          data-id={customer.id}
                          onClick={handleEditCustomerClick}
                          className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                          title="تعديل قبل الطباعة"
                        >
                          <Edit2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
            {/* Total Footer */}
            {!isLoading && filteredCustomers.length > 0 && (
              <tfoot className="bg-gray-50">
                <tr>
                  <td colSpan={3} className="px-6 py-4 font-bold text-gray-700">الإجمالي العام</td>
                  <td className="px-6 py-4 text-left font-bold text-blue-600 text-lg">
                    {filteredCustomers.reduce((sum, c) => sum + Number(c.balance), 0).toFixed(2)}
                  </td>
                  <td className="print:hidden"></td>
                </tr>
              </tfoot>
            )}
          </table>
        </div>
      </div>

      {/* Modals */}
      {showBulkImport && (
        <BulkImportDropzone 
          onClose={handleCloseBulkImport}
          onSuccess={handleBulkImportSuccess}
        />
      )}

      {editingCustomer && (
        <PrePrintEditModal 
          customer={editingCustomer}
          onClose={handleCloseEditModal}
          onPrint={handlePrintEditModal}
        />
      )}

    </div>
  );
}
